        <!-- ════════════════════════════════
         CARD 12 — HORTON PLAINS
         Row 1: 60% text LEFT | 40% img RIGHT
         Row 2: 60% 3-images LEFT | 40% para RIGHT
    ════════════════════════════════ -->
        <div class="dest-card">
            <div class="dest-inner">

                <!-- ROW 1 -->
                <div class="dest-row row1-card2">

                    <!-- Left 60%: label + title + paragraphs -->
                    <div class="dest-col col-text">
                        <p class="dest-label"
                            data-en="HORTON PLAINS"
                            data-si="හෝර්ටන් තැන්න"
                            data-ta="HORTON PLAINS">HORTON PLAINS</p>
                        <h2 class="dest-title"
                            data-en="Horton Plains <em>National Park</em>"
                            data-si="හෝර්ටන් තැන්න <em>ජාතික වනෝද්‍යානය</em>"
                            data-ta="Horton Plains <em>Nationaal Park</em>">Horton Plains <em>National Park</em></h2>
                        <p class="dest-para"
                            data-en="Horton Plains lies at 2,100 to 2,300 meters elevation in Sri Lanka's Central Highlands. Originally called Maha Eliya, it was renamed after British Governor Sir Robert Wilmot Horton in the 19th century."
                            data-si="හෝර්ටන් තැන්න ශ්‍රී ලංකාවේ මධ්‍යම කඳුකරයේ මීටර් 2,100 සිට 2,300 දක්වා උන්නතාංශයක පිහිටා ඇත. මුලින් මහ එළිය ලෙස හඳුන්වන ලද මෙය, 19 වැනි සියවසේ බ්‍රිතාන්‍ය ආණ්ඩුකාර සර් රොබට් විල්මට් හෝර්ටන්ගේ නමින් නැවත නම් කරන ලදී."
                            data-ta="Horton Plains ligt op een hoogte van 2.100 tot 2.300 meter in het centrale hoogland van Sri Lanka. Oorspronkelijk Maha Eliya genoemd, werd het in de 19e eeuw vernoemd naar de Britse gouverneur Sir Robert Wilmot Horton.">Horton Plains lies at 2,100 to 2,300 meters elevation in Sri Lanka's Central Highlands. Originally called Maha Eliya, it was renamed after British Governor Sir Robert Wilmot Horton in the 19th century.</p>
                        <p class="dest-para"
                            data-en="The park covers 3,160 hectares and contains Kirigalpoththa and Totupolakanda, the second and third highest peaks in Sri Lanka. The Central Highlands were declared a UNESCO World Heritage Site in 2010."
                            data-si="මෙම වනෝද්‍යානය හෙක්ටයාර් 3,160ක් ආවරණය කරන අතර, ශ්‍රී ලංකාවේ දෙවැනි සහ තුන්වැනි උසම කඳු වන කිරිගල්පොත්ත සහ තොටුපොළ කන්ද ඇතුළත් වේ. 2010 දී මධ්‍යම කඳුකරය යුනෙස්කෝ ලෝක උරුම ස්ථානයක් ලෙස ප්‍රකාශයට පත් කරන ලදී."
                            data-ta="Het park beslaat 3.160 hectare en bevat Kirigalpoththa en Totupolakanda, de op een na en op twee na hoogste toppen van Sri Lanka. Het centrale hoogland werd in 2010 uitgeroepen tot UNESCO-Werelderfgoedlocatie.">The park covers 3,160 hectares and contains Kirigalpoththa and Totupolakanda, the second and third highest peaks in Sri Lanka. The Central Highlands were declared a UNESCO World Heritage Site in 2010.</p>
                        <p class="dest-para"
                            data-en="Vegetation consists of montane grasslands and evergreen cloud forests. Close to 750 plant species have been observed including dwarf bamboo, Myrtaceae, Lauraceae, ferns, lichens, and beautiful wild orchids."
                            data-si="වෘක්ෂලතාදිය කඳුකර තණබිම් සහ සදාහරිත වළාකුළු වනාන්තරවලින් සැදුම් ලැබේ. වාමන වේවැල්, මිර්ටේසී, ලෝරේසී, පර්ණ, ලයිකන් සහ සුන්දර වන ඕකිඩ් ඇතුළු ශාක විශේෂ 750කට ආසන්න ප්‍රමාණයක් නිරීක්ෂණය කර ඇත."
                            data-ta="De vegetatie bestaat uit graslanden in de bergen en altijdgroene wolkenwouden. Bijna 750 plantensoorten zijn waargenomen, waaronder dwergbamboe, Myrtaceae, Lauraceae, varens, korstmossen en prachtige wilde orchideeën.">Vegetation consists of montane grasslands and evergreen cloud forests. Close to 750 plant species have been observed including dwarf bamboo, Myrtaceae, Lauraceae, ferns, lichens, and beautiful wild orchids.</p>
                    </div>

                    <!-- Right 40%: single image -->
                    <div class="dest-col col-img">
                        <div class="main-img-wrap">
                            <img src="https://images.unsplash.com/photo-1506905925346-21bda4d32df4?w=700&q=80"
                                alt="HORTON PLAINS" />
                        </div>
                    </div>

                </div>

                <!-- ROW 2 -->
                <div class="dest-row row2-card2">

                    <!-- Left 60%: 3 images -->
                    <div class="dest-col col-imgs">
                        <div class="triple-imgs">
                            <div class="tri-img tri-img--sm">
                                <img src="https://images.unsplash.com/photo-1464822759023-fed622ff2c3b?w=400&q=80"
                                    alt="HORTON PLAINS" />
                            </div>
                            <div class="tri-img tri-img--wide">
                                <img src="https://images.unsplash.com/photo-1582510003544-4d00b7f74220?w=600&q=80"
                                    alt="HORTON PLAINS" />
                            </div>
                            <div class="tri-img tri-img--sm">
                                <img src="https://images.unsplash.com/photo-1567620905732-2d1ec7ab7445?w=400&q=80"
                                    alt="HORTON PLAINS" />
                            </div>
                        </div>
                    </div>

                    <!-- Right 40%: paragraph -->
                    <div class="dest-col col-text">
                        <p class="dest-para"
                            data-en="World's End is a sheer cliff with an 880-meter drop, while Baker's Falls cascades 20 meters through the forest. The circular hiking trail takes visitors past these dramatic viewpoints through mystical cloud forests."
                            data-si="වර්ල්ඩ්ස් එන්ඩ් යනු මීටර් 880ක බෑවුමක් සහිත සෘජු කඳු බෑවුමකි, බේකර්ස් ෆෝල්ස් වනාන්තරය හරහා මීටර් 20ක් කාස්කේඩ් වෙයි. වෘත්තාකාර කඳු මංතීරුව නරඹන්නන් අද්භූත වළාකුළු වනාන්තර හරහා මෙම නාටකීය දර්ශන ස්ථාන අසලින් ගෙන යයි."
                            data-ta="World's End is een steile rotswand met een val van 880 meter, terwijl Baker's Falls 20 meter door het bos cascadeert. Het ronde wandelpad voert bezoekers langs deze dramatische uitkijkpunten door mystieke wolkenwouden.">World's End is a sheer cliff with an 880-meter drop, while Baker's Falls cascades 20 meters through the forest. The circular hiking trail takes visitors past these dramatic viewpoints through mystical cloud forests.</p>
                        <p class="dest-para"
                            data-en="Temperatures reach 27 degrees by day but drop to 5 degrees at night with thick mist formation. It is the coldest and windiest place in Sri Lanka, creating a unique ecosystem found nowhere else on the island."
                            data-si="උෂ්ණත්වය දහවල් කාලයේ අංශක 27 දක්වා ළඟා වන නමුත් රාත්‍රියේ ඝන මීදුමක් සමඟ අංශක 5 දක්වා පහත වැටේ. එය ශ්‍රී ලංකාවේ වඩාත්ම සීතල හා සුළං සහිත ස්ථානය වන අතර, දූපතේ වෙනත් කොතැනකවත් නොමැති අනන්‍ය පරිසර පද්ධතියක් නිර්මාණය කරයි."
                            data-ta="Overdag bereiken de temperaturen 27 graden, maar 's nachts dalen ze tot 5 graden met dikke mistvorming. Het is de koudste en winderigste plek van Sri Lanka, wat een uniek ecosysteem creëert dat nergens anders op het eiland te vinden is.">Temperatures reach 27 degrees by day but drop to 5 degrees at night with thick mist formation. It is the coldest and windiest place in Sri Lanka, creating a unique ecosystem found nowhere else on the island.</p>
                    </div>

                </div>

            </div>
        </div>

        <!-- ════════════════════════════════
         CARD 13 — UDAWALAWE NATIONAL PARK
         Row 1: 40% img LEFT | 60% text RIGHT
         Row 2: 40% para LEFT | 60% 3-images RIGHT
    ════════════════════════════════ -->
        <div class="dest-card">
            <div class="dest-inner">

                <!-- ROW 1 -->
                <div class="dest-row row1-card1">

                    <!-- Left 40%: single image -->
                    <div class="dest-col col-img">
                        <div class="main-img-wrap">
                            <img src="https://images.unsplash.com/photo-1533050487297-09b450131914?w=700&q=80"
                                alt="UDAWALAWE NATIONAL PARK" />
                        </div>
                    </div>

                    <!-- Right 60%: label + title + paragraphs -->
                    <div class="dest-col col-text">
                        <p class="dest-label"
                            data-en="UDAWALAWE NATIONAL PARK"
                            data-si="උඩවලව ජාතික වනෝද්‍යානය"
                            data-ta="UDAWALAWE NATIONAAL PARK">UDAWALAWE NATIONAL PARK</p>
                        <h2 class="dest-title"
                            data-en="Udawalawe <em>Wildlife Safari</em>"
                            data-si="උඩවලව <em>වන සත්ව සෆාරිය</em>"
                            data-ta="Udawalawe <em>Wildsafari</em>">Udawalawe <em>Wildlife Safari</em></h2>
                        <p class="dest-para"
                            data-en="Udawalawe National Park covers approximately 308 square kilometers in southern Sri Lanka. Established in 1972, it was created to provide safe habitat for elephants displaced by the Udawalawe Reservoir construction."
                            data-si="උඩවලව ජාතික වනෝද්‍යානය දකුණු ශ්‍රී ලංකාවේ වර්ග කිලෝමීටර් 308ක් පමණ ආවරණය කරයි. 1972 දී ස්ථාපිත කරන ලද මෙය, උඩවලව ජලාශ ඉදිකිරීම නිසා අවතැන් වූ අලින්ට ආරක්ෂිත වාසභූමියක් ලබා දීම සඳහා නිර්මාණය කරන ලදී."
                            data-ta="Udawalawe National Park beslaat ongeveer 308 vierkante kilometer in het zuiden van Sri Lanka. Opgericht in 1972, werd het gecreëerd om een veilige habitat te bieden voor olifanten die verdreven waren door de bouw van het Udawalawe-reservoir.">Udawalawe National Park covers approximately 308 square kilometers in southern Sri Lanka. Established in 1972, it was created to provide safe habitat for elephants displaced by the Udawalawe Reservoir construction.</p>
                        <p class="dest-para"
                            data-en="The park is famous for its large Asian elephant population, often observed in herds of varying sizes. With over 500 elephants residing here, sightings are virtually guaranteed on any safari visit."
                            data-si="මෙම වනෝද්‍යානය එහි විශාල ආසියානු අලි ජනගහනය සඳහා ප්‍රසිද්ධය, බොහෝ විට විවිධ ප්‍රමාණයේ රංචු ලෙස නිරීක්ෂණය වෙයි. අලින් 500කට වැඩි සංඛ්‍යාවක් මෙහි වාසය කරන හෙයින්, ඕනෑම සෆාරි සංචාරයකදී දැකීම ආසන්න වශයෙන් සහතික වෙයි."
                            data-ta="Het park staat bekend om zijn grote populatie Aziatische olifanten, vaak waargenomen in kuddes van verschillende groottes. Met meer dan 500 olifanten die hier wonen, zijn waarnemingen vrijwel gegarandeerd bij elk safaribezoek.">The park is famous for its large Asian elephant population, often observed in herds of varying sizes. With over 500 elephants residing here, sightings are virtually guaranteed on any safari visit.</p>
                        <p class="dest-para"
                            data-en="Terrain blends open grasslands, marshes, scrublands, and pockets of dense forest. The Udawalawe Reservoir creates a dramatic backdrop, particularly beautiful during the golden hours of dawn and dusk."
                            data-si="භූමිය විවෘත තණබිම්, වගුරු බිම්, පඳුරු බිම් සහ ඝන වනාන්තර කොටස් මිශ්‍ර වෙයි. උඩවලව ජලාශය නාටකීය පසුබිමක් නිර්මාණය කරයි, විශේෂයෙන් අරුණෝදය හා සන්ධ්‍යා කාලයේ රන්වන් මොහොතේ සුන්දරත්වයෙන් යුක්ත වෙයි."
                            data-ta="Het terrein combineert open graslanden, moerassen, struikgewas en delen dicht bos. Het Udawalawe-reservoir creëert een dramatische achtergrond, vooral mooi tijdens de gouden uren van zonsopgang en schemering.">Terrain blends open grasslands, marshes, scrublands, and pockets of dense forest. The Udawalawe Reservoir creates a dramatic backdrop, particularly beautiful during the golden hours of dawn and dusk.</p>
                    </div>

                </div>

                <!-- ROW 2 -->
                <div class="dest-row row2-card1">

                    <!-- Left 40%: paragraph -->
                    <div class="dest-col col-text">
                        <p class="dest-para"
                            data-en="Other mammals include leopards, sloth bears, sambar deer, wild boars, and the endemic toque macaque. Over 210 bird species include the Sri Lanka grey hornbill, serpent eagle, and migratory painted storks."
                            data-si="වෙනත් ක්ෂීරපායීන් අතර දිවියන්, වලාහා, සම්බර් මුවන්, වල් ඌරන් සහ ආවේණික රිලවුන් ඇතුළත් වේ. පක්ෂි විශේෂ 210කට වැඩි ප්‍රමාණයක් අතර ශ්‍රී ලංකා අළු කොකරාල, නාග රාජාලි සහ සංක්‍රමණික චිත්‍ර ලේනලූවන් ඇතුළත් වේ."
                            data-ta="Andere zoogdieren zijn onder andere luipaarden, lippenberen, sambarherten, wilde zwijnen en de endemische macaque. Meer dan 210 vogelsoorten omvatten de Sri Lankaanse grijze neushoornvogel, slangenarend en migrerende verfooievaars.">Other mammals include leopards, sloth bears, sambar deer, wild boars, and the endemic toque macaque. Over 210 bird species include the Sri Lanka grey hornbill, serpent eagle, and migratory painted storks.</p>
                        <p class="dest-para"
                            data-en="The Elephant Transit Home on the park's outskirts cares for orphaned calves before wild reintroduction. Visitors watch baby elephant feedings from a viewing deck, observing these magnificent creatures without disturbing them."
                            data-si="වනෝද්‍යානයේ අයිනේ පිහිටි අලි සංක්‍රාන්ති නිවාසය, වනයට නැවත හඳුන්වා දීමට පෙර අනාථ අලි පැටවුන් රැක බලා ගනී. නරඹන්නන් නැරඹුම් වේදිකාවකින් අලි පැටවුන්ට ආහාර වේල් ලබා දීම නරඹන අතර, මෙම අතිමහත් සත්වයන් කරදර නොකර නිරීක්ෂණය කරති."
                            data-ta="Het Elephant Transit Home aan de rand van het park zorgt voor wees-kalveren voordat ze weer in het wild worden geïntroduceerd. Bezoekers kijken naar de voeding van babyolifanten vanaf een uitkijkplatform en observeren deze prachtige wezens zonder ze te storen.">The Elephant Transit Home on the park's outskirts cares for orphaned calves before wild reintroduction. Visitors watch baby elephant feedings from a viewing deck, observing these magnificent creatures without disturbing them.</p>
                    </div>

                    <!-- Right 60%: 3 images -->
                    <div class="dest-col col-imgs">
                        <div class="triple-imgs">
                            <div class="tri-img tri-img--sm">
                                <img src="https://images.unsplash.com/photo-1501854140801-50d01698950b?w=400&q=80"
                                    alt="UDAWALAWE NATIONAL PARK" />
                            </div>
