        <!-- ════════════════════════════════
         CARD 14 — BENTOTA BEACH
         Row 1: 60% text LEFT | 40% img RIGHT
         Row 2: 60% 3-images LEFT | 40% para RIGHT
    ════════════════════════════════ -->
        <div class="dest-card">
            <div class="dest-inner">

                <!-- ROW 1 -->
                <div class="dest-row row1-card2">

                    <!-- Left 60%: label + title + paragraphs -->
                    <div class="dest-col col-text">
                        <p class="dest-label"
                            data-en="BENTOTA BEACH"
                            data-si="බෙන්තොට වෙරළ"
                            data-ta="BENTOTA BEACH">BENTOTA BEACH</p>
                        <h2 class="dest-title"
                            data-en="Bentota Beach <em>Getaway</em>"
                            data-si="බෙන්තොට වෙරළ <em>විවේකස්ථානය</em>"
                            data-ta="Bentota Beach <em>Uitje</em>">Bentota Beach <em>Getaway</em></h2>
                        <p class="dest-para"
                            data-en="Bentota is a coastal town 65 kilometers south of Colombo, renowned for pristine golden beaches and calm turquoise waters. It has long been a favored destination for tourists seeking a peaceful beach retreat."
                            data-si="බෙන්තොට කොළඹින් කිලෝමීටර් 65ක් දකුණින් පිහිටි වෙරළබඩ නගරයකි, නොකැළැඹුණු රන් වර්ණ වෙරළ සහ සන්සුන් නිල් ජලය සඳහා ප්‍රසිද්ධය. සාමකාමී වෙරළ විවේකස්ථානයක් සොයන සංචාරකයින් සඳහා මෙය බොහෝ කලක සිට ප්‍රියතම ගමනාන්තයක්ව පවතී."
                            data-ta="Bentota is een kuststad 65 kilometer ten zuiden van Colombo, bekend om zijn ongerepte gouden stranden en rustige turquoise wateren. Het is al lang een geliefde bestemming voor toeristen op zoek naar een vredige strandvakantie.">Bentota is a coastal town 65 kilometers south of Colombo, renowned for pristine golden beaches and calm turquoise waters. It has long been a favored destination for tourists seeking a peaceful beach retreat.</p>
                        <p class="dest-para"
                            data-en="The Bentota River creates a unique lagoon environment perfect for water sports. Visitors enjoy jet skiing, windsurfing, banana boat rides, and river safaris in calm waters ideal for beginners and families."
                            data-si="බෙන්තොට ගඟ ජල ක්‍රීඩා සඳහා පරිපූර්ණ අනන්‍ය කලාප පරිසරයක් නිර්මාණය කරයි. නරඹන්නන් ආරම්භකයින්ට සහ පවුල්වලට පරිපූර්ණ සන්සුන් ජලයේ ජෙට් ස්කී ඊම්, විණ්ඩ්සර්ෆින්, කෙසෙල් බෝට්ටු ගමන් සහ ගඟ සෆාරි භුක්ති විඳිති."
                            data-ta="De Bentota-rivier creëert een unieke lagune-omgeving die perfect is voor watersporten. Bezoekers genieten van jetskiën, windsurfen, bananenboottochten en riviersafari's in rustige wateren, ideaal voor beginners en gezinnen.">The Bentota River creates a unique lagoon environment perfect for water sports. Visitors enjoy jet skiing, windsurfing, banana boat rides, and river safaris in calm waters ideal for beginners and families.</p>
                        <p class="dest-para"
                            data-en="The beach stretches for several kilometers with plenty of space for sunbathing, swimming, and long walks. Palm-fringed coastline provides natural shade, and gentle waves make it one of the safest swimming beaches."
                            data-si="වෙරළ කිලෝමීටර් කිහිපයක් දිගටම විහිදී ඇති අතර, හිරු රශ්මියට නාන, පිහිනීම සහ දිගු ඇවිදීම් සඳහා විශාල ඉඩක් ඇත. පොල් ගස් වැටුණු වෙරළ තීරය ස්වාභාවික සෙවණක් ලබා දෙන අතර, මෘදු රළ එය වඩාත්ම ආරක්ෂිත පිහිනුම් වෙරළවලින් එකක් කරයි."
                            data-ta="Het strand strekt zich uit over verschillende kilometers met veel ruimte om te zonnebaden, zwemmen en lange wandelingen te maken. De met palmbomen omzoomde kustlijn biedt natuurlijke schaduw, en zachte golven maken het een van de veiligste zwemstranden.">The beach stretches for several kilometers with plenty of space for sunbathing, swimming, and long walks. Palm-fringed coastline provides natural shade, and gentle waves make it one of the safest swimming beaches.</p>
                    </div>

                    <!-- Right 40%: single image -->
                    <div class="dest-col col-img">
                        <div class="main-img-wrap">
                            <img src="https://images.unsplash.com/photo-1506905925346-21bda4d32df4?w=700&q=80"
                                alt="BENTOTA BEACH" />
                        </div>
                    </div>

                </div>

                <!-- ROW 2 -->
                <div class="dest-row row2-card2">

                    <!-- Left 60%: 3 images -->
                    <div class="dest-col col-imgs">
                        <div class="triple-imgs">
                            <div class="tri-img tri-img--sm">
                                <img src="https://images.unsplash.com/photo-1464822759023-fed622ff2c3b?w=400&q=80"
                                    alt="BENTOTA BEACH" />
                            </div>
                            <div class="tri-img tri-img--wide">
                                <img src="https://images.unsplash.com/photo-1582510003544-4d00b7f74220?w=600&q=80"
                                    alt="BENTOTA BEACH" />
                            </div>
                            <div class="tri-img tri-img--sm">
                                <img src="https://images.unsplash.com/photo-1567620905732-2d1ec7ab7445?w=400&q=80"
                                    alt="BENTOTA BEACH" />
                            </div>
                        </div>
                    </div>

                    <!-- Right 40%: paragraph -->
                    <div class="dest-col col-text">
                        <p class="dest-para"
                            data-en="Bentota is known for Ayurvedic wellness centers and spa resorts offering traditional Sri Lankan healing therapies. Luxury hotels line the beach with world-class amenities while maintaining natural coastal beauty."
                            data-si="බෙන්තොට සාම්ප්‍රදායික ශ්‍රී ලාංකික සුව චිකිත්සා ලබා දෙන ආයුර්වේද සුවතා මධ්‍යස්ථාන සහ ස්පා නිවාඩු නිකේතන සඳහා ප්‍රසිද්ධය. සුඛෝපභෝගී හෝටල් වෙරළ ඔස්සේ ස්වාභාවික වෙරළබඩ සුන්දරත්වය පවත්වාගෙන ලෝක මට්ටමේ පහසුකම් සමඟ පෙළගැසී ඇත."
                            data-ta="Bentota staat bekend om Ayurvedische wellnesscentra en spa-resorts die traditionele Sri Lankaanse geneeswijzen aanbieden. Luxe hotels staan langs het strand met faciliteiten van wereldklasse, terwijl de natuurlijke kustschoonheid behouden blijft.">Bentota is known for Ayurvedic wellness centers and spa resorts offering traditional Sri Lankan healing therapies. Luxury hotels line the beach with world-class amenities while maintaining natural coastal beauty.</p>
                        <p class="dest-para"
                            data-en="The nearby Brief Garden by landscape architect Bevis Bawa is a hidden gem worth visiting. This enchanting garden features sculptures, pavilions, and tropical plants arranged in beautiful outdoor rooms."
                            data-si="භූ දර්ශන ගෘහ නිර්මාණ ශිල්පී බෙවිස් බාවා විසින් නිර්මාණය කරන ලද ආසන්න බ්‍රීෆ් උද්‍යානය නැරඹීමට වටිනා සැඟවුණු මැණිකකි. මෙම අලංකාර උද්‍යානයේ චිත්‍ර ශිල්ප, මණ්ඩප සහ නිවර්තන ශාක සුන්දර එළිමහන් කාමරවල සකස් කර ඇත."
                            data-ta="De nabijgelegen Brief Garden van landschapsarchitect Bevis Bawa is een verborgen parel die het bezoeken waard is. Deze betoverende tuin bevat sculpturen, paviljoenen en tropische planten gerangschikt in prachtige buitenkamers.">The nearby Brief Garden by landscape architect Bevis Bawa is a hidden gem worth visiting. This enchanting garden features sculptures, pavilions, and tropical plants arranged in beautiful outdoor rooms.</p>
                    </div>

                </div>

            </div>
        </div>

        <!-- ════════════════════════════════
         CARD 15 — NUWARA ELIYA
         Row 1: 40% img LEFT | 60% text RIGHT
         Row 2: 40% para LEFT | 60% 3-images RIGHT
    ════════════════════════════════ -->
        <div class="dest-card">
            <div class="dest-inner">

                <!-- ROW 1 -->
                <div class="dest-row row1-card1">

                    <!-- Left 40%: single image -->
                    <div class="dest-col col-img">
                        <div class="main-img-wrap">
                            <img src="https://images.unsplash.com/photo-1533050487297-09b450131914?w=700&q=80"
                                alt="NUWARA ELIYA" />
                        </div>
                    </div>

                    <!-- Right 60%: label + title + paragraphs -->
                    <div class="dest-col col-text">
                        <p class="dest-label"
                            data-en="NUWARA ELIYA"
                            data-si="නුවරඑළිය"
                            data-ta="NUWARA ELIYA">NUWARA ELIYA</p>
                        <h2 class="dest-title"
                            data-en="Nuwara Eliya <em>Little England</em>"
                            data-si="නුවරඑළිය <em>කුඩා එංගලන්තය</em>"
                            data-ta="Nuwara Eliya <em>Klein Engeland</em>">Nuwara Eliya <em>Little England</em></h2>
                        <p class="dest-para"
                            data-en="Nuwara Eliya is often called Little England by the tourist industry. Winding roads through lush green valleys and tea estates lead to a town offering a typical English environment in the tropics."
                            data-si="නුවරඑළිය බොහෝ විට සංචාරක කර්මාන්තය විසින් කුඩා එංගලන්තය ලෙස හඳුන්වනු ලබයි. සශ්‍රීක කොළ පැහැති නිම්න සහ තේ වතු හරහා ඇලීගිය මාර්ග, නිවර්තන කලාපයේ සාමාන්‍ය ඉංග්‍රීසි පරිසරයක් ලබා දෙන නගරයකට ගමන් කරයි."
                            data-ta="Nuwara Eliya wordt door de toeristenindustrie vaak Klein Engeland genoemd. Slingerende wegen door weelderige groene valleien en theeplantages leiden naar een stadje dat een typisch Engelse omgeving in de tropen biedt.">Nuwara Eliya is often called Little England by the tourist industry. Winding roads through lush green valleys and tea estates lead to a town offering a typical English environment in the tropics.</p>
                        <p class="dest-para"
                            data-en="Its unique climate features early morning mist, cold tangy air, and a fresh invigorating atmosphere. The town has a golf course, race course, horses, rose gardens, and charming British-style houses throughout."
                            data-si="මෙහි අනන්‍ය දේශගුණයේ අධික උදෑසන මීදුම, සීතල තියුණු වාතය සහ නැවුම් ස්ඵූර්තිමත් වාතාවරණයක් ඇත. නගරයේ ගොල්ෆ් පිටිය, තරග පිටිය, අශ්වයින්, රෝස උද්‍යාන සහ පුරාම අලංකාර බ්‍රිතාන්‍ය විලාසිතාවේ නිවාස ඇත."
                            data-ta="Het unieke klimaat kenmerkt zich door vroege ochtendmist, koude, frisse lucht en een verkwikkende sfeer. Het stadje heeft een golfbaan, renbaan, paarden, rozentuinen en charmante huizen in Britse stijl door het hele gebied.">Its unique climate features early morning mist, cold tangy air, and a fresh invigorating atmosphere. The town has a golf course, race course, horses, rose gardens, and charming British-style houses throughout.</p>
                        <p class="dest-para"
                            data-en="Planned by the British and declared a town in 1828, the pink brick Victorian Post Office remains a landmark. The golf course blends beautifully with surrounding tea plantations, fauna, and flora."
                            data-si="බ්‍රිතාන්‍යයන් විසින් සැලසුම් කොට 1828 දී නගරයක් ලෙස ප්‍රකාශයට පත් කරන ලද, රෝස පැහැති ගඩොල්වලින් සැදුම් ලද වික්ටෝරියානු තැපැල් කාර්යාලය මෙතෙක්ම සන්ධිස්ථානයක්ව පවතී. ගොල්ෆ් පිටිය අවට තේ වතු, සත්ව හා වෘක්ෂලතාදිය සමඟ අලංකාර ලෙස මිශ්‍ර වෙයි."
                            data-ta="Het Victoriaanse postkantoor van roze baksteen, gepland door de Britten en in 1828 tot stad uitgeroepen, blijft een bezienswaardigheid. De golfbaan versmelt prachtig met de omliggende theeplantages, fauna en flora.">Planned by the British and declared a town in 1828, the pink brick Victorian Post Office remains a landmark. The golf course blends beautifully with surrounding tea plantations, fauna, and flora.</p>
                    </div>

                </div>

                <!-- ROW 2 -->
                <div class="dest-row row2-card1">

                    <!-- Left 40%: paragraph -->
                    <div class="dest-col col-text">
                        <p class="dest-para"
                            data-en="Many locals visit during April and May, the warmest months, when Colombo's elite seek cool relief. Most British visitors feel they are in England, hence the nickname given by foreign visitors over the years."
                            data-si="කොළඹ ප්‍රභූවරුන් සිසිල් සහනයක් සොයන, වඩාත්ම උණුසුම් මාස වන අප්‍රේල් සහ මැයි මාසවලදී බොහෝ ප්‍රාදේශීයයන් සංචාරය කරති. බොහෝ බ්‍රිතාන්‍ය නරඹන්නන් ඔවුන් එංගලන්තයේ සිටින බව හැඟෙන අතර, එයින් වසර ගණනාවක් තිස්සේ විදේශීය නරඹන්නන් විසින් ලබා දුන් අන්වර්ථ නාමයකි."
                            data-ta="Veel lokale bewoners bezoeken in april en mei, de warmste maanden, wanneer de elite van Colombo verkoeling zoekt. De meeste Britse bezoekers voelen zich alsof ze in Engeland zijn, vandaar de bijnaam die buitenlandse bezoekers door de jaren heen hebben gegeven.">Many locals visit during April and May, the warmest months, when Colombo's elite seek cool relief. Most British visitors feel they are in England, hence the nickname given by foreign visitors over the years.</p>
                        <p class="dest-para"
                            data-en="Visitors enjoy fresh vegetables and leisurely walks around beautiful Lake Gregory with stunning scenery. Rugged mountains outlined against clear blue skies create a breathtaking backdrop in this charming hill station."
                            data-si="නරඹන්නන් නැවුම් එළවළු සහ සුන්දර ග්‍රෙගරි විල වටා සිදුවන සැහැල්ලු ඇවිදීම් භුක්ති විඳිති. නිල් අහස හරහා හැඩගැන්වුණු රළු කඳු මෙම ආකර්ෂණීය කඳුකර නගරයේ සිත් ගන්නා පසුබිමක් නිර්මාණය කරයි."
                            data-ta="Bezoekers genieten van verse groenten en ontspannen wandelingen rond het prachtige Lake Gregory met adembenemende landschappen. Ruige bergen, afgetekend tegen een heldere blauwe lucht, creëren een adembenemende achtergrond in dit charmante heuvelstation.">Visitors enjoy fresh vegetables and leisurely walks around beautiful Lake Gregory with stunning scenery. Rugged mountains outlined against clear blue skies create a breathtaking backdrop in this charming hill station.</p>
                    </div>

