        <!-- ════════════════════════════════
         CARD 16 — ARUGAM BAY
         Row 1: 60% text LEFT | 40% img RIGHT
         Row 2: 60% 3-images LEFT | 40% para RIGHT
    ════════════════════════════════ -->
        <div class="dest-card">
            <div class="dest-inner">

                <!-- ROW 1 -->
                <div class="dest-row row1-card2">

                    <!-- Left 60%: label + title + paragraphs -->
                    <div class="dest-col col-text">
                        <p class="dest-label"
                            data-en="ARUGAM BAY"
                            data-si="අරුගම් බොක්ක"
                            data-ta="ARUGAM BAY">ARUGAM BAY</p>
                        <h2 class="dest-title"
                            data-en="Arugam Bay <em>Surf Paradise</em>"
                            data-si="අරුගම් බොක්ක <em>රළ පැදීමේ පාරාදීසය</em>"
                            data-ta="Arugam Bay <em>Surfparadijs</em>">Arugam Bay <em>Surf Paradise</em></h2>
                        <p class="dest-para"
                            data-en="Arugam Bay is the jewel of Sri Lanka's surf towns with beautiful right-hand point breaks for every level. It makes Sri Lanka an all-round surf destination with rideable conditions spread across the island year-round."
                            data-si="අරුගම් බොක්ක යනු සෑම මට්ටමකටම සුදුසු සුන්දර දකුණු අත් වරප් ඛණ්ඩ සහිත ශ්‍රී ලංකාවේ රළ පැදීමේ නගරවල මැණිකයි. එය ශ්‍රී ලංකාව වර්ෂය පුරාම දූපත පුරා ව්‍යාප්ත වූ පැදීමට හැකි තත්ත්වයන් සහිත සමස්ථ රළ පැදීමේ ගමනාන්තයක් කරයි."
                            data-ta="Arugam Bay is het kroonjuweel van de surfsteden van Sri Lanka met prachtige rechtse point breaks voor elk niveau. Het maakt Sri Lanka tot een veelzijdige surfbestemming met rijdbare omstandigheden verspreid over het hele eiland, het hele jaar door.">Arugam Bay is the jewel of Sri Lanka's surf towns with beautiful right-hand point breaks for every level. It makes Sri Lanka an all-round surf destination with rideable conditions spread across the island year-round.</p>
                        <p class="dest-para"
                            data-en="Point breaks like Main Point and Whiskey Point offer long right-hand peels running up to 400 meters. The atmosphere during peak season is electric with beachfront cafes and international travelers enjoying the waves."
                            data-si="මේන් පොයින්ට් සහ විස්කි පොයින්ට් වැනි පොයින්ට් බ්‍රේක් මීටර් 400ක් දක්වා දිවෙන දිගු දකුණු අත් රළ ලබා දෙයි. උච්ච සමයේ වෙරළ ඉදිරිපස කැෆේ සහ ජාත්‍යන්තර සංචාරකයින් රළ භුක්ති විඳිමින් සිටින විට වාතාවරණය ඉතා සජීවී වෙයි."
                            data-ta="Point breaks zoals Main Point en Whiskey Point bieden lange rechtse golven van wel 400 meter. De sfeer tijdens het hoogseizoen is elektrisch, met strandcafés en internationale reizigers die van de golven genieten.">Point breaks like Main Point and Whiskey Point offer long right-hand peels running up to 400 meters. The atmosphere during peak season is electric with beachfront cafes and international travelers enjoying the waves.</p>
                        <p class="dest-para"
                            data-en="Whether you are an expert chasing barrels or a beginner at Baby Point, the warm water means no wetsuit needed. Surfboard rentals and experienced instructors cater to all skill levels throughout the season."
                            data-si="ඔබ බැරල් සොයන විදග්ධයෙකු වුවද හෝ බේබි පොයින්ට් හි ආරම්භකයෙකු වුවද, උණුසුම් ජලය යනු වෙට්සූට් අවශ්‍ය නොවන බවය. රළ පැදීමේ පුවරු කුලියට ගැනීම් සහ පළපුරුදු උපදේශකයින් සමයේ පුරාම සියලුම නිපුණතා මට්ටම් සඳහා සේවාසලසති."
                            data-ta="Of je nu een expert bent die op zoek is naar barrels of een beginner bij Baby Point, het warme water betekent dat er geen wetsuit nodig is. Surfplankverhuur en ervaren instructeurs bedienen alle vaardigheidsniveaus gedurende het seizoen.">Whether you are an expert chasing barrels or a beginner at Baby Point, the warm water means no wetsuit needed. Surfboard rentals and experienced instructors cater to all skill levels throughout the season.</p>
                    </div>

                    <!-- Right 40%: single image -->
                    <div class="dest-col col-img">
                        <div class="main-img-wrap">
                            <img src="https://images.unsplash.com/photo-1506905925346-21bda4d32df4?w=700&q=80"
                                alt="ARUGAM BAY" />
