                    </div>

                    <!-- Right 40%: paragraph -->
                    <div class="dest-col col-text">
                        <p class="dest-para"
                            data-en="Beyond surfing, Arugam Bay offers lagoon tours, wildlife safaris to Kumana National Park, and yoga retreats. Peanut Farm Beach provides a more secluded experience away from the main break."
                            data-si="රළ පැදීමෙන් ඔබ්බට, අරුගම් බොක්ක කලාප සංචාර, කුමන ජාතික වනෝද්‍යානයට වන සත්ව සෆාරි සහ යෝග විවේකස්ථාන ලබා දෙයි. පීනට් ෆාම් වෙරළ ප්‍රධාන රළ ඛණ්ඩයෙන් වෙන්ව වඩාත් හුදකලා අත්දැකීමක් ලබා දෙයි."
                            data-ta="Naast surfen biedt Arugam Bay lagune-tochten, safari's naar Kumana National Park en yogaretraites. Peanut Farm Beach biedt een meer afgezonderde ervaring, weg van de hoofdgolf.">Beyond surfing, Arugam Bay offers lagoon tours, wildlife safaris to Kumana National Park, and yoga retreats. Peanut Farm Beach provides a more secluded experience away from the main break.</p>
                        <p class="dest-para"
                            data-en="The best time to visit is May to September when the east coast enjoys dry season and consistent swells. Surf competitions, beach parties, and a vibrant international community create an unforgettable atmosphere."
                            data-si="නැගෙනහිර වෙරළ වියළි කාලයක් සහ අඛණ්ඩ රළ භුක්ති විඳින මැයි සිට සැප්තැම්බර් දක්වා කාලය වඩාත්ම සුදුසු සංචාරක කාලයයි. රළ පැදීමේ තරග, වෙරළ සාද සහ සජීවී ජාත්‍යන්තර ප්‍රජාවක් අමතක නොවන වාතාවරණයක් නිර්මාණය කරයි."
                            data-ta="De beste tijd om te bezoeken is mei tot september, wanneer de oostkust een droog seizoen en consistente deining geniet. Surfwedstrijden, strandfeesten en een levendige internationale gemeenschap creëren een onvergetelijke sfeer.">The best time to visit is May to September when the east coast enjoys dry season and consistent swells. Surf competitions, beach parties, and a vibrant international community create an unforgettable atmosphere.</p>
                    </div>

                </div>

            </div>
