        <!-- ════════════════════════════════
         CARD 17 — TRINCOMALEE
         Row 1: 40% img LEFT | 60% text RIGHT
         Row 2: 40% para LEFT | 60% 3-images RIGHT
    ════════════════════════════════ -->
        <div class="dest-card">
            <div class="dest-inner">

                <!-- ROW 1 -->
                <div class="dest-row row1-card1">

                    <!-- Left 40%: single image -->
                    <div class="dest-col col-img">
                        <div class="main-img-wrap">
                            <img src="https://images.unsplash.com/photo-1533050487297-09b450131914?w=700&q=80"
                                alt="TRINCOMALEE" />
                        </div>
                    </div>

                    <!-- Right 60%: label + title + paragraphs -->
                    <div class="dest-col col-text">
                        <p class="dest-label"
                            data-en="TRINCOMALEE"
                            data-si="ත්‍රිකුණාමලය"
                            data-ta="TRINCOMALEE">TRINCOMALEE</p>
                        <h2 class="dest-title"
                            data-en="Trincomalee <em>Coastal Gem</em>"
                            data-si="ත්‍රිකුණාමලය <em>වෙරළ මැණික</em>"
                            data-ta="Trincomalee <em>Kustparel</em>">Trincomalee <em>Coastal Gem</em></h2>
                        <p class="dest-para"
                            data-en="Trincomalee is a port city on Sri Lanka's northeast coast with one of the largest natural harbors in the world. It has been a strategic maritime hub for centuries, attracting traders and naval powers globally."
                            data-si="ත්‍රිකුණාමලය ශ්‍රී ලංකාවේ ඊසාන දිග වෙරළේ පිහිටි ලෝකයේ විශාලතම ස්වාභාවික වරායන්ගෙන් එකක් සහිත වරාය නගරයකි. එය සියවස් ගණනක් තිස්සේ උපායමාර්ගික සමුද්‍ර කේන්ද්‍රස්ථානයක්ව පවතින අතර, ලොව පුරා වෙළෙන්දන් සහ නාවික බලවතුන් ආකර්ෂණය කරයි."
                            data-ta="Trincomalee is een havenstad aan de noordoostkust van Sri Lanka met een van de grootste natuurlijke havens ter wereld. Het is al eeuwenlang een strategisch maritiem knooppunt, dat handelaren en marinemachten wereldwijd aantrekt.">Trincomalee is a port city on Sri Lanka's northeast coast with one of the largest natural harbors in the world. It has been a strategic maritime hub for centuries, attracting traders and naval powers globally.</p>
                        <p class="dest-para"
                            data-en="The district features untouched coastlines with Nilaveli Beach prime for whale watching and diving. The Koneswaram Temple perched on Swami Rock is one of the most important Hindu temples in Sri Lanka."
                            data-si="මෙම දිස්ත්‍රික්කයේ තල්මසුන් නැරඹීම සහ කිමිදීම සඳහා වඩාත්ම සුදුසු නිලාවැලි වෙරළ සහිත නොවලහන වෙරළ තීරයන් ඇත. ස්වාමි පර්වතයේ පිහිටි කෝණේශ්වරම් කෝවිල ශ්‍රී ලංකාවේ වඩාත්ම වැදගත් හින්දු කෝවිල්වලින් එකකි."
                            data-ta="Het district heeft ongerepte kustlijnen met Nilaveli Beach, ideaal voor walvisspotten en duiken. De Koneswaram-tempel, gelegen op Swami Rock, is een van de belangrijkste hindoetempels van Sri Lanka.">The district features untouched coastlines with Nilaveli Beach prime for whale watching and diving. The Koneswaram Temple perched on Swami Rock is one of the most important Hindu temples in Sri Lanka.</p>
                        <p class="dest-para"
                            data-en="Trincomalee offers diversity, culture, and religion through sites like Koneswaram Temple and Fort Frederick. This colonial-era fort was built by the Portuguese and later occupied by the Dutch and British."
                            data-si="ත්‍රිකුණාමලය කෝණේශ්වරම් කෝවිල සහ ෆ්‍රෙඩ්රික් බලකොටුව වැනි ස්ථාන හරහා විවිධත්වය, සංස්කෘතිය සහ ආගම ලබා දෙයි. මෙම යටත් විජිත යුගයේ බලකොටුව පෘතුගීසීන් විසින් ඉදිකරන ලද අතර පසුව හොලන්දකරුවන් සහ බ්‍රිතාන්‍යයන් විසින් අත්පත් කරගත්තේය."
                            data-ta="Trincomalee biedt diversiteit, cultuur en religie via plekken zoals de Koneswaram-tempel en Fort Frederick. Dit fort uit het koloniale tijdperk werd gebouwd door de Portugezen en later bezet door de Nederlanders en Britten.">Trincomalee offers diversity, culture, and religion through sites like Koneswaram Temple and Fort Frederick. This colonial-era fort was built by the Portuguese and later occupied by the Dutch and British.</p>
                    </div>

                </div>

                <!-- ROW 2 -->
                <div class="dest-row row2-card1">

                    <!-- Left 40%: paragraph -->
                    <div class="dest-col col-text">
                        <p class="dest-para"
                            data-en="Pigeon Island National Park off Nilaveli is a marine sanctuary famous for coral reefs and snorkeling. Visitors swim alongside black-tip reef sharks and sea turtles in crystal-clear waters."
                            data-si="නිලාවැලියට ආසන්නයේ පිහිටි පරවි දූපත් ජාතික වනෝද්‍යානය කොරල් පර සහ ස්නෝකලිං සඳහා ප්‍රසිද්ධ සමුද්‍ර අභයභූමියකි. නරඹන්නන් කැටපත් වැනි ජලයේ කළු තුඩු සහිත සුළු මෝරුන් සහ මුහුදු කැස්බෑවුන් සමඟ පිහිනති."
                            data-ta="Pigeon Island National Park, voor de kust van Nilaveli, is een mariene reservaat bekend om koraalriffen en snorkelen. Bezoekers zwemmen samen met zwartpuntrifhaaien en zeeschildpadden in kristalhelder water.">Pigeon Island National Park off Nilaveli is a marine sanctuary famous for coral reefs and snorkeling. Visitors swim alongside black-tip reef sharks and sea turtles in crystal-clear waters.</p>
                        <p class="dest-para"
                            data-en="Uppuveli Beach is the best area to stay, with a calm vibe and trendy restaurants. From here you can easily reach Nilaveli Beach or Fort Frederick, making Trincomalee ideal for beach lovers and history enthusiasts."
                            data-si="උප්පුවැලි වෙරළ නවාතැන් ගැනීමට වඩාත්ම සුදුසු ප්‍රදේශය වන අතර, සන්සුන් වාතාවරණයක් සහ නවීන අවන්හල් ඇත. මෙතැනින් ඔබට පහසුවෙන් නිලාවැලි වෙරළ හෝ ෆ්‍රෙඩ්රික් බලකොටුව වෙත ළඟා විය හැකි අතර, එමඟින් ත්‍රිකුණාමලය වෙරළ ලෝලීන්ට හා ඉතිහාස ලෝලීන්ට පරිපූර්ණ වෙයි."
                            data-ta="Uppuveli Beach is het beste gebied om te verblijven, met een rustige sfeer en trendy restaurants. Van hieruit bereik je gemakkelijk Nilaveli Beach of Fort Frederick, waardoor Trincomalee ideaal is voor strandliefhebbers en geschiedenisliefhebbers.">Uppuveli Beach is the best area to stay, with a calm vibe and trendy restaurants. From here you can easily reach Nilaveli Beach or Fort Frederick, making Trincomalee ideal for beach lovers and history enthusiasts.</p>
                    </div>

