        <!-- ════════════════════════════════
         CARD 18 — JAFFNA
         Row 1: 60% text LEFT | 40% img RIGHT
         Row 2: 60% 3-images LEFT | 40% para RIGHT
    ════════════════════════════════ -->
        <div class="dest-card">
            <div class="dest-inner">

                <!-- ROW 1 -->
                <div class="dest-row row1-card2">

                    <!-- Left 60%: label + title + paragraphs -->
                    <div class="dest-col col-text">
                        <p class="dest-label"
                            data-en="JAFFNA"
                            data-si="යාපනය"
                            data-ta="JAFFNA">JAFFNA</p>
                        <h2 class="dest-title"
                            data-en="Jaffna <em>Northern Capital</em>"
                            data-si="යාපනය <em>උතුරු අගනුවර</em>"
                            data-ta="Jaffna <em>Noordelijke Hoofdstad</em>">Jaffna <em>Northern Capital</em></h2>
                        <p class="dest-para"
                            data-en="Jaffna was Sri Lanka's second city and the symbolic capital of the northern region. It is a busy, mercantile place with a dense commercial center and quieter leafy periphery, ideally explored by bicycle."
                            data-si="යාපනය ශ්‍රී ලංකාවේ දෙවැනි නගරය වූ අතර, උතුරු ප්‍රදේශයේ සංකේතාත්මක අගනුවර විය. එය ඝන වාණිජ මධ්‍යස්ථානයක් සහ සන්සුන් කොළපැහැති වටපිටාවක් සහිත කාර්යබහුල වෙළඳ ස්ථානයක් වන අතර, පාගවියකින් ගවේෂණය කිරීමට වඩාත්ම සුදුසුය."
                            data-ta="Jaffna was de tweede stad van Sri Lanka en de symbolische hoofdstad van het noordelijke gebied. Het is een druk, commercieel oord met een dicht zakencentrum en een rustigere, groene periferie, ideaal te verkennen per fiets.">Jaffna was Sri Lanka's second city and the symbolic capital of the northern region. It is a busy, mercantile place with a dense commercial center and quieter leafy periphery, ideally explored by bicycle.</p>
                        <p class="dest-para"
                            data-en="The New Market Complex stands at Jaffna's bustling heart, a two-storey structure clad in luminous ochre. Shaded courtyards open onto food markets and the bus station, creating a vibrant trading hub."
                            data-si="නව වෙළඳපොළ සංකීර්ණය යාපනයේ ක්‍රියාශීලි හදවතේ පිහිටා ඇත, එය ආලෝකවත් ඔචර් වර්ණයෙන් ආවරණය වූ ද්විමහල් ගොඩනැගිල්ලකි. සෙවණැලි ඇති මංසන්ධි ආහාර වෙළඳපොළවලට සහ බස් නැවතුම්පොළට විවෘත වන අතර, සජීවී වෙළඳ කේන්ද්‍රස්ථානයක් නිර්මාණය කරයි."
                            data-ta="Het New Market Complex staat in het bruisende hart van Jaffna, een tweeverdiepingen tellend bouwwerk bekleed met lichtgevend okergeel. Schaduwrijke binnenplaatsen openen zich naar voedselmarkten en het busstation, wat een levendig handelsknooppunt creëert.">The New Market Complex stands at Jaffna's bustling heart, a two-storey structure clad in luminous ochre. Shaded courtyards open onto food markets and the bus station, creating a vibrant trading hub.</p>
                        <p class="dest-para"
                            data-en="The Nallur Kandaswamy Devasthanam is one of the most revered Hindu temples in the area, dedicated to Kartikeya. Over 500 Hindu temples in Jaffna make it a significant center of Tamil religious culture."
                            data-si="නල්ලූර් කන්දස්වාමි දේවස්ථානම් ප්‍රදේශයේ වඩාත්ම ගරු කරන හින්දු කෝවිල්වලින් එකකි, එය කාර්තිකේය දෙවියන්ට කැප කර ඇත. යාපනයේ හින්දු කෝවිල් 500කට වැඩි ප්‍රමාණයක් ඇති නිසා, එය දෙමළ ආගමික සංස්කෘතියේ වැදගත් කේන්ද්‍රස්ථානයක් කරයි."
                            data-ta="De Nallur Kandaswamy Devasthanam is een van de meest vereerde hindoetempels in het gebied, gewijd aan Kartikeya. Met meer dan 500 hindoetempels in Jaffna is het een belangrijk centrum van de Tamil religieuze cultuur.">The Nallur Kandaswamy Devasthanam is one of the most revered Hindu temples in the area, dedicated to Kartikeya. Over 500 Hindu temples in Jaffna make it a significant center of Tamil religious culture.</p>
                    </div>

