                                <img src="https://images.unsplash.com/photo-1582510003544-4d00b7f74220?w=600&q=80"
                                    alt="JAFFNA" />
                            </div>
                            <div class="tri-img tri-img--sm">
                                <img src="https://images.unsplash.com/photo-1567620905732-2d1ec7ab7445?w=400&q=80"
                                    alt="JAFFNA" />
                            </div>
                        </div>
                    </div>

                    <!-- Right 40%: paragraph -->
                    <div class="dest-col col-text">
                        <p class="dest-para"
                            data-en="The Jaffna Library, once one of Asia's largest with nearly 100,000 books, was burned in 1981. Today restored and reopened, it stands as an architectural landmark and symbol of resilience."
                            data-si="යාපන පුස්තකාලය, වරෙක පොත් 100,000කට ආසන්න ප්‍රමාණයක් සහිත ආසියාවේ විශාලතම පුස්තකාලයන්ගෙන් එකක්ව තිබූ අතර, 1981 දී ගිනිබත් කරන ලදී. අද වන විට ප්‍රතිසංස්කරණය කොට නැවත විවෘත කරන ලද එය, ගෘහ නිර්මාණ සන්ධිස්ථානයක් සහ ඔරෝපිරිමියාවේ සංකේතයක් ලෙස නැගී සිටී."
                            data-ta="De Jaffna-bibliotheek, ooit een van de grootste van Azië met bijna 100.000 boeken, werd in 1981 platgebrand. Vandaag gerestaureerd en heropend, staat het als een architectonisch baken en symbool van veerkracht.">The Jaffna Library, once one of Asia's largest with nearly 100,000 books, was burned in 1981. Today restored and reopened, it stands as an architectural landmark and symbol of resilience.</p>
                        <p class="dest-para"
                            data-en="War scars remain visible yet the city rebuilds with determination. Jaffna offers a unique cultural experience distinct from the rest of Sri Lanka, with Tamil heritage, delicious cuisine, and warm hospitality."
                            data-si="යුද්ධයේ කැලැල් තවමත් දැකගත හැකි වුවද, නගරය නිශ්චිත අධිෂ්ඨානයකින් නැවත ගොඩනඟා ගනී. යාපනය ශ්‍රී ලංකාවේ අනෙකුත් ප්‍රදේශවලින් වෙනස් වූ අනන්‍ය සංස්කෘතික අත්දැකීමක් ලබා දෙයි, දෙමළ උරුමය, රසවත් ආහාර හා උණුසුම් ආගන්තුක සත්කාරය සමඟ."
                            data-ta="Littekens van de oorlog blijven zichtbaar, maar de stad herbouwt zich met vastberadenheid. Jaffna biedt een unieke culturele ervaring die zich onderscheidt van de rest van Sri Lanka, met Tamil-erfgoed, heerlijke keuken en warme gastvrijheid.">War scars remain visible yet the city rebuilds with determination. Jaffna offers a unique cultural experience distinct from the rest of Sri Lanka, with Tamil heritage, delicious cuisine, and warm hospitality.</p>
                    </div>

                </div>

            </div>
        </div>

        <!-- ════════════════════════════════
         CARD 19 — SINHARAJA FOREST
         Row 1: 40% img LEFT | 60% text RIGHT
         Row 2: 40% para LEFT | 60% 3-images RIGHT
    ════════════════════════════════ -->
        <div class="dest-card">
            <div class="dest-inner">

                <!-- ROW 1 -->
                <div class="dest-row row1-card1">

                    <!-- Left 40%: single image -->
                    <div class="dest-col col-img">
                        <div class="main-img-wrap">
                            <img src="https://images.unsplash.com/photo-1533050487297-09b450131914?w=700&q=80"
                                alt="SINHARAJA FOREST" />
                        </div>
                    </div>

                    <!-- Right 60%: label + title + paragraphs -->
                    <div class="dest-col col-text">
                        <p class="dest-label"
                            data-en="SINHARAJA FOREST"
                            data-si="සිංහරාජ වනාන්තරය"
                            data-ta="SINHARAJA BOS">SINHARAJA FOREST</p>
                        <h2 class="dest-title"
                            data-en="Sinharaja Forest <em>Reserve</em>"
                            data-si="සිංහරාජ වන <em>රක්ෂිතය</em>"
                            data-ta="Sinharaja Bos<em>reservaat</em>">Sinharaja Forest <em>Reserve</em></h2>
                        <p class="dest-para"
                            data-en="Sinharaja Forest Reserve is Sri Lanka's only rainforest and a UNESCO World Heritage Site. More than 50 percent of its plants and animals are endemic, with some species found nowhere else on Earth."
                            data-si="සිංහරාජ වන රක්ෂිතය ශ්‍රී ලංකාවේ එකම වැසි වනාන්තරය වන අතර, යුනෙස්කෝ ලෝක උරුම ස්ථානයකි. එහි ශාක හා සතුන්ගෙන් සියයට 50කට වැඩි ප්‍රමාණයක් ආවේණික වන අතර, විශේෂ කිහිපයක් මිහිතලයේ වෙනත් කොතැනකවත් හමු නොවෙයි."
                            data-ta="Het Sinharaja Bosreservaat is het enige regenwoud van Sri Lanka en een UNESCO-Werelderfgoedlocatie. Meer dan 50 procent van de planten en dieren is endemisch, en sommige soorten worden nergens anders op aarde aangetroffen.">Sinharaja Forest Reserve is Sri Lanka's only rainforest and a UNESCO World Heritage Site. More than 50 percent of its plants and animals are endemic, with some species found nowhere else on Earth.</p>
                        <p class="dest-para"
                            data-en="Covering approximately 11,000 hectares, the forest receives rainfall from both monsoons. Dense canopy, towering trees, and thick undergrowth create a mystical atmosphere transporting visitors into a prehistoric world."
                            data-si="හෙක්ටයාර් 11,000ක් පමණ ආවරණය කරන මෙම වනාන්තරයට මෝසම් කාලගුණ දෙකෙන්ම වර්ෂාව ලැබේ. ඝන වියලි ආවරණය, උස ගස් සහ ඝන යටවැඩියාව, නරඹන්නන් ප්‍රාග් ඓතිහාසික ලෝකයකට රැගෙන යන අද්භූත වාතාවරණයක් නිර්මාණය කරයි."
                            data-ta="Het bos, dat ongeveer 11.000 hectare beslaat, ontvangt regen van beide moessons. Dichte bladerdaken, torenhoge bomen en dik kreupelhout creëren een mystieke sfeer die bezoekers meeneemt naar een prehistorische wereld.">Covering approximately 11,000 hectares, the forest receives rainfall from both monsoons. Dense canopy, towering trees, and thick undergrowth create a mystical atmosphere transporting visitors into a prehistoric world.</p>
                        <p class="dest-para"
                            data-en="Wildlife enthusiasts spot the Sri Lankan giant squirrel, green pit viper, hump-nosed lizard, and Serendib scops owl. Birdwatchers enjoy endemic species like the Sri Lanka blue magpie and red-faced malkoha."
                            data-si="වන සත්ව ලෝලීන් ශ්‍රී ලංකා මහ ලේනා, කොළ පැහැති පොළඟා, කුදු නාසය සහිත කටුස්සා සහ සෙරෙන්ඩිබ් බකමූණා දකිති. පක්ෂි නරඹන්නන් ශ්‍රී ලංකා නිල් කොස්වැටිය සහ රතු මුහුණේ මල්කොහා වැනි ආවේණික විශේෂ භුක්ති විඳිති."
                            data-ta="Natuurliefhebbers spotten de Sri Lankaanse reuzeneekhoorn, groene kuilslang, bultneusgekko en Serendib-dwergooruil. Vogelaars genieten van endemische soorten zoals de Sri Lankaanse blauwe ekster en roodgezichtsmalkoha.">Wildlife enthusiasts spot the Sri Lankan giant squirrel, green pit viper, hump-nosed lizard, and Serendib scops owl. Birdwatchers enjoy endemic species like the Sri Lanka blue magpie and red-faced malkoha.</p>
                    </div>

                </div>

                <!-- ROW 2 -->
                <div class="dest-row row2-card1">

                    <!-- Left 40%: paragraph -->
                    <div class="dest-col col-text">
                        <p class="dest-para"
                            data-en="Entry is only on foot with a compulsory guide. Several trails wind past waterfalls, streams, and giant trees with buttress roots. The entrance fee includes a local guide for visitor safety."
                            data-si="ඇතුළුවීම අනිවාර්ය මාර්ගෝපදේශකයෙකු සමඟ පයින් ගමන් කිරීමෙන් පමණි. මංතීරු කිහිපයක් දිය ඇලි, දොළ සහ බැට්‍රස් මූල සහිත දැවැන්ත ගස් අසලින් ඇලීගෙන යයි. නරඹන්නන්ගේ ආරක්ෂාව සඳහා ඇතුළුවීමේ ගාස්තුවට ප්‍රාදේශීය මාර්ගෝපදේශකයෙකු ඇතුළත් වේ."
                            data-ta="Toegang is alleen te voet met een verplichte gids. Verschillende paden slingeren langs watervallen, beekjes en reusachtige bomen met steunwortels. De toegangsprijs omvat een lokale gids voor de veiligheid van bezoekers.">Entry is only on foot with a compulsory guide. Several trails wind past waterfalls, streams, and giant trees with buttress roots. The entrance fee includes a local guide for visitor safety.</p>
                        <p class="dest-para"
                            data-en="The forest serves as a crucial catchment area for southern Sri Lanka's rivers. Its conservation maintains the island's biodiversity and water resources, making every visit a journey into one of Sri Lanka's most precious natural treasures."
                            data-si="මෙම වනාන්තරය දකුණු ශ්‍රී ලංකාවේ ගංගා සඳහා වැදගත් ජලාශ්‍රිත ප්‍රදේශයක් ලෙස සේවය කරයි. එහි සංරක්ෂණය දූපතේ ජෛව විවිධත්වය සහ ජල සම්පත් පවත්වා ගෙන යන අතර, සෑම සංචාරයක්ම ශ්‍රී ලංකාවේ වඩාත්ම වටිනා ස්වාභාවික සම්පත් වෙත ගමනක් කරයි."
                            data-ta="Het bos dient als een cruciaal opvanggebied voor de rivieren in het zuiden van Sri Lanka. Het behoud ervan handhaaft de biodiversiteit en watervoorraden van het eiland, waardoor elk bezoek een reis wordt naar een van de meest kostbare natuurlijke schatten van Sri Lanka.">The forest serves as a crucial catchment area for southern Sri Lanka's rivers. Its conservation maintains the island's biodiversity and water resources, making every visit a journey into one of Sri Lanka's most precious natural treasures.</p>
                    </div>

                    <!-- Right 60%: 3 images -->
                    <div class="dest-col col-imgs">
                        <div class="triple-imgs">
                            <div class="tri-img tri-img--sm">
                                <img src="https://images.unsplash.com/photo-1501854140801-50d01698950b?w=400&q=80"
                                    alt="SINHARAJA FOREST" />
                            </div>
                            <div class="tri-img tri-img--wide">
                                <img src="https://images.unsplash.com/photo-1552832230-c0197dd311b5?w=600&q=80"
                                    alt="SINHARAJA FOREST" />
                            </div>
                            <div class="tri-img tri-img--sm">
                                <img src="https://images.unsplash.com/photo-1519681393784-d120267933ba?w=400&q=80"
                                    alt="SINHARAJA FOREST" />
                            </div>
                        </div>
                    </div>

                </div>

            </div>
