        <!-- ════════════════════════════════
         CARD 20 — KITULGALA
         Row 1: 60% text LEFT | 40% img RIGHT
         Row 2: 60% 3-images LEFT | 40% para RIGHT
    ════════════════════════════════ -->
        <div class="dest-card">
            <div class="dest-inner">

                <!-- ROW 1 -->
                <div class="dest-row row1-card2">

                    <!-- Left 60%: label + title + paragraphs -->
                    <div class="dest-col col-text">
                        <p class="dest-label"
                            data-en="KITULGALA"
                            data-si="කිතුල්ගල"
                            data-ta="KITULGALA">KITULGALA</p>
                        <h2 class="dest-title"
                            data-en="Kitulgala <em>Adventure Hub</em>"
                            data-si="කිතුල්ගල <em>වික්‍රමාන්විත මධ්‍යස්ථානය</em>"
                            data-ta="Kitulgala <em>Avonturencentrum</em>">Kitulgala <em>Adventure Hub</em></h2>
                        <p class="dest-para"
                            data-en="Kitulgala is Sri Lanka's adventure capital on the banks of the Kelani River. It gained international fame as the filming location for The Bridge on the River Kwai in 1957."
                            data-si="කිතුල්ගල කැලණි ගඟ ඉවුර තිස්සේ පිහිටි ශ්‍රී ලංකාවේ වික්‍රමාන්විත අගනුවරයි. 1957 දී ද බ්‍රිජ් ඔන් ද රිවර් ක්වායි චිත්‍රපටය රූගත කළ ස්ථානය ලෙස එය ජාත්‍යන්තර කීර්තියක් ලබා ගත්තේය."
                            data-ta="Kitulgala is de avonturenhoofdstad van Sri Lanka, aan de oevers van de Kelani-rivier. Het verwierf internationale bekendheid als filmlocatie voor The Bridge on the River Kwai in 1957.">Kitulgala is Sri Lanka's adventure capital on the banks of the Kelani River. It gained international fame as the filming location for The Bridge on the River Kwai in 1957.</p>
                        <p class="dest-para"
                            data-en="White water rafting is the main attraction with five major rapids and four smaller ones. Rapids graded 2 and 3 make them ideal for beginners and experienced rafters alike on this thrilling river."
                            data-si="ප්‍රධාන ආකර්ශනීය ස්ථානය වන්නේ ප්‍රධාන ඉහළ රළ පහක් සහ කුඩා රළ හතරක් සහිත දිය ඇලි රාෆ්ටිං ය. 2 සහ 3 ශ්‍රේණියේ ඉහළ රළ, මෙම ආකර්ශනීය ගඟේ ආරම්භකයින්ට සහ පළපුරුදු රාෆ්ටින් ක්‍රීඩකයින්ට පරිපූර්ණ වෙයි."
                            data-ta="Wildwaterraften is de belangrijkste attractie met vijf grote en vier kleinere stroomversnellingen. Stroomversnellingen van graad 2 en 3 maken het ideaal voor zowel beginners als ervaren raften op deze spannende rivier.">White water rafting is the main attraction with five major rapids and four smaller ones. Rapids graded 2 and 3 make them ideal for beginners and experienced rafters alike on this thrilling river.</p>
                        <p class="dest-para"
                            data-en="Beyond rafting, Kitulgala offers abseiling, canyoning, waterfall trekking, and jungle camping. The surrounding rainforest is rich in biodiversity with numerous birds, butterflies, and endemic wildlife."
                            data-si="රාෆ්ටින් කිරීමෙන් ඔබ්බට, කිතුල්ගල ඇබ්සේලිං, කැන්යනින්, දිය ඇලි කඳු නැගීම් සහ වනාන්තර කඳවුරු ලබා දෙයි. අවට වැසි වනාන්තරය බහුල පක්ෂීන්, සමනලුන් සහ ආවේණික වන සතුන් සහිතව ජෛව විවිධත්වයෙන් සශ්‍රීක වෙයි."
                            data-ta="Naast raften biedt Kitulgala abseilen, canyoning, waterval-trekking en jungle kamperen. Het omliggende regenwoud is rijk aan biodiversiteit met talloze vogels, vlinders en endemische wilde dieren.">Beyond rafting, Kitulgala offers abseiling, canyoning, waterfall trekking, and jungle camping. The surrounding rainforest is rich in biodiversity with numerous birds, butterflies, and endemic wildlife.</p>
                    </div>

                    <!-- Right 40%: single image -->
                    <div class="dest-col col-img">
                        <div class="main-img-wrap">
                            <img src="https://images.unsplash.com/photo-1506905925346-21bda4d32df4?w=700&q=80"
                                alt="KITULGALA" />
                        </div>
                    </div>

                </div>

                <!-- ROW 2 -->
                <div class="dest-row row2-card2">

                    <!-- Left 60%: 3 images -->
                    <div class="dest-col col-imgs">
                        <div class="triple-imgs">
                            <div class="tri-img tri-img--sm">
                                <img src="https://images.unsplash.com/photo-1464822759023-fed622ff2c3b?w=400&q=80"
                                    alt="KITULGALA" />
                            </div>
                            <div class="tri-img tri-img--wide">
                                <img src="https://images.unsplash.com/photo-1582510003544-4d00b7f74220?w=600&q=80"
                                    alt="KITULGALA" />
                            </div>
                            <div class="tri-img tri-img--sm">
                                <img src="https://images.unsplash.com/photo-1567620905732-2d1ec7ab7445?w=400&q=80"
                                    alt="KITULGALA" />
                            </div>
                        </div>
                    </div>

                    <!-- Right 40%: paragraph -->
                    <div class="dest-col col-text">
                        <p class="dest-para"
                            data-en="The nearby Belilena Cave is one of Sri Lanka's largest caves with evidence of prehistoric habitation dating back over 12,000 years. Excavations uncovered tools and remains of Balangoda Man."
                            data-si="ආසන්නයේ පිහිටි බෙලිලෙන ගුහාව, වසර 12,000කට වැඩි කාලයකට පෙර ප්‍රාග් ඓතිහාසික වාසස්ථානයක් වූ බවට සාක්ෂි සහිත ශ්‍රී ලංකාවේ විශාලතම ගුහාවලින් එකකි. කැණීම්වලින් බලංගොඩ මිනිසාගේ මෙවලම් සහ අවශේෂ සොයාගත්තේය."
                            data-ta="De nabijgelegen Belilena-grot is een van de grootste grotten van Sri Lanka, met bewijs van prehistorische bewoning die meer dan 12.000 jaar teruggaat. Opgravingen onthulden gereedschap en resten van de Balangoda-mens.">The nearby Belilena Cave is one of Sri Lanka's largest caves with evidence of prehistoric habitation dating back over 12,000 years. Excavations uncovered tools and remains of Balangoda Man.</p>
                        <p class="dest-para"
                            data-en="Lush greenery, cascading waterfalls, and the rushing river make Kitulgala a photographer's paradise. Whether seeking adrenaline or peaceful nature, it delivers an unforgettable experience in beautiful surroundings."
                            data-si="සශ්‍රීක කොළ පැහැය, කාස්කේඩ් වන දිය ඇලි සහ ඉවුරු කඩාගෙන ගලා යන ගඟ, කිතුල්ගල ඡායාරූප ශිල්පීන්ගේ පාරාදීසයක් කරයි. ඇඩ්‍රනලින් සොයන්නේ වුවද, සාමකාමී ස්වභාවධර්මය සොයන්නේ වුවද, එය සුන්දර වටපිටාවක අමතක නොවන අත්දැකීමක් ලබා දෙයි."
                            data-ta="Weelderig groen, kletterende watervallen en de bruisende rivier maken Kitulgala een paradijs voor fotografen. Of je nu op zoek bent naar adrenaline of vredige natuur, het biedt een onvergetelijke ervaring in prachtige omgevingen.">Lush greenery, cascading waterfalls, and the rushing river make Kitulgala a photographer's paradise. Whether seeking adrenaline or peaceful nature, it delivers an unforgettable experience in beautiful surroundings.</p>
                    </div>

                </div>

            </div>
        </div>

        <!-- ════════════════════════════════
         CARD 21 — MINNERIYA NATIONAL PARK
         Row 1: 40% img LEFT | 60% text RIGHT
         Row 2: 40% para LEFT | 60% 3-images RIGHT
    ════════════════════════════════ -->
        <div class="dest-card">
            <div class="dest-inner">

                <!-- ROW 1 -->
                <div class="dest-row row1-card1">

                    <!-- Left 40%: single image -->
                    <div class="dest-col col-img">
                        <div class="main-img-wrap">
                            <img src="https://images.unsplash.com/photo-1533050487297-09b450131914?w=700&q=80"
                                alt="MINNERIYA NATIONAL PARK" />
                        </div>
                    </div>

                    <!-- Right 60%: label + title + paragraphs -->
                    <div class="dest-col col-text">
                        <p class="dest-label"
                            data-en="MINNERIYA NATIONAL PARK"
                            data-si="මින්නේරිය ජාතික වනෝද්‍යානය"
                            data-ta="MINNERIYA NATIONAAL PARK">MINNERIYA NATIONAL PARK</p>
                        <h2 class="dest-title"
                            data-en="Minneriya <em>Elephant Gathering</em>"
                            data-si="මින්නේරිය <em>අලි එක්රැස්වීම</em>"
                            data-ta="Minneriya <em>Olifantenbijeenkomst</em>">Minneriya <em>Elephant Gathering</em></h2>
                        <p class="dest-para"
                            data-en="Minneriya National Park is world-famous for the annual Gathering, where hundreds of elephants congregate around the ancient Minneriya Tank. This is the largest wild elephant gathering in South Asia."
                            data-si="මින්නේරිය ජාතික වනෝද්‍යානය වාර්ෂික එක්රැස්වීම සඳහා ලෝක ප්‍රසිද්ධය, එහිදී අලින් සිය ගණනක් පුරාණ මින්නේරිය වැව වටා එක් රැස් වෙයි. මෙය දකුණු ආසියාවේ විශාලතම වන අලි එක්රැස්වීමයි."
                            data-ta="Minneriya National Park is wereldberoemd om de jaarlijkse 'Gathering', waarbij honderden olifanten samenkomen rond het oude Minneriya-reservoir. Dit is de grootste verzameling wilde olifanten in Zuid-Azië.">Minneriya National Park is world-famous for the annual Gathering, where hundreds of elephants congregate around the ancient Minneriya Tank. This is the largest wild elephant gathering in South Asia.</p>
                        <p class="dest-para"
                            data-en="The Minneriya Tank is a 4,760-acre reservoir built by King Mahasen around 277 to 304 AD. A 13-meter dam across the Minneriya River holds over 20 billion gallons of water."
                            data-si="මින්නේරිය වැව, ක්‍රි.ව. 277 සිට 304 දක්වා පමණ පැවති මහාසේන රජු විසින් ඉදිකරන ලද අක්කර 4,760ක ජලාශයකි. මින්නේරිය ගඟ හරහා ඇති මීටර් 13ක වේල්ලක ජලය ගැලුම් බිලියන 20කට වැඩි ප්‍රමාණයක් රඳවා ගනී."
                            data-ta="Het Minneriya-reservoir is een reservoir van 4.760 acres, gebouwd door koning Mahasen rond 277 tot 304 n.Chr. Een 13 meter hoge dam over de Minneriya-rivier houdt meer dan 20 miljard liter water vast.">The Minneriya Tank is a 4,760-acre reservoir built by King Mahasen around 277 to 304 AD. A 13-meter dam across the Minneriya River holds over 20 billion gallons of water.</p>
                        <p class="dest-para"
                            data-en="During the dry season from May to September, herds migrate here in search of water. Up to 300 elephants feed on grasslands bordering the tank while others cool off in the giant reservoir."
                            data-si="මැයි සිට සැප්තැම්බර් දක්වා වියළි කාලයේ දී, ජලය සොයමින් රංචු මෙහි සංක්‍රමණය වෙයි. අලින් 300ක් දක්වා වැවට මායිම් වූ තණබිම්වල ආහාර ගන්නා අතර, අනෙක් අය දැවැන්ත ජලාශයේ සිසිල් වෙයි."
                            data-ta="Tijdens het droge seizoen van mei tot september migreren kuddes hierheen op zoek naar water. Tot 300 olifanten grazen op de graslanden langs het reservoir, terwijl anderen afkoelen in het enorme reservoir.">During the dry season from May to September, herds migrate here in search of water. Up to 300 elephants feed on grasslands bordering the tank while others cool off in the giant reservoir.</p>
                    </div>

                </div>

                <!-- ROW 2 -->
                <div class="dest-row row2-card1">

                    <!-- Left 40%: paragraph -->
                    <div class="dest-col col-text">
                        <p class="dest-para"
                            data-en="The park also hosts leopards, sloth bears, spotted deer, sambar deer, wild buffalo, crocodiles, and numerous birds. Low-canopy forests, scrubland, grasslands, and swamps create a diverse ecosystem."
                            data-si="මෙම වනෝද්‍යානයේ දිවියන්, වලාහා, තිත් මුවන්, සම්බර් මුවන්, වල් මී හරක් (කොටි), කිඹුලන් සහ පක්ෂීන් රාශියකුත් වාසය කරයි. පහත් වියලි ආවරණ වනාන්තර, පඳුරු බිම්, තණබිම් සහ වගුරු බිම් විවිධාකාර පරිසර පද්ධතියක් නිර්මාණය කරයි."
                            data-ta="Het park herbergt ook luipaarden, lippenberen, gevlekte herten, sambarherten, wilde buffels, krokodillen en talloze vogels. Lage bladerdaken, struikgewas, graslanden en moerassen creëren een divers ecosysteem.">The park also hosts leopards, sloth bears, spotted deer, sambar deer, wild buffalo, crocodiles, and numerous birds. Low-canopy forests, scrubland, grasslands, and swamps create a diverse ecosystem.</p>
                        <p class="dest-para"
                            data-en="A safari offers thrilling wildlife experiences with elephants interacting, playing, and bathing. The sight of hundreds of majestic creatures against the backdrop of the ancient tank is truly unforgettable."
                            data-si="සෆාරියක් අලින් අන්තර්ක්‍රියා කරමින්, සෙල්ලම් කරමින් සහ ස්නානය කරමින් ආකර්ශනීය වන සත්ව අත්දැකීම් ලබා දෙයි. පුරාණ වැවේ පසුබිමින් යුතුව මහිමාන්විත සතුන් සිය ගණනක දසුන ඇත්තෙන්ම අමතක කළ නොහැකියි."
                            data-ta="Een safari biedt spannende ervaringen met dieren in het wild, waarbij olifanten interageren, spelen en baden. Het zicht op honderden majestueuze wezens tegen de achtergrond van het oude reservoir is werkelijk onvergetelijk.">A safari offers thrilling wildlife experiences with elephants interacting, playing, and bathing. The sight of hundreds of majestic creatures against the backdrop of the ancient tank is truly unforgettable.</p>
                    </div>

                    <!-- Right 60%: 3 images -->
                    <div class="dest-col col-imgs">
                        <div class="triple-imgs">
                            <div class="tri-img tri-img--sm">
                                <img src="https://images.unsplash.com/photo-1501854140801-50d01698950b?w=400&q=80"
                                    alt="MINNERIYA NATIONAL PARK" />
