        <!-- ════════════════════════════════
         CARD 22 — COLOMBO
         Row 1: 60% text LEFT | 40% img RIGHT
         Row 2: 60% 3-images LEFT | 40% para RIGHT
    ════════════════════════════════ -->
        <div class="dest-card">
            <div class="dest-inner">

                <!-- ROW 1 -->
                <div class="dest-row row1-card2">

                    <!-- Left 60%: label + title + paragraphs -->
                    <div class="dest-col col-text">
                        <p class="dest-label"
                            data-en="COLOMBO"
                            data-si="කොළඹ"
                            data-ta="COLOMBO">COLOMBO</p>
                        <h2 class="dest-title"
                            data-en="Colombo <em>Commercial Capital</em>"
                            data-si="කොළඹ <em>වාණිජ අගනුවර</em>"
                            data-ta="Colombo <em>Commerciële Hoofdstad</em>">Colombo <em>Commercial Capital</em></h2>
                        <p class="dest-para"
                            data-en="Colombo is Sri Lanka's largest city and commercial capital, home to around a million people. Situated in the western province, it is the administrative and economic center covering 37 square kilometers."
                            data-si="කොළඹ ශ්‍රී ලංකාවේ විශාලතම නගරය සහ වාණිජ අගනුවර වන අතර, මිලියනයක ජනතාවක් පමණ එහි වාසය කරති. බස්නාහිර පළාතේ පිහිටි මෙය, වර්ග කිලෝමීටර් 37ක් ආවරණය කරන පරිපාලන හා ආර්ථික කේන්ද්‍රස්ථානයයි."
                            data-ta="Colombo is de grootste stad en commerciële hoofdstad van Sri Lanka, met ongeveer een miljoen inwoners. Gelegen in de westelijke provincie, is het het administratieve en economische centrum dat 37 vierkante kilometer beslaat.">Colombo is Sri Lanka's largest city and commercial capital, home to around a million people. Situated in the western province, it is the administrative and economic center covering 37 square kilometers.</p>
                        <p class="dest-para"
                            data-en="The city showcases Sri Lanka's Asian and European heritage. Ancient shrines stand next to churches while skyscrapers rise above time-honored shops, creating a fascinating blend of old and new."
                            data-si="මෙම නගරය ශ්‍රී ලංකාවේ ආසියානු සහ යුරෝපීය උරුමය ප්‍රදර්ශනය කරයි. පුරාණ සිද්ධස්ථාන දේවස්ථානවලට යාබදව පිහිටා ඇති අතර, අහස් කුස්ම් කාලයේ ගෞරවණීය සාප්පු වලට ඉහළින් නැගී සිටී, එමඟින් පැරණි හා නව මිශ්‍රණයක් සිත් ඇද ගනී."
                            data-ta="De stad toont het Aziatische en Europese erfgoed van Sri Lanka. Oude heiligdommen staan naast kerken, terwijl wolkenkrabbers oprijzen boven eeuwenoude winkels, wat een fascinerende mix van oud en nieuw creëert.">The city showcases Sri Lanka's Asian and European heritage. Ancient shrines stand next to churches while skyscrapers rise above time-honored shops, creating a fascinating blend of old and new.</p>
                        <p class="dest-para"
                            data-en="Colombo's architecture reflects Portuguese, Dutch, and British colonization visible throughout the city. The Galle Face Green promenade is a 5-hectare strip between Galle Road and the Indian Ocean."
                            data-si="කොළඹ ගෘහ නිර්මාණ ශිල්පය නගරය පුරාම පෙනෙන පෘතුගීසි, හොලන්ද සහ බ්‍රිතාන්‍ය යටත් විජිතකරණය පිළිබිඹු කරයි. ගාලු මුවදොර හරිතය ගාලු පාර සහ ඉන්දියානු සාගරය අතර හෙක්ටයාර් 5ක ඉඩකඩකි."
                            data-ta="De architectuur van Colombo weerspiegelt de Portugese, Nederlandse en Britse kolonisatie, zichtbaar door de hele stad. De Galle Face Green-promenade is een strook van 5 hectare tussen Galle Road en de Indische Oceaan.">Colombo's architecture reflects Portuguese, Dutch, and British colonization visible throughout the city. The Galle Face Green promenade is a 5-hectare strip between Galle Road and the Indian Ocean.</p>
                    </div>

                    <!-- Right 40%: single image -->
                    <div class="dest-col col-img">
                        <div class="main-img-wrap">
                            <img src="https://images.unsplash.com/photo-1506905925346-21bda4d32df4?w=700&q=80"
                                alt="COLOMBO" />
                        </div>
                    </div>

                </div>

                <!-- ROW 2 -->
                <div class="dest-row row2-card2">

                    <!-- Left 60%: 3 images -->
                    <div class="dest-col col-imgs">
                        <div class="triple-imgs">
                            <div class="tri-img tri-img--sm">
                                <img src="https://images.unsplash.com/photo-1464822759023-fed622ff2c3b?w=400&q=80"
                                    alt="COLOMBO" />
                            </div>
                            <div class="tri-img tri-img--wide">
                                <img src="https://images.unsplash.com/photo-1582510003544-4d00b7f74220?w=600&q=80"
                                    alt="COLOMBO" />
                            </div>
                            <div class="tri-img tri-img--sm">
                                <img src="https://images.unsplash.com/photo-1567620905732-2d1ec7ab7445?w=400&q=80"
                                    alt="COLOMBO" />
                            </div>
                        </div>
                    </div>

                    <!-- Right 40%: paragraph -->
                    <div class="dest-col col-text">
                        <p class="dest-para"
                            data-en="The city offers historical monuments, colonial architecture, beaches, fine dining, nightlife, and shopping. Pettah is the bustling shopping quarter famous for traditional shops and markets."
                            data-si="මෙම නගරයේ ඓතිහාසික ස්මාරක, යටත් විජිත ගෘහ නිර්මාණ ශිල්පය, වෙරළ, ඉහළ පන්තියේ ආහාර, රාත්‍රී ජීවිතය සහ සාප්පු සවාරි ඇත. පේට්ටාව සාම්ප්‍රදායික සාප්පු සහ වෙළඳපොළවලට ප්‍රසිද්ධ කාර්යබහුල සාප්පු සවාරි කලාපයයි."
                            data-ta="De stad biedt historische monumenten, koloniale architectuur, stranden, fijne dineervoorzieningen, nachtleven en winkelen. Pettah is de bruisende winkelwijk, bekend om zijn traditionele winkels en markten.">The city offers historical monuments, colonial architecture, beaches, fine dining, nightlife, and shopping. Pettah is the bustling shopping quarter famous for traditional shops and markets.</p>
                        <p class="dest-para"
                            data-en="Temples, mosques, and churches cater to the diverse population enriching the city's culture. Gangaramaya Temple and Seema Malaka offer spiritual serenity amid the mayhem of city streets."
                            data-si="කෝවිල්, මුස්ලිම් පල්ලි සහ දේවස්ථාන විවිධ ජනවාසය සඳහා සේවාසලසන අතර, නගරයේ සංස්කෘතිය පෝෂණය කරයි. ගංගාරාම විහාරය සහ සීමාමලක නගර වීදිවල කලබලකාරී බව මැද ආධ්‍යාත්මික සැහැල්ලුවක් ලබා දෙයි."
                            data-ta="Tempels, moskeeën en kerken bedienen de diverse bevolking en verrijken de cultuur van de stad. Gangaramaya-tempel en Seema Malaka bieden spirituele rust te midden van de drukte van de stadsstraten.">Temples, mosques, and churches cater to the diverse population enriching the city's culture. Gangaramaya Temple and Seema Malaka offer spiritual serenity amid the mayhem of city streets.</p>
                    </div>

                </div>

            </div>
        </div>

        <!-- ════════════════════════════════
         CARD 23 — RAVANA FALLS
         Row 1: 40% img LEFT | 60% text RIGHT
         Row 2: 40% para LEFT | 60% 3-images RIGHT
    ════════════════════════════════ -->
        <div class="dest-card">
            <div class="dest-inner">

                <!-- ROW 1 -->
                <div class="dest-row row1-card1">

                    <!-- Left 40%: single image -->
                    <div class="dest-col col-img">
                        <div class="main-img-wrap">
                            <img src="https://images.unsplash.com/photo-1533050487297-09b450131914?w=700&q=80"
                                alt="RAVANA FALLS" />
                        </div>
                    </div>

                    <!-- Right 60%: label + title + paragraphs -->
                    <div class="dest-col col-text">
                        <p class="dest-label"
                            data-en="RAVANA FALLS"
                            data-si="රාවණා ඇල්ල"
                            data-ta="RAVANA WATERVAL">RAVANA FALLS</p>
                        <h2 class="dest-title"
                            data-en="Ravana Falls <em>Waterfall</em>"
                            data-si="රාවණා <em>ඇල්ල</em>"
                            data-ta="Ravana <em>Waterval</em>">Ravana Falls <em>Waterfall</em></h2>
                        <p class="dest-para"
                            data-en="Ravana Falls is one of Sri Lanka's widest waterfalls at approximately 25 meters high. Located within the Ravana Ella Wildlife Sanctuary, it sits just 6 kilometers from Ella Railway Station."
                            data-si="රාවණා ඇල්ල මීටර් 25ක් පමණ උසින් යුත් ශ්‍රී ලංකාවේ පුළුල්ම දිය ඇලිවලින් එකකි. රාවණා ඇල්ල වන සත්ව අභයභූමිය තුළ පිහිටි මෙය, ඇල්ල දුම්රිය ස්ථානයෙන් කිලෝමීටර් 6ක් පමණක් දුරින් ඇත."
                            data-ta="Ravana Falls is een van de breedste watervallen van Sri Lanka, ongeveer 25 meter hoog. Gelegen binnen het Ravana Ella Wildreservaat, ligt het slechts 6 kilometer van het treinstation van Ella.">Ravana Falls is one of Sri Lanka's widest waterfalls at approximately 25 meters high. Located within the Ravana Ella Wildlife Sanctuary, it sits just 6 kilometers from Ella Railway Station.</p>
                        <p class="dest-para"
                            data-en="Named after the legendary Ravana from the Ramayana epic, legend says he hid Princess Sita in caves behind this waterfall during her captivity. The cave is now known as Ravana Ella Cave."
                            data-si="රාමායණ වීර කාව්‍යයේ පුරාවෘත්ත රාවණා රජුගේ නමින් නම් කරන ලද මෙය, පුරාවෘත්ත අනුව ඔහු සීතා කුමරියගේ බන්ධනය කාලයේ මෙම ඇල්ල පිටුපස ගුහාවල සඟවා තැබූ බව කියැවේ. දැන් මෙම ගුහාව රාවණා ඇල්ල ගුහාව ලෙස හඳුන්වයි."
                            data-ta="Genoemd naar de legendarische Ravana uit het Ramayana-epos, vertelt de legende dat hij prinses Sita tijdens haar gevangenschap verstopte in grotten achter deze waterval. De grot staat nu bekend als de Ravana Ella-grot.">Named after the legendary Ravana from the Ramayana epic, legend says he hid Princess Sita in caves behind this waterfall during her captivity. The cave is now known as Ravana Ella Cave.</p>
                        <p class="dest-para"
                            data-en="The waterfall cascades from an oval-shaped concave rock outcrop. During the wet season it resembles an areca flower with withering petals, while the dry season brings a gentler but still beautiful flow."
                            data-si="මෙම ඇල්ල ඕවලාකාර අවතල පාෂාණ උන්මුඛයකින් කාස්කේඩ් වෙයි. තෙත් සමයේ එය මැකෙමින් යන පෙති සහිත පුවක් මලකට සමාන වන අතර, වියළි සමයේ එය මෘදු එහෙත් තවමත් සුන්දර ගලායාමක් ගෙන එයි."
                            data-ta="De waterval valt vanaf een ovaalvormige concave rotsformatie. Tijdens het natte seizoen lijkt het op een areca-bloem met verwelkende bloemblaadjes, terwijl het droge seizoen een zachtere, maar nog steeds prachtige stroom met zich meebrengt.">The waterfall cascades from an oval-shaped concave rock outcrop. During the wet season it resembles an areca flower with withering petals, while the dry season brings a gentler but still beautiful flow.</p>
                    </div>

                </div>

                <!-- ROW 2 -->
                <div class="dest-row row2-card1">

                    <!-- Left 40%: paragraph -->
                    <div class="dest-col col-text">
                        <p class="dest-para"
                            data-en="Visitors can climb rocks for closer views, and lower pools offer refreshing swims. Adventure seekers find awe-inspiring vistas of both the falls and Ella's treasured surroundings from nearby viewpoints."
                            data-si="නරඹන්නන්ට වඩාත් සමීප දසුන් සඳහා පාෂාණ නැගිය හැකි අතර, පහළ පිහිනුම් වළවල් ස්ඵූර්තිමත් ස්නානයක් ලබා දෙයි. වික්‍රමාන්විත ලෝලීන් ආසන්නයේ ඇති දර්ශන ස්ථානවලින් ඇල්ලේ සහ ඇල්ලේ වටිනා වටපිටාවේ විශ්මයජනක දසුන් සොයා ගනිති."
                            data-ta="Bezoekers kunnen op rotsen klimmen voor mooiere uitzichten, en lagere poelen bieden verfrissende zwemmogelijkheden. Avonturiers vinden ontzagwekkende vergezichten op zowel de waterval als de gekoesterde omgeving van Ella vanaf nabijgelegen uitkijkpunten.">Visitors can climb rocks for closer views, and lower pools offer refreshing swims. Adventure seekers find awe-inspiring vistas of both the falls and Ella's treasured surroundings from nearby viewpoints.</p>
                        <p class="dest-para"
                            data-en="Best visited during the rainy season when water is most impressive, the falls are a popular stop along the Ella-Wellawaya road. Natural beauty combined with mythological significance makes it a hill country must-visit."
                            data-si="ජලය වඩාත්ම ආකර්ශනීය වන වැසි සමයේ ගමන් කිරීම වඩාත්ම සුදුසු වන අතර, මෙම ඇල්ල ඇල්ල-වැල්ලවාය මාර්ගය ඔස්සේ ප්‍රසිද්ධ නැවතුම් ස්ථානයකි. ස්වාභාවික සුන්දරත්වය පුරාවෘත්ත වැදගත්කම සමඟ මිශ්‍ර වීම, එය කඳුකරයේ අනිවාර්යයෙන් නැරඹිය යුතු ස්ථානයක් කරයි."
                            data-ta="Het beste te bezoeken tijdens het regenseizoen, wanneer het water het meest indrukwekkend is, is de waterval een populaire stop langs de weg Ella-Wellawaya. Natuurlijke schoonheid gecombineerd met mythologische betekenis maakt het een must-see in het heuvelland.">Best visited during the rainy season when water is most impressive, the falls are a popular stop along the Ella-Wellawaya road. Natural beauty combined with mythological significance makes it a hill country must-visit.</p>
                    </div>

                    <!-- Right 60%: 3 images -->
                    <div class="dest-col col-imgs">
                        <div class="triple-imgs">
                            <div class="tri-img tri-img--sm">
                                <img src="https://images.unsplash.com/photo-1501854140801-50d01698950b?w=400&q=80"
                                    alt="RAVANA FALLS" />
                            </div>
                            <div class="tri-img tri-img--wide">
                                <img src="https://images.unsplash.com/photo-1552832230-c0197dd311b5?w=600&q=80"
                                    alt="RAVANA FALLS" />
                            </div>
                            <div class="tri-img tri-img--sm">
                                <img src="https://images.unsplash.com/photo-1519681393784-d120267933ba?w=400&q=80"
                                    alt="RAVANA FALLS" />
                            </div>
