                    </div>

                </div>

            </div>
        </div>

        <!-- ════════════════════════════════
         CARD 24 — PIGEON ISLAND
         Row 1: 60% text LEFT | 40% img RIGHT
         Row 2: 60% 3-images LEFT | 40% para RIGHT
    ════════════════════════════════ -->
        <div class="dest-card">
            <div class="dest-inner">

                <!-- ROW 1 -->
                <div class="dest-row row1-card2">

                    <!-- Left 60%: label + title + paragraphs -->
                    <div class="dest-col col-text">
                        <p class="dest-label"
                            data-en="PIGEON ISLAND"
                            data-si="පරවි දූපත"
                            data-ta="PIGEON ISLAND">PIGEON ISLAND</p>
                        <h2 class="dest-title"
                            data-en="Pigeon Island <em>Marine Park</em>"
                            data-si="පරවි දූපත් <em>සමුද්‍ර වනෝද්‍යානය</em>"
                            data-ta="Pigeon Island <em>Marinepark</em>">Pigeon Island <em>Marine Park</em></h2>
                        <p class="dest-para"
                            data-en="Pigeon Island National Park is a marine sanctuary about 1 kilometer off Nilaveli near Trincomalee. It consists of two islands surrounded by coral reefs home to incredible marine diversity."
                            data-si="පරවි දූපත් ජාතික වනෝද්‍යානය ත්‍රිකුණාමලයට ආසන්න නිලාවැලියෙන් කිලෝමීටරයක් පමණ ඔබ්බෙහි පිහිටි සමුද්‍ර අභයභූමියකි. එය විශ්මයජනක සමුද්‍ර විවිධත්වයකට නිවහන වූ කොරල් පරවලින් වට වූ දූපත් දෙකකින් සමන්විත වෙයි."
                            data-ta="Pigeon Island National Park is een mariene reservaat op ongeveer 1 kilometer van Nilaveli, nabij Trincomalee. Het bestaat uit twee eilanden omringd door koraalriffen die een ongelooflijke mariene diversiteit herbergen.">Pigeon Island National Park is a marine sanctuary about 1 kilometer off Nilaveli near Trincomalee. It consists of two islands surrounded by coral reefs home to incredible marine diversity.</p>
                        <p class="dest-para"
                            data-en="Designated a national park in 2003, it is one of two marine national parks in Sri Lanka. Over 100 coral species and 300 reef fish species have been recorded in the waters around the islands."
                            data-si="2003 දී ජාතික වනෝද්‍යානයක් ලෙස නම් කරන ලද මෙය, ශ්‍රී ලංකාවේ සමුද්‍ර ජාතික වනෝද්‍යාන දෙකෙන් එකකි. දූපත් වටා ඇති ජලයේ කොරල් විශේෂ 100කට වැඩි ප්‍රමාණයක් සහ පර මත්ස්‍ය විශේෂ 300ක් ලේඛනගත කර ඇත."
                            data-ta="In 2003 aangewezen als nationaal park, is het een van de twee mariene nationale parken van Sri Lanka. Meer dan 100 koraalsoorten en 300 rifvissoorten zijn geregistreerd in de wateren rond de eilanden.">Designated a national park in 2003, it is one of two marine national parks in Sri Lanka. Over 100 coral species and 300 reef fish species have been recorded in the waters around the islands.</p>
                        <p class="dest-para"
                            data-en="Snorkeling and diving are the main activities with black-tip reef sharks, sea turtles, and colorful reef fish. Crystal-clear water offers excellent visibility making it a premier snorkeling destination."
                            data-si="ස්නෝකලිං සහ කිමිදීම ප්‍රධාන ක්‍රියාකාරකම් වන අතර, කළු තුඩු සහිත සුළු මෝරුන්, මුහුදු කැස්බෑවුන් සහ වර්ණවත් පර මත්ස්‍යයින් එහි ඇත. කැටපත් වැනි පැහැදිලි ජලය විශිෂ්ට දෘශ්‍යතාවයක් ලබා දෙන අතර, එය ප්‍රමුඛතම ස්නෝකලිං ගමනාන්තයක් කරයි."
                            data-ta="Snorkelen en duiken zijn de belangrijkste activiteiten, met zwartpuntrifhaaien, zeeschildpadden en kleurrijke rifvissen. Het kristalheldere water biedt een uitstekend zicht, waardoor het een toonaangevende snorkelbestemming is.">Snorkeling and diving are the main activities with black-tip reef sharks, sea turtles, and colorful reef fish. Crystal-clear water offers excellent visibility making it a premier snorkeling destination.</p>
                    </div>

                    <!-- Right 40%: single image -->
                    <div class="dest-col col-img">
                        <div class="main-img-wrap">
                            <img src="https://images.unsplash.com/photo-1506905925346-21bda4d32df4?w=700&q=80"
                                alt="PIGEON ISLAND" />
                        </div>
                    </div>

                </div>

                <!-- ROW 2 -->
                <div class="dest-row row2-card2">

                    <!-- Left 60%: 3 images -->
                    <div class="dest-col col-imgs">
                        <div class="triple-imgs">
                            <div class="tri-img tri-img--sm">
                                <img src="https://images.unsplash.com/photo-1464822759023-fed622ff2c3b?w=400&q=80"
                                    alt="PIGEON ISLAND" />
                            </div>
                            <div class="tri-img tri-img--wide">
                                <img src="https://images.unsplash.com/photo-1582510003544-4d00b7f74220?w=600&q=80"
                                    alt="PIGEON ISLAND" />
                            </div>
                            <div class="tri-img tri-img--sm">
                                <img src="https://images.unsplash.com/photo-1567620905732-2d1ec7ab7445?w=400&q=80"
                                    alt="PIGEON ISLAND" />
                            </div>
                        </div>
                    </div>

                    <!-- Right 40%: paragraph -->
                    <div class="dest-col col-text">
                        <p class="dest-para"
                            data-en="The islands are an important breeding ground for rock pigeons that give the park its name. The larger island has rocky outcrops and small beaches, while the smaller is surrounded by shallow coral gardens."
                            data-si="මෙම දූපත්, වනෝද්‍යානයට එහි නම ලබා දෙන පර්වත පරවියන්ගේ වැදගත් අභිජනන භූමියකි. විශාල දූපතේ පාෂාණ උන්මුඛ සහ කුඩා වෙරළ ඇති අතර, කුඩා දූපත නොගැඹුරු කොරල් උද්‍යාන වලින් වට වී ඇත."
                            data-ta="De eilanden zijn een belangrijk broedgebied voor rotsduiven, die het park zijn naam geven. Het grotere eiland heeft rotsachtige uitlopers en kleine stranden, terwijl het kleinere eiland omringd is door ondiepe koraaltuinen.">The islands are an important breeding ground for rock pigeons that give the park its name. The larger island has rocky outcrops and small beaches, while the smaller is surrounded by shallow coral gardens.</p>
                        <p class="dest-para"
                            data-en="Best visited between April and September when the east coast enjoys calm seas and clear waters. Boat trips from Nilaveli Beach combine pristine marine ecosystems with beautiful island scenery."
                            data-si="නැගෙනහිර වෙරළ සන්සුන් මුහුද සහ පැහැදිලි ජලය භුක්ති විඳින අප්‍රේල් සහ සැප්තැම්බර් අතර කාලය ගමන් කිරීමට වඩාත්ම සුදුසුය. නිලාවැලි වෙරළේ සිට බෝට්ටු ගමන්, නොකැළැඹුණු සමුද්‍ර පරිසර පද්ධති සුන්දර දූපත් දර්ශන සමඟ ඒකාබද්ධ කරයි."
                            data-ta="Het beste te bezoeken tussen april en september, wanneer de oostkust kalme zeeën en helder water geniet. Boottochten vanaf Nilaveli Beach combineren ongerepte mariene ecosystemen met prachtige eilandlandschappen.">Best visited between April and September when the east coast enjoys calm seas and clear waters. Boat trips from Nilaveli Beach combine pristine marine ecosystems with beautiful island scenery.</p>
                    </div>

                </div>

            </div>
        </div>

        <!-- ════════════════════════════════
         CARD 25 — KAUDULLA NATIONAL PARK
         Row 1: 40% img LEFT | 60% text RIGHT
         Row 2: 40% para LEFT | 60% 3-images RIGHT
    ════════════════════════════════ -->
        <div class="dest-card">
            <div class="dest-inner">

                <!-- ROW 1 -->
                <div class="dest-row row1-card1">

                    <!-- Left 40%: single image -->
                    <div class="dest-col col-img">
                        <div class="main-img-wrap">
                            <img src="https://images.unsplash.com/photo-1533050487297-09b450131914?w=700&q=80"
                                alt="KAUDULLA NATIONAL PARK" />
                        </div>
                    </div>

                    <!-- Right 60%: label + title + paragraphs -->
                    <div class="dest-col col-text">
                        <p class="dest-label"
                            data-en="KAUDULLA NATIONAL PARK"
                            data-si="කවුඩුල්ල ජාතික වනෝද්‍යානය"
                            data-ta="KAUDULLA NATIONAAL PARK">KAUDULLA NATIONAL PARK</p>
                        <h2 class="dest-title"
                            data-en="Kaudulla <em>Elephant Safari</em>"
                            data-si="කවුඩුල්ල <em>අලි සෆාරිය</em>"
                            data-ta="Kaudulla <em>Olifantensafari</em>">Kaudulla <em>Elephant Safari</em></h2>
                        <p class="dest-para"
                            data-en="Kaudulla National Park sits in Sri Lanka's North Central Province, declared a protected area in 2002. It surrounds the ancient Kaudulla Tank built by King Mahasen, forming part of the elephant corridor."
                            data-si="කවුඩුල්ල ජාතික වනෝද්‍යානය ශ්‍රී ලංකාවේ උතුරු මැද පළාතේ පිහිටා ඇත, 2002 දී ආරක්ෂිත ප්‍රදේශයක් ලෙස ප්‍රකාශයට පත් කරන ලදී. එය මහාසේන රජු විසින් ඉදිකරන ලද පුරාණ කවුඩුල්ල වැව වටකරගෙන, අලි කොරිඩෝවේ කොටසක් සකස් කරයි."
                            data-ta="Kaudulla National Park ligt in de Noord-Centrale provincie van Sri Lanka en werd in 2002 uitgeroepen tot beschermd gebied. Het omringt het oude Kaudulla-reservoir, gebouwd door koning Mahasen, en vormt een deel van de olifantencorridor.">Kaudulla National Park sits in Sri Lanka's North Central Province, declared a protected area in 2002. It surrounds the ancient Kaudulla Tank built by King Mahasen, forming part of the elephant corridor.</p>
                        <p class="dest-para"
                            data-en="Covering about 6,900 hectares, the park is famed for spectacular elephant gatherings. During the dry season from July to October, hundreds of elephants congregate around the ancient Kaudulla Reservoir."
                            data-si="හෙක්ටයාර් 6,900ක් පමණ ආවරණය කරන මෙම වනෝද්‍යානය විශිෂ්ට අලි එක්රැස්වීම් සඳහා ප්‍රසිද්ධය. ජූලි සිට ඔක්තෝබර් දක්වා වියළි කාලයේ දී, අලින් සිය ගණනක් පුරාණ කවුඩුල්ල ජලාශය වටා එක් රැස් වෙයි."
                            data-ta="Met een oppervlakte van ongeveer 6.900 hectare staat het park bekend om zijn spectaculaire olifantenbijeenkomsten. Tijdens het droge seizoen van juli tot oktober verzamelen honderden olifanten zich rond het oude Kaudulla-reservoir.">Covering about 6,900 hectares, the park is famed for spectacular elephant gatherings. During the dry season from July to October, hundreds of elephants congregate around the ancient Kaudulla Reservoir.</p>
                        <p class="dest-para"
                            data-en="The Gathering sees families and herds drinking, bathing, and socializing in receding waters and lush grass. Witnessing so many magnificent creatures interacting is a truly unforgettable wildlife experience."
                            data-si="මෙම එක්රැස්වීමේදී පවුල් සහ රංචු, පහත වැටෙන ජලයේ සහ සශ්‍රීක තණබිම්වල පානය කරමින්, ස්නානය කරමින් සහ සමාජගත වෙමින් සිටිති. මෙතරම් මහිමාන්විත සතුන් ගණනක් අන්තර්ක්‍රියා කරනු දැකීම ඇත්තෙන්ම අමතක නොවන වන සත්ව අත්දැකීමකි."
                            data-ta="Tijdens de 'Gathering' drinken, baden en socialiseren families en kuddes in terugtrekkend water en weelderig gras. Het zien van zoveel prachtige wezens die met elkaar omgaan, is een werkelijk onvergetelijke ervaring met dieren in het wild.">The Gathering sees families and herds drinking, bathing, and socializing in receding waters and lush grass. Witnessing so many magnificent creatures interacting is a truly unforgettable wildlife experience.</p>
                    </div>

                </div>

                <!-- ROW 2 -->
                <div class="dest-row row2-card1">

                    <!-- Left 40%: paragraph -->
                    <div class="dest-col col-text">
                        <p class="dest-para"
                            data-en="The park supports 24 mammal species, 160 bird species, 9 amphibians, 25 reptiles, and 75 butterflies. Other wildlife includes sambar deer, axis deer, wild boar, sloth bears, and occasional leopards."
                            data-si="මෙම වනෝද්‍යානය ක්ෂීරපායී විශේෂ 24ක්, පක්ෂි විශේෂ 160ක්, උභයජීවී 9ක්, උරගයින් 25ක් සහ සමනල විශේෂ 75ක් සඳහා සහාය වෙයි. අනෙකුත් වන සතුන් අතර සම්බර් මුවන්, ඇක්සිස් මුවන්, වල් ඌරන්, වලාහා සහ විටින් විට දිවියන් ඇතුළත් වේ."
                            data-ta="Het park huisvest 24 zoogdiersoorten, 160 vogelsoorten, 9 amfibieën, 25 reptielen en 75 vlindersoorten. Andere dieren in het wild zijn sambarherten, axishherten, wilde zwijnen, lippenberen en af en toe luipaarden.">The park supports 24 mammal species, 160 bird species, 9 amphibians, 25 reptiles, and 75 butterflies. Other wildlife includes sambar deer, axis deer, wild boar, sloth bears, and occasional leopards.</p>
                        <p class="dest-para"
                            data-en="Kaudulla offers a quieter safari experience compared to busier parks. Open landscapes provide clear sightlines for photography, and the calm atmosphere allows more time observing animals and less time waiting in vehicle queues."
                            data-si="කවුඩුල්ල කාර්යබහුල වනෝද්‍යාන හා සසඳන විට වඩාත් සන්සුන් සෆාරි අත්දැකීමක් ලබා දෙයි. විවෘත භූදර්ශන ඡායාරූප ශිල්පය සඳහා පැහැදිලි දසුන් ලබා දෙන අතර, සන්සුන් වාතාවරණය, වාහන පෝලිම්වල රැඳී සිටීමට අඩු කාලයක් සහ සතුන් නිරීක්ෂණය කිරීමට වැඩි කාලයක් ලබා දෙයි."
                            data-ta="Kaudulla biedt een rustigere safari-ervaring in vergelijking met drukkere parken. Open landschappen bieden duidelijke zichtlijnen voor fotografie, en de rustige sfeer geeft meer tijd om dieren te observeren en minder tijd om in voertuigrijen te wachten.">Kaudulla offers a quieter safari experience compared to busier parks. Open landscapes provide clear sightlines for photography, and the calm atmosphere allows more time observing animals and less time waiting in vehicle queues.</p>
                    </div>

                    <!-- Right 60%: 3 images -->
                    <div class="dest-col col-imgs">
                        <div class="triple-imgs">
                            <div class="tri-img tri-img--sm">
                                <img src="https://images.unsplash.com/photo-1501854140801-50d01698950b?w=400&q=80"
                                    alt="KAUDULLA NATIONAL PARK" />
                            </div>
                            <div class="tri-img tri-img--wide">
                                <img src="https://images.unsplash.com/photo-1552832230-c0197dd311b5?w=600&q=80"
                                    alt="KAUDULLA NATIONAL PARK" />
                            </div>
                            <div class="tri-img tri-img--sm">
                                <img src="https://images.unsplash.com/photo-1519681393784-d120267933ba?w=400&q=80"
                                    alt="KAUDULLA NATIONAL PARK" />
