        <!-- ════════════════════════════════
         CARD 26 — SRI MAHA BODHI
         Row 1: 60% text LEFT | 40% img RIGHT
         Row 2: 60% 3-images LEFT | 40% para RIGHT
    ════════════════════════════════ -->
        <div class="dest-card">
            <div class="dest-inner">

                <!-- ROW 1 -->
                <div class="dest-row row1-card2">

                    <!-- Left 60%: label + title + paragraphs -->
                    <div class="dest-col col-text">
                        <p class="dest-label"
                            data-en="SRI MAHA BODHI"
                            data-si="ශ්‍රී මහා බෝධිය"
                            data-ta="SRI MAHA BODHI">SRI MAHA BODHI</p>
                        <h2 class="dest-title"
                            data-en="Sri Maha Bodhi <em>Sacred Tree</em>"
                            data-si="ශ්‍රී මහා බෝධි <em>පූජනීය ගස</em>"
                            data-ta="Sri Maha Bodhi <em>Heilige Boom</em>">Sri Maha Bodhi <em>Sacred Tree</em></h2>
                        <p class="dest-para"
                            data-en="The Jaya Sri Maha Bodhi is a sacred fig tree in Anuradhapura, believed to be a sapling from the historical Bodhi Tree in Bodh Gaya where Buddha attained enlightenment. Planted in 288 BCE, it is the oldest living human-planted tree with a known date."
                            data-si="ජය ශ්‍රී මහා බෝධිය අනුරාධපුරයේ පූජනීය නුග ගසකි, බුදුන් වහන්සේ බුද්ධත්වයට පත් වූ බෝධ් ගයාහි ඓතිහාසික බෝධි වෘක්ෂයෙන් ලබාගත් පැළයක් බව විශ්වාස කරයි. ක්‍රි.පූ. 288 දී රෝපණය කරන ලද මෙය, දන්නා දිනයක් සහිතව මනුෂ්‍ය හස්තයෙන් රෝපණය කරන ලද ජීවමාන පැරණිතම ගසයි."
                            data-ta="De Jaya Sri Maha Bodhi is een heilige vijgenboom in Anuradhapura, waarvan men gelooft dat het een stekje is van de historische Bodhi-boom in Bodh Gaya, waar Boeddha verlichting bereikte. Geplant in 288 v.Chr., is het de oudste levende, door mensen geplante boom met een bekende datum.">The Jaya Sri Maha Bodhi is a sacred fig tree in Anuradhapura, believed to be a sapling from the historical Bodhi Tree in Bodh Gaya where Buddha attained enlightenment. Planted in 288 BCE, it is the oldest living human-planted tree with a known date.</p>
                        <p class="dest-para"
                            data-en="Princess Sangamitta, daughter of Emperor Ashoka, brought the sapling to Sri Lanka as part of his mission to spread Buddhism. King Devanampiya Tissa planted it in Mahamevnawa Gardens, marking Buddhism's establishment in Sri Lanka."
                            data-si="අශෝක අධිරාජයාගේ දියණිය වූ සංඝමිත්තා කුමරිය, බුද්ධාගම ව්‍යාප්ත කිරීමේ ඔහුගේ මෙහෙයුමේ කොටසක් ලෙස මෙම පැළය ශ්‍රී ලංකාවට ගෙන ආවාය. දේවානම්පියතිස්ස රජු එය මහාමේඝවන උද්‍යානයේ රෝපණය කළ අතර, එමඟින් ශ්‍රී ලංකාවේ බුද්ධාගමේ ස්ථාපනය සලකුණු කරයි."
                            data-ta="Prinses Sangamitta, dochter van keizer Ashoka, bracht het stekje naar Sri Lanka als onderdeel van zijn missie om het boeddhisme te verspreiden. Koning Devanampiya Tissa plantte het in de Mahamevnawa-tuinen, wat de vestiging van het boeddhisme in Sri Lanka markeerde.">Princess Sangamitta, daughter of Emperor Ashoka, brought the sapling to Sri Lanka as part of his mission to spread Buddhism. King Devanampiya Tissa planted it in Mahamevnawa Gardens, marking Buddhism's establishment in Sri Lanka.</p>
                        <p class="dest-para"
                            data-en="For over 2,300 years, generations of monks and devotees have carefully tended and protected this sacred tree. It remains the most sacred relic in Sri Lanka, venerated by millions of Buddhists worldwide."
                            data-si="වසර 2,300කට වැඩි කාලයක් තිස්සේ, භික්ෂූන් සහ භක්තිකයන්ගේ පරම්පරාවන් මෙම පූජනීය ගස ප්‍රවේශමෙන් රැක බලා ආරක්ෂා කර ඇත. එය ශ්‍රී ලංකාවේ වඩාත්ම පූජනීය ධාතුව ලෙස පවතින අතර, ලොව පුරා බෞද්ධයන් මිලියන ගණනක් විසින් වැඳපුදනු ලබයි."
                            data-ta="Al meer dan 2.300 jaar lang hebben generaties monniken en gelovigen deze heilige boom zorgvuldig verzorgd en beschermd. Het blijft het meest heilige relikwie van Sri Lanka, vereerd door miljoenen boeddhisten wereldwijd.">For over 2,300 years, generations of monks and devotees have carefully tended and protected this sacred tree. It remains the most sacred relic in Sri Lanka, venerated by millions of Buddhists worldwide.</p>
                    </div>

                    <!-- Right 40%: single image -->
                    <div class="dest-col col-img">
                        <div class="main-img-wrap">
                            <img src="https://images.unsplash.com/photo-1506905925346-21bda4d32df4?w=700&q=80"
                                alt="SRI MAHA BODHI" />
                        </div>
                    </div>

                </div>

                <!-- ROW 2 -->
                <div class="dest-row row2-card2">

                    <!-- Left 60%: 3 images -->
                    <div class="dest-col col-imgs">
                        <div class="triple-imgs">
                            <div class="tri-img tri-img--sm">
                                <img src="https://images.unsplash.com/photo-1464822759023-fed622ff2c3b?w=400&q=80"
                                    alt="SRI MAHA BODHI" />
                            </div>
                            <div class="tri-img tri-img--wide">
                                <img src="https://images.unsplash.com/photo-1582510003544-4d00b7f74220?w=600&q=80"
                                    alt="SRI MAHA BODHI" />
                            </div>
                            <div class="tri-img tri-img--sm">
                                <img src="https://images.unsplash.com/photo-1567620905732-2d1ec7ab7445?w=400&q=80"
                                    alt="SRI MAHA BODHI" />
                            </div>
                        </div>
                    </div>

                    <!-- Right 40%: paragraph -->
                    <div class="dest-col col-text">
                        <p class="dest-para"
                            data-en="The tree is surrounded by a golden railing and protective walls. Devotees dressed in white circle clockwise, offering flowers, lighting oil lamps, and meditating in its shade with deep reverence."
                            data-si="මෙම ගස රන්වන් වැට සහ ආරක්ෂිත පවුරුවලින් වට වී ඇත. සුදු ඇඳුම් අඳින ලද භක්තිකයන් ඔරලෝසු දිශාවට කවයක් සාදමින්, මල් පූජා කරමින්, තෙල් පහන් දල්වමින් සහ එහි සෙවණේ ගැඹුරු භක්තියෙන් භාවනා කරති."
                            data-ta="De boom is omringd door een gouden hek en beschermende muren. In het wit geklede gelovigen lopen met de klok mee, offeren bloemen, ontsteken olielampen en mediteren in de schaduw ervan met diepe eerbied.">The tree is surrounded by a golden railing and protective walls. Devotees dressed in white circle clockwise, offering flowers, lighting oil lamps, and meditating in its shade with deep reverence.</p>
                        <p class="dest-para"
                            data-en="The Sri Maha Bodhi stands as a testament to enduring faith and the deep connection between nature and spirituality. It is a living symbol of Buddhism's roots in Sri Lanka and a beacon of enlightenment for pilgrims."
                            data-si="ශ්‍රී මහා බෝධිය නිරන්තර ශ්‍රද්ධාවට සහ ස්වභාවධර්මය හා ආධ්‍යාත්මිකත්වය අතර ඇති ගැඹුරු සම්බන්ධතාවයට සාක්ෂියක් ලෙස නැගී සිටී. එය ශ්‍රී ලංකාවේ බුද්ධාගමේ මූලයන්ගේ ජීවමාන සංකේතයක් සහ වන්දනාකරුවන් සඳහා බුද්ධත්වයේ ආලෝකයකි."
                            data-ta="De Sri Maha Bodhi staat als een getuigenis van blijvend geloof en de diepe verbinding tussen natuur en spiritualiteit. Het is een levend symbool van de wortels van het boeddhisme in Sri Lanka en een baken van verlichting voor pelgrims.">The Sri Maha Bodhi stands as a testament to enduring faith and the deep connection between nature and spirituality. It is a living symbol of Buddhism's roots in Sri Lanka and a beacon of enlightenment for pilgrims.</p>
                    </div>

                </div>

            </div>
        </div>

        <!-- ════════════════════════════════
         CARD 27 — HIKKADUWA BEACH
         Row 1: 40% img LEFT | 60% text RIGHT
         Row 2: 40% para LEFT | 60% 3-images RIGHT
    ════════════════════════════════ -->
        <div class="dest-card">
            <div class="dest-inner">

                <!-- ROW 1 -->
                <div class="dest-row row1-card1">

                    <!-- Left 40%: single image -->
                    <div class="dest-col col-img">
                        <div class="main-img-wrap">
                            <img src="https://images.unsplash.com/photo-1533050487297-09b450131914?w=700&q=80"
                                alt="HIKKADUWA BEACH" />
                        </div>
                    </div>

                    <!-- Right 60%: label + title + paragraphs -->
                    <div class="dest-col col-text">
                        <p class="dest-label"
                            data-en="HIKKADUWA BEACH"
                            data-si="හික්කඩුව වෙරළ"
                            data-ta="HIKKADUWA BEACH">HIKKADUWA BEACH</p>
                        <h2 class="dest-title"
                            data-en="Hikkaduwa Beach <em>Vibes</em>"
                            data-si="හික්කඩුව වෙරළ <em>මනරම් වාතාවරණය</em>"
                            data-ta="Hikkaduwa Beach <em>Sfeer</em>">Hikkaduwa Beach <em>Vibes</em></h2>
                        <p class="dest-para"
                            data-en="Hikkaduwa lies along Sri Lanka's sun-warmed southwest coast about two hours from Colombo. It evolved from a fishing village into one of the island's most popular coastal destinations with constant energy."
                            data-si="හික්කඩුව කොළඹින් පැය දෙකක් පමණ දුරින් ශ්‍රී ලංකාවේ හිරුකැටි දකුණු-බටහිර වෙරළ තීරය ඔස්සේ පිහිටා ඇත. එය ධීවර ගමක සිට, නිරන්තර ශක්තියකින් යුත් දූපතේ වඩාත්ම ජනප්‍රිය වෙරළබඩ ගමනාන්තවලින් එකක් බවට පරිවර්තනය විය."
                            data-ta="Hikkaduwa ligt langs de door de zon verwarmde zuidwestkust van Sri Lanka, ongeveer twee uur van Colombo. Het ontwikkelde zich van een vissersdorp tot een van de meest populaire kustbestemmingen van het eiland met constante energie.">Hikkaduwa lies along Sri Lanka's sun-warmed southwest coast about two hours from Colombo. It evolved from a fishing village into one of the island's most popular coastal destinations with constant energy.</p>
                        <p class="dest-para"
                            data-en="The Hikkaduwa National Park protects a coral reef rich with color and species. Snorkeling means sharing space with turtles and schools of reef fish, while surf breaks suit beginners and advanced riders alike."
                            data-si="හික්කඩුව ජාතික වනෝද්‍යානය වර්ණ සහ විශේෂ බහුල කොරල් පරයක් ආරක්ෂා කරයි. ස්නෝකලිං කිරීම යනු කැස්බෑවුන් සහ පර මත්ස්‍ය රංචු සමඟ අවකාශය බෙදා ගැනීමයි, එසේම රළ බ්‍රේක් ආරම්භකයින්ට හා දියුණු රළ පදින්නන්ට සමානව ගැලපේ."
                            data-ta="Het Hikkaduwa National Park beschermt een koraalrif rijk aan kleur en soorten. Snorkelen betekent ruimte delen met schildpadden en rifvisscholen, terwijl de surfbreaks geschikt zijn voor zowel beginners als gevorderde surfers.">The Hikkaduwa National Park protects a coral reef rich with color and species. Snorkeling means sharing space with turtles and schools of reef fish, while surf breaks suit beginners and advanced riders alike.</p>
                        <p class="dest-para"
                            data-en="Hikkaduwa Beach is the town's heart, providing a wide golden stretch for swimming, sunbathing, and sunset walks. The north end near the coral sanctuary is ideal for swimming and snorkeling."
                            data-si="හික්කඩුව වෙරළ නගරයේ හදවතයි, පිහිනීම, හිරු රශ්මියට නාන සහ හිරු බැසීම් ඇවිදීම් සඳහා පුළුල් රන් වර්ණ ඉඩක් ලබා දෙයි. කොරල් අභයභූමියට ආසන්න උතුරු කෙළවර, පිහිනීම සහ ස්නෝකලිං සඳහා පරිපූර්ණයි."
                            data-ta="Hikkaduwa Beach is het hart van het stadje, met een breed gouden strand voor zwemmen, zonnebaden en zonsondergangwandelingen. Het noordelijke uiteinde nabij het koraalreservaat is ideaal voor zwemmen en snorkelen.">Hikkaduwa Beach is the town's heart, providing a wide golden stretch for swimming, sunbathing, and sunset walks. The north end near the coral sanctuary is ideal for swimming and snorkeling.</p>
                    </div>

                </div>

                <!-- ROW 2 -->
                <div class="dest-row row2-card1">

                    <!-- Left 40%: paragraph -->
                    <div class="dest-col col-text">
                        <p class="dest-para"
                            data-en="Turtles appear near shore throughout the year, often at the north end of the beach. At sunrise or sunset you can watch them feeding on seagrass, while hatcheries care for injured turtles focusing on rehabilitation."
                            data-si="වර්ෂය පුරාම කැස්බෑවුන් වෙරළට ආසන්නයේ, බොහෝ විට වෙරළේ උතුරු කෙළවරේ පෙනී සිටිති. හිරු උදාවේ හෝ හිරු බැසීමේ දී ඔවුන් මුහුදු තණකොළ අනුභව කිරීම නැරඹිය හැකි අතර, බිහිකරණ මධ්‍යස්ථාන තුවාල ලැබූ කැස්බෑවුන් සුව කිරීම මත අවධානය යොමු කරති."
                            data-ta="Schildpadden verschijnen het hele jaar door in de buurt van de kust, vaak aan het noordelijke uiteinde van het strand. Bij zonsopgang of zonsondergang kun je zien hoe ze zeegras eten, terwijl broedhuizen zorgen voor gewonde schildpadden met focus op revalidatie.">Turtles appear near shore throughout the year, often at the north end of the beach. At sunrise or sunset you can watch them feeding on seagrass, while hatcheries care for injured turtles focusing on rehabilitation.</p>
                        <p class="dest-para"
                            data-en="The community rebuilt with strength after the 2004 tsunami and honors that history through education. Today the area feels lived-in and cared-for, making Hikkaduwa one of the most authentic beach destinations in Sri Lanka."
                            data-si="2004 සුනාමියෙන් පසු ප්‍රජාව ශක්තියෙන් යුතුව නැවත ගොඩනඟා ගත් අතර, අධ්‍යාපනය හරහා එම ඉතිහාසය ගරු කරති. අද වන විට මෙම ප්‍රදේශය ජීවමාන සහ රැක බලාගත් බවක් දැනේ, එමඟින් හික්කඩුව ශ්‍රී ලංකාවේ වඩාත්ම සත්‍ය වෙරළබඩ ගමනාන්තවලින් එකක් කරයි."
                            data-ta="De gemeenschap herbouwde zich met kracht na de tsunami van 2004 en eert die geschiedenis door middel van educatie. Vandaag voelt het gebied bewoond en verzorgd aan, waardoor Hikkaduwa een van de meest authentieke strandbestemmingen van Sri Lanka is.">The community rebuilt with strength after the 2004 tsunami and honors that history through education. Today the area feels lived-in and cared-for, making Hikkaduwa one of the most authentic beach destinations in Sri Lanka.</p>
                    </div>

