        <!-- ════════════════════════════════
         CARD 28 — KELANIYA RAJA MAHA VIHARA
         Row 1: 60% text LEFT | 40% img RIGHT
         Row 2: 60% 3-images LEFT | 40% para RIGHT
    ════════════════════════════════ -->
        <div class="dest-card">
            <div class="dest-inner">

                <!-- ROW 1 -->
                <div class="dest-row row1-card2">

                    <!-- Left 60%: label + title + paragraphs -->
                    <div class="dest-col col-text">
                        <p class="dest-label"
                            data-en="KELANIYA RAJA MAHA VIHARA"
                            data-si="කැලණිය රජ මහා විහාරය"
                            data-ta="KELANIYA RAJA MAHA VIHARA">KELANIYA RAJA MAHA VIHARA</p>
                        <h2 class="dest-title"
                            data-en="Kelaniya Raja Maha <em>Vihara</em>"
                            data-si="කැලණිය රජ මහා <em>විහාරය</em>"
                            data-ta="Kelaniya Raja Maha <em>Vihara</em>">Kelaniya Raja Maha <em>Vihara</em></h2>
                        <p class="dest-para"
                            data-en="The Kelaniya Raja Maha Vihara is one of Sri Lanka's most sacred Buddhist temples, located 11 kilometers northeast of Colombo. Tradition says the Buddha visited Kelaniya during his third and final visit to the island."
                            data-si="කැලණිය රජ මහා විහාරය, කොළඹින් කිලෝමීටර් 11ක් ඊසානදිගින් පිහිටි ශ්‍රී ලංකාවේ වඩාත්ම පූජනීය බෞද්ධ විහාරස්ථානවලින් එකකි. බුදුන් වහන්සේ ඔහුගේ තුන්වැනි හා අවසන් දූපත් සංචාරයේදී කැලණියට පැමිණි බව සම්ප්‍රදාය පවසයි."
                            data-ta="De Kelaniya Raja Maha Vihara is een van de meest heilige boeddhistische tempels van Sri Lanka, gelegen 11 kilometer ten noordoosten van Colombo. Volgens de traditie bezocht Boeddha Kelaniya tijdens zijn derde en laatste bezoek aan het eiland.">The Kelaniya Raja Maha Vihara is one of Sri Lanka's most sacred Buddhist temples, located 11 kilometers northeast of Colombo. Tradition says the Buddha visited Kelaniya during his third and final visit to the island.</p>
                        <p class="dest-para"
                            data-en="The temple is famous for beautiful paintings by renowned artist Solias Mendis adorning the image house walls. These frescoes depict scenes from Buddha's life and Sri Lankan Buddhist history in a distinctive blended style."
                            data-si="මෙම විහාරස්ථානය ප්‍රසිද්ධ චිත්‍ර ශිල්පී සෝලියස් මෙන්ඩිස් විසින් රූප ගෘහයේ පවුරු අලංකාර කරන ලද සුන්දර සිතුවම් සඳහා ප්‍රසිද්ධය. මෙම බිතුසිතුවම් අනන්‍ය මිශ්‍රිත විලාසයකින් බුදුන්ගේ ජීවිතයේ සහ ශ්‍රී ලාංකික බෞද්ධ ඉතිහාසයේ දර්ශන නිරූපනය කරයි."
                            data-ta="De tempel staat bekend om prachtige schilderijen van de beroemde kunstenaar Solias Mendis die de muren van het beeldenhuis sieren. Deze fresco's tonen scènes uit het leven van Boeddha en de Sri Lankaanse boeddhistische geschiedenis in een onderscheidende mix van stijlen.">The temple is famous for beautiful paintings by renowned artist Solias Mendis adorning the image house walls. These frescoes depict scenes from Buddha's life and Sri Lankan Buddhist history in a distinctive blended style.</p>
                        <p class="dest-para"
                            data-en="The complex features a large dagoba said to enshrine a gem-studded throne where the Buddha sat and preached. The annual Duruthu Perahera in January is one of Sri Lanka's most spectacular religious processions."
                            data-si="මෙම සංකීර්ණයේ බුදුන් වහන්සේ වැඩ සිට ධර්ම දේශනා කළ බව කියනු ලබන මැණික් සහිත සිංහාසනයක් තැන්පත් යැයි කියන ලද විශාල දාගැබක් ඇත. ජනවාරි මාසයේ පැවැත්වෙන වාර්ෂික දුරුතු පෙරහැර ශ්‍රී ලංකාවේ වඩාත්ම විශිෂ්ට ආගමික පෙරහැරවලින් එකකි."
                            data-ta="Het complex bevat een grote dagoba waarvan men zegt dat deze een met edelstenen bezette troon herbergt waar Boeddha zat en preekte. De jaarlijkse Duruthu Perahera in januari is een van de meest spectaculaire religieuze processies van Sri Lanka.">The complex features a large dagoba said to enshrine a gem-studded throne where the Buddha sat and preached. The annual Duruthu Perahera in January is one of Sri Lanka's most spectacular religious processions.</p>
                    </div>

                    <!-- Right 40%: single image -->
                    <div class="dest-col col-img">
                        <div class="main-img-wrap">
                            <img src="https://images.unsplash.com/photo-1506905925346-21bda4d32df4?w=700&q=80"
                                alt="KELANIYA RAJA MAHA VIHARA" />
                        </div>
