                    <div class="dest-col col-imgs">
                        <div class="triple-imgs">
                            <div class="tri-img tri-img--sm">
                                <img src="https://images.unsplash.com/photo-1464822759023-fed622ff2c3b?w=400&q=80"
                                    alt="KELANIYA RAJA MAHA VIHARA" />
                            </div>
                            <div class="tri-img tri-img--wide">
                                <img src="https://images.unsplash.com/photo-1582510003544-4d00b7f74220?w=600&q=80"
                                    alt="KELANIYA RAJA MAHA VIHARA" />
                            </div>
                            <div class="tri-img tri-img--sm">
                                <img src="https://images.unsplash.com/photo-1567620905732-2d1ec7ab7445?w=400&q=80"
                                    alt="KELANIYA RAJA MAHA VIHARA" />
                            </div>
                        </div>
                    </div>

                    <!-- Right 40%: paragraph -->
                    <div class="dest-col col-text">
                        <p class="dest-para"
                            data-en="Architecture reflects a blend of Kandyan and modern styles with intricate wood carvings, painted ceilings, and ornate decorations. The serene atmosphere and artistic treasures make Kelaniya spiritually and culturally important."
                            data-si="ගෘහ නිර්මාණ ශිල්පය සියුම් දැව කැටයම්, චිත්‍රකරණය කරන ලද සිවිලිම් සහ අලංකාර සැරසිලි සහිතව කන්ද උඩරට හා නවීන විලාසයන්ගේ මිශ්‍රණයක් පිළිබිඹු කරයි. සන්සුන් වාතාවරණය සහ කලාත්මක නිධාන, කැලණිය ආධ්‍යාත්මිකව හා සංස්කෘතිකව වැදගත් කරයි."
                            data-ta="De architectuur weerspiegelt een mix van Kandyaanse en moderne stijlen met ingewikkelde houtsnijwerken, beschilderde plafonds en sierlijke decoraties. De serene sfeer en artistieke schatten maken Kelaniya spiritueel en cultureel belangrijk.">Architecture reflects a blend of Kandyan and modern styles with intricate wood carvings, painted ceilings, and ornate decorations. The serene atmosphere and artistic treasures make Kelaniya spiritually and culturally important.</p>
                        <p class="dest-para"
                            data-en="Situated on the banks of the Kelani River, the temple offers peaceful retreat from Colombo's bustle. It remains an active place of worship where devotees meditate, make offerings, and seek blessings daily."
                            data-si="කැලණි ගඟ ඉවුර තිස්සේ පිහිටි මෙම විහාරස්ථානය, කොළඹේ කලබලයෙන් සාමකාමී විවේකස්ථානයක් ලබා දෙයි. එය භක්තිකයන් දිනපතා භාවනා කරන, පූජා පිදීම් කරන සහ ආශීර්වාද පතන ක්‍රියාකාරී වන්දනා ස්ථානයක්ව පවතී."
                            data-ta="Gelegen aan de oevers van de Kelani-rivier, biedt de tempel een vredige rustplaats te midden van de drukte van Colombo. Het blijft een actieve plaats van aanbidding waar gelovigen dagelijks mediteren, offers brengen en zegeningen zoeken.">Situated on the banks of the Kelani River, the temple offers peaceful retreat from Colombo's bustle. It remains an active place of worship where devotees meditate, make offerings, and seek blessings daily.</p>
                    </div>

                </div>

            </div>
        </div>

        <!-- ════════════════════════════════
         CARD 29 — BUNDALA NATIONAL PARK
         Row 1: 40% img LEFT | 60% text RIGHT
         Row 2: 40% para LEFT | 60% 3-images RIGHT
    ════════════════════════════════ -->
        <div class="dest-card">
            <div class="dest-inner">

                <!-- ROW 1 -->
                <div class="dest-row row1-card1">

                    <!-- Left 40%: single image -->
                    <div class="dest-col col-img">
                        <div class="main-img-wrap">
                            <img src="https://images.unsplash.com/photo-1533050487297-09b450131914?w=700&q=80"
                                alt="BUNDALA NATIONAL PARK" />
                        </div>
                    </div>

                    <!-- Right 60%: label + title + paragraphs -->
                    <div class="dest-col col-text">
                        <p class="dest-label"
                            data-en="BUNDALA NATIONAL PARK"
                            data-si="බුන්දල ජාතික වනෝද්‍යානය"
                            data-ta="BUNDALA NATIONAAL PARK">BUNDALA NATIONAL PARK</p>
                        <h2 class="dest-title"
                            data-en="Bundala <em>Bird Paradise</em>"
                            data-si="බුන්දල <em>පක්ෂි පාරාදීසය</em>"
                            data-ta="Bundala <em>Vogelparadijs</em>">Bundala <em>Bird Paradise</em></h2>
                        <p class="dest-para"
                            data-en="Bundala National Park is a coastal sanctuary in Hambantota District, declared a wildlife sanctuary in 1969 and upgraded to national park status in 1993. It was Sri Lanka's first wetland to receive Ramsar designation and is a UNESCO Biosphere Reserve."
                            data-si="බුන්දල ජාතික වනෝද්‍යානය හම්බන්තොට දිස්ත්‍රික්කයේ පිහිටි වෙරළබඩ අභයභූමියකි, 1969 දී වන සත්ව අභයභූමියක් ලෙස ප්‍රකාශයට පත් කරන ලද අතර 1993 දී ජාතික වනෝද්‍යාන තත්ත්වයට උසස් කරන ලදී. එය රම්සාර් නම් කිරීම ලැබූ ශ්‍රී ලංකාවේ පළමු තෙත්බිම වූ අතර, යුනෙස්කෝ ජීවගෝලීය රක්ෂිතයකි."
                            data-ta="Bundala National Park is een kustreservaat in het district Hambantota, in 1969 uitgeroepen tot wildreservaat en in 1993 opgewaardeerd tot nationaal park. Het was de eerste wetland van Sri Lanka die de Ramsar-status kreeg en is een UNESCO-biosfeerreservaat.">Bundala National Park is a coastal sanctuary in Hambantota District, declared a wildlife sanctuary in 1969 and upgraded to national park status in 1993. It was Sri Lanka's first wetland to receive Ramsar designation and is a UNESCO Biosphere Reserve.</p>
                        <p class="dest-para"
                            data-en="The park protects salt pans, lagoons, scrub forests, dunes, marshes, and coastal areas. These diverse environments create one of the country's most important ecological zones for resident and migratory birds."
                            data-si="මෙම වනෝද්‍යානය ලුණු වගුරු, කලාප, පඳුරු වනාන්තර, ඉසිඹු, වගුරු බිම් සහ වෙරළබඩ ප්‍රදේශ ආරක්ෂා කරයි. මෙම විවිධාකාර පරිසරයන් ස්ථානික හා සංක්‍රමණික පක්ෂීන් සඳහා රටේ වඩාත්ම වැදගත් පාරිසරික කලාපවලින් එකක් නිර්මාණය කරයි."
                            data-ta="Het park beschermt zoutpannen, lagunes, struikbossen, duinen, moerassen en kustgebieden. Deze diverse omgevingen creëren een van de belangrijkste ecologische zones van het land voor inheemse en trekvogels.">The park protects salt pans, lagoons, scrub forests, dunes, marshes, and coastal areas. These diverse environments create one of the country's most important ecological zones for resident and migratory birds.</p>
                        <p class="dest-para"
                            data-en="Bundala is home to over 230 bird species, making it a paradise for birdwatchers. Thousands of greater flamingos arrive during the northern winter to feed in the shallow lagoons in a spectacular display."
                            data-si="බුන්දල පක්ෂි විශේෂ 230කට වැඩි ප්‍රමාණයකට නිවහන වන අතර, එමඟින් එය පක්ෂි නරඹන්නන් සඳහා පාරාදීසයක් කරයි. උතුරු ශීත සමයේ දී ෆ්ලැමින්ගෝ සහස් ගණනක් නොගැඹුරු කලාපවල ආහාර ගැනීම සඳහා විශිෂ්ට දසුනකින් පැමිණෙති."
                            data-ta="Bundala is de thuisbasis van meer dan 230 vogelsoorten, waardoor het een paradijs is voor vogelaars. Duizenden grote flamingo's arriveren tijdens de noordelijke winter om te foerageren in de ondiepe lagunes, een spectaculair schouwspel.">Bundala is home to over 230 bird species, making it a paradise for birdwatchers. Thousands of greater flamingos arrive during the northern winter to feed in the shallow lagoons in a spectacular display.</p>
                    </div>

                </div>

                <!-- ROW 2 -->
                <div class="dest-row row2-card1">

                    <!-- Left 40%: paragraph -->
                    <div class="dest-col col-text">
                        <p class="dest-para"
                            data-en="Unlike parks focused on large mammals, Bundala stands out for wetland ecosystems. Visitors spot elephants, crocodiles, monkeys, deer, and numerous reptiles while enjoying more intimate safari routes."
                            data-si="විශාල ක්ෂීරපායීන් කෙරෙහි අවධානය යොමු කරන වනෝද්‍යාන මෙන් නොව, බුන්දල තෙත්බිම් පරිසර පද්ධති සඳහා කැපී පෙනේ. නරඹන්නන් වඩාත් සමීප සෆාරි මාර්ග භුක්ති විඳිමින් අලින්, කිඹුලන්, වඳුරන්, මුවන් සහ උරගයින් රාශියක් දකිති."
                            data-ta="In tegenstelling tot parken die zich richten op grote zoogdieren, valt Bundala op door zijn wetland-ecosystemen. Bezoekers spotten olifanten, krokodillen, apen, herten en talloze reptielen terwijl ze genieten van meer intieme safariroutes.">Unlike parks focused on large mammals, Bundala stands out for wetland ecosystems. Visitors spot elephants, crocodiles, monkeys, deer, and numerous reptiles while enjoying more intimate safari routes.</p>
                        <p class="dest-para"
                            data-en="The park appeals strongly to birding and nature photography enthusiasts. Quieter atmosphere creates stronger connection with nature, and changing landscapes of wetlands and coastal scenery provide endless creative possibilities."
                            data-si="මෙම වනෝද්‍යානය පක්ෂි නැරඹීම සහ ස්වභාවධර්ම ඡායාරූප ශිල්ප ලෝලීන්ට දැඩි ලෙස ආකර්ෂණීය වෙයි. සන්සුන් වාතාවරණය ස්වභාවධර්මය සමඟ ශක්තිමත් සම්බන්ධතාවයක් නිර්මාණය කරන අතර, තෙත්බිම් සහ වෙරළබඩ දර්ශනවල වෙනස් වන භූදර්ශන අවසානයක් නැති නිර්මාණශීලී හැකියාවන් ලබා දෙයි."
                            data-ta="Het park spreekt sterk aan bij liefhebbers van vogels kijken en natuurfotografie. De rustigere sfeer creëert een sterkere verbinding met de natuur, en de veranderende landschappen van wetlands en kustlandschap bieden eindeloze creatieve mogelijkheden.">The park appeals strongly to birding and nature photography enthusiasts. Quieter atmosphere creates stronger connection with nature, and changing landscapes of wetlands and coastal scenery provide endless creative possibilities.</p>
                    </div>

                    <!-- Right 60%: 3 images -->
                    <div class="dest-col col-imgs">
                        <div class="triple-imgs">
                            <div class="tri-img tri-img--sm">
                                <img src="https://images.unsplash.com/photo-1501854140801-50d01698950b?w=400&q=80"
                                    alt="BUNDALA NATIONAL PARK" />
                            </div>
                            <div class="tri-img tri-img--wide">
                                <img src="https://images.unsplash.com/photo-1552832230-c0197dd311b5?w=600&q=80"
                                    alt="BUNDALA NATIONAL PARK" />
                            </div>
                            <div class="tri-img tri-img--sm">
                                <img src="https://images.unsplash.com/photo-1519681393784-d120267933ba?w=400&q=80"
                                    alt="BUNDALA NATIONAL PARK" />
                            </div>
                        </div>
                    </div>

                </div>

            </div>
