        <!-- ════════════════════════════════
         CARD 30 — KNUCKLES MOUNTAIN RANGE
         Row 1: 60% text LEFT | 40% img RIGHT
         Row 2: 60% 3-images LEFT | 40% para RIGHT
    ════════════════════════════════ -->
        <div class="dest-card">
            <div class="dest-inner">

                <!-- ROW 1 -->
                <div class="dest-row row1-card2">

                    <!-- Left 60%: label + title + paragraphs -->
                    <div class="dest-col col-text">
                        <p class="dest-label"
                            data-en="KNUCKLES MOUNTAIN RANGE"
                            data-si="දුම්බර කඳු වැටිය"
                            data-ta="KNUCKLES BERGKETEN">KNUCKLES MOUNTAIN RANGE</p>
                        <h2 class="dest-title"
                            data-en="Knuckles Mountain <em>Range</em>"
                            data-si="දුම්බර <em>කඳු වැටිය</em>"
                            data-ta="Knuckles <em>Bergketen</em>">Knuckles Mountain <em>Range</em></h2>
                        <p class="dest-para"
                            data-en="The Knuckles Mountain Range sits northeast of Kandy in central Sri Lanka. Locals call it Dumbara Kanduvetiya, meaning mist-laden mountain range, while the English name comes from peaks resembling a clenched fist."
                            data-si="දුම්බර කඳු වැටිය මධ්‍යම ශ්‍රී ලංකාවේ මහනුවරට ඊසානදිගින් පිහිටා ඇත. ප්‍රාදේශීයයන් එය මීදුමෙන් වැසුණු කඳු වැටිය යන අර්ථය දෙන දුම්බර කඳුවැටිය ලෙස හඳුන්වන අතර, ඉංග්‍රීසි නාමය බැඳ ඇති මිටක් වැනි කඳුවලින් උපන්නකි."
                            data-ta="Het Knuckles-gebergte ligt ten noordoosten van Kandy in centraal Sri Lanka. Lokale bewoners noemen het Dumbara Kanduvetiya, wat 'met mist beladen bergketen' betekent, terwijl de Engelse naam komt van toppen die op een gebalde vuist lijken.">The Knuckles Mountain Range sits northeast of Kandy in central Sri Lanka. Locals call it Dumbara Kanduvetiya, meaning mist-laden mountain range, while the English name comes from peaks resembling a clenched fist.</p>
                        <p class="dest-para"
                            data-en="The Knuckles Conservation Forest covers about 155 square kilometers with elevation from 900 to over 1,900 meters. This variation creates many microclimates, each supporting different plant and animal life."
                            data-si="දුම්බර සංරක්ෂණ වනාන්තරය වර්ග කිලෝමීටර් 155ක් පමණ ආවරණය කරන අතර, මීටර් 900 සිට 1,900ක් දක්වා උන්නතාංශයකින් යුක්ත වෙයි. මෙම විවිධත්වය විවිධ ශාක හා සත්ව ජීවිතයට සහාය වන ක්ෂුද්‍ර දේශගුණ රාශියක් නිර්මාණය කරයි."
                            data-ta="Het Knuckles Conservation Forest beslaat ongeveer 155 vierkante kilometer met een hoogte van 900 tot meer dan 1.900 meter. Deze variatie creëert vele microklimaten, die elk verschillende planten- en diersoorten ondersteunen.">The Knuckles Conservation Forest covers about 155 square kilometers with elevation from 900 to over 1,900 meters. This variation creates many microclimates, each supporting different plant and animal life.</p>
                        <p class="dest-para"
                            data-en="Terrain changes fast through cloud forests, open grasslands, river valleys, and rocky ridges. Key features include Mini World's End with its deep valley view and Pitawala Pathana's unusual rock formations."
                            data-si="භූමිය වළාකුළු වනාන්තර, විවෘත තණබිම්, ගංගා නිම්න සහ පාෂාණ ආදානය හරහා වේගයෙන් වෙනස් වෙයි. ප්‍රධාන විශේෂාංග අතර ගැඹුරු නිම්න දසුනක් සහිත මිනි වර්ල්ඩ්ස් එන්ඩ් සහ පිටවල පතනයේ අසාමාන්‍ය පාෂාණ සැකැස්ම් ඇතුළත් වේ."
                            data-ta="Het terrein verandert snel via wolkenwouden, open graslanden, riviervalleien en rotsachtige ruggen. Belangrijke kenmerken zijn Mini World's End met zijn diepe valleizicht en de ongewone rotsformaties van Pitawala Pathana.">Terrain changes fast through cloud forests, open grasslands, river valleys, and rocky ridges. Key features include Mini World's End with its deep valley view and Pitawala Pathana's unusual rock formations.</p>
                    </div>

                    <!-- Right 40%: single image -->
                    <div class="dest-col col-img">
                        <div class="main-img-wrap">
