                        </div>
                    </div>

                    <!-- Right 40%: paragraph -->
                    <div class="dest-col col-text">
                        <p class="dest-para"
                            data-en="Remote villages like Meemure surround the conservation forest where life follows traditional patterns. Homestays offer home-cooked meals and the chance to join daily routines of small-scale farming and cultivation."
                            data-si="මීමුරේ වැනි දුරස්ථ ගම්මාන, සාම්ප්‍රදායික රටාවන් අනුගමනය කරන ජීවිතයක් ඇති සංරක්ෂණ වනාන්තරය වටකරගෙන ඇත. නිවාස නවාතැන් නිවසේ පිසින ලද ආහාර සහ කුඩා පරිමාණ ගොවිතැන් හා වගා කිරීමේ දෛනික චර්යාවන්ට එක්වීමේ අවස්ථාව ලබා දෙයි."
                            data-ta="Afgelegen dorpen zoals Meemure omringen het beschermde bos, waar het leven traditionele patronen volgt. Homestays bieden thuisbereide maaltijden en de kans om deel te nemen aan de dagelijkse routines van kleinschalige landbouw en teelt.">Remote villages like Meemure surround the conservation forest where life follows traditional patterns. Homestays offer home-cooked meals and the chance to join daily routines of small-scale farming and cultivation.</p>
                        <p class="dest-para"
                            data-en="The Knuckles offers rare mix of nature, culture, and adventure through untouched forests and natural habitats. It is a destination with depth and authenticity for those seeking to escape the crowds."
                            data-si="දුම්බර කඳුවැටිය නොවලහන වනාන්තර සහ ස්වාභාවික වාසභූමි හරහා ස්වභාවධර්මය, සංස්කෘතිය සහ වික්‍රමාන්විතභාවයේ දුර්ලභ මිශ්‍රණයක් ලබා දෙයි. ජනකායෙන් මිදීමට කැමති අයට, ගැඹුර හා සත්‍යතාවයකින් යුත් ගමනාන්තයකි."
                            data-ta="De Knuckles biedt een zeldzame mix van natuur, cultuur en avontuur door ongerepte bossen en natuurlijke habitats. Het is een bestemming met diepgang en authenticiteit voor degenen die aan de drukte willen ontsnappen.">The Knuckles offers rare mix of nature, culture, and adventure through untouched forests and natural habitats. It is a destination with depth and authenticity for those seeking to escape the crowds.</p>
                    </div>

                </div>

            </div>
        </div>

        <!-- ════════════════════════════════
         CARD 31 — KALPITIYA
         Row 1: 40% img LEFT | 60% text RIGHT
