        <div class="dest-card">
            <div class="dest-inner">

                <!-- ROW 1 -->
                <div class="dest-row row1-card1">

                    <!-- Left 40%: single image -->
                    <div class="dest-col col-img">
                        <div class="main-img-wrap">
                            <img src="https://images.unsplash.com/photo-1533050487297-09b450131914?w=700&q=80"
                                alt="KALPITIYA" />
                        </div>
                    </div>

                    <!-- Right 60%: label + title + paragraphs -->
                    <div class="dest-col col-text">
                        <p class="dest-label"
                            data-en="KALPITIYA"
                            data-si="කල්පිටිය"
                            data-ta="KALPITIYA">KALPITIYA</p>
                        <h2 class="dest-title"
                            data-en="Kalpitiya <em>Coastal Escape</em>"
                            data-si="කල්පිටිය <em>වෙරළබඩ විවේකස්ථානය</em>"
                            data-ta="Kalpitiya <em>Kustontsnapping</em>">Kalpitiya <em>Coastal Escape</em></h2>
                        <p class="dest-para"
                            data-en="Kalpitiya is a coastal town on Sri Lanka's northwestern coast on a peninsula separating Puttalam Lagoon from the Indian Ocean. It is one of the country's best-kept secrets with pristine beaches and relatively undeveloped charm."
                            data-si="කල්පිටිය, පුත්තලම් කලාපය ඉන්දියානු සාගරයෙන් වෙන් කරන අර්ධද්වීපයක ශ්‍රී ලංකාවේ ඊසානදිග-බටහිර වෙරළ තීරයේ පිහිටි වෙරළබඩ නගරයකි. නොකැළැඹුණු වෙරළ සහ සාපේක්ෂව සංවර්ධනය නොවූ ආකර්ශනීයත්වයක් සහිතව, එය රටේ වඩාත්ම හොඳින් රහස් සඟවාගත් ස්ථානවලින් එකකි."
                            data-ta="Kalpitiya is een kuststad aan de noordwestkust van Sri Lanka, op een schiereiland dat de Puttalam-lagune scheidt van de Indische Oceaan. Het is een van de best bewaarde geheimen van het land, met ongerepte stranden en relatief onontwikkelde charme.">Kalpitiya is a coastal town on Sri Lanka's northwestern coast on a peninsula separating Puttalam Lagoon from the Indian Ocean. It is one of the country's best-kept secrets with pristine beaches and relatively undeveloped charm.</p>
                        <p class="dest-para"
                            data-en="Waters off Kalpitiya host large pods of spinner dolphins with almost guaranteed sightings on boat trips. Between November and April, the area becomes prime for spotting sperm whales and elusive blue whales."
                            data-si="කල්පිටියට ආසන්න ජලයේ විශාල ස්පින්නර් ඩොල්ෆින් රංචු ඇති අතර, බෝට්ටු ගමන්වලදී ආසන්න වශයෙන් සහතික දසුන් ලැබේ. නොවැම්බර් සිට අප්‍රේල් දක්වා, ශුක්ල තල්මසුන් සහ සැඟවුණු නිල් තල්මසුන් දැකීම සඳහා මෙම ප්‍රදේශය වඩාත්ම සුදුසු වෙයි."
                            data-ta="De wateren voor de kust van Kalpitiya herbergen grote groepen spinnerdolfijnen, met bijna gegarandeerde waarnemingen tijdens boottochten. Tussen november en april wordt het gebied uitstekend geschikt om potvissen en ontwijkende blauwe vinvissen te spotten.">Waters off Kalpitiya host large pods of spinner dolphins with almost guaranteed sightings on boat trips. Between November and April, the area becomes prime for spotting sperm whales and elusive blue whales.</p>
                        <p class="dest-para"
                            data-en="Kalpitiya has emerged as Sri Lanka's premier kitesurfing destination. Consistent winds and flat lagoon waters create perfect conditions for beginners and advanced riders, attracting enthusiasts from around the world."
                            data-si="කල්පිටිය ශ්‍රී ලංකාවේ ප්‍රමුඛතම කයිට්සර්ෆින් ගමනාන්තය ලෙස මතුවී ඇත. අඛණ්ඩ සුළං සහ සමතල කලාප ජලය ආරම්භකයින්ට හා දියුණු රළ පදින්නන්ට පරිපූර්ණ තත්ත්වයන් නිර්මාණය කරන අතර, ලොව පුරා ලෝලීන් ආකර්ෂණය කරයි."
                            data-ta="Kalpitiya is uitgegroeid tot de belangrijkste kitesurfbestemming van Sri Lanka. Consistente wind en vlak lagunewater creëren perfecte omstandigheden voor beginners en gevorderde surfers, en trekken liefhebbers van over de hele wereld aan.">Kalpitiya has emerged as Sri Lanka's premier kitesurfing destination. Consistent winds and flat lagoon waters create perfect conditions for beginners and advanced riders, attracting enthusiasts from around the world.</p>
                    </div>

                </div>

                <!-- ROW 2 -->
                <div class="dest-row row2-card1">

                    <!-- Left 40%: paragraph -->
                    <div class="dest-col col-text">
                        <p class="dest-para"
                            data-en="The nearby Dutch Fort dates to the 17th century, offering glimpse into colonial history. The area features Catholic churches, fishing villages, and salt pans creating a unique cultural landscape."
                            data-si="ආසන්නයේ පිහිටි හොලන්ද බලකොටුව 17 වැනි සියවසට අයත් වන අතර, යටත් විජිත ඉතිහාසය පිළිබඳ දැක්මක් ලබා දෙයි. මෙම ප්‍රදේශයේ කතෝලික දේවස්ථාන, ධීවර ගම්මාන සහ ලුණු වගුරු ඇති අතර, අනන්‍ය සංස්කෘතික භූදර්ශනයක් නිර්මාණය කරයි."
                            data-ta="Het nabijgelegen Nederlandse fort dateert uit de 17e eeuw en biedt een blik op de koloniale geschiedenis. Het gebied kenmerkt zich door katholieke kerken, vissersdorpen en zoutpannen, wat een uniek cultureel landschap creëert.">The nearby Dutch Fort dates to the 17th century, offering glimpse into colonial history. The area features Catholic churches, fishing villages, and salt pans creating a unique cultural landscape.</p>
                        <p class="dest-para"
                            data-en="The Bar Reef just offshore is Sri Lanka's largest coral reef with excellent snorkeling and diving. Kalpitiya's untouched nature, diverse marine life, and water sports make it ideal for adventure seekers and nature lovers."
                            data-si="වෙරළට ආසන්නයේ පිහිටි බාර් රීෆ් යනු විශිෂ්ට ස්නෝකලිං සහ කිමිදීම් සහිත ශ්‍රී ලංකාවේ විශාලතම කොරල් පරයයි. කල්පිටියේ නොවලහන ස්වභාවධර්මය, විවිධාකාර සමුද්‍ර ජීවීන් සහ ජල ක්‍රීඩා, එය වික්‍රමාන්විත ලෝලීන්ට හා ස්වභාවධර්ම ලෝලීන්ට පරිපූර්ණ කරයි."
                            data-ta="Het Bar Reef, net voor de kust, is het grootste koraalrif van Sri Lanka met uitstekend snorkelen en duiken. De ongerepte natuur, diverse mariene leven en watersporten van Kalpitiya maken het ideaal voor avonturiers en natuurliefhebbers.">The Bar Reef just offshore is Sri Lanka's largest coral reef with excellent snorkeling and diving. Kalpitiya's untouched nature, diverse marine life, and water sports make it ideal for adventure seekers and nature lovers.</p>
                    </div>

                    <!-- Right 60%: 3 images -->
                    <div class="dest-col col-imgs">
