         Row 1: 60% text LEFT | 40% img RIGHT
         Row 2: 60% 3-images LEFT | 40% para RIGHT
    ════════════════════════════════ -->
        <div class="dest-card">
            <div class="dest-inner">

                <!-- ROW 1 -->
                <div class="dest-row row1-card2">

                    <!-- Left 60%: label + title + paragraphs -->
                    <div class="dest-col col-text">
                        <p class="dest-label"
                            data-en="DELFT ISLAND"
                            data-si="ඩෙල්ෆ්ට් දූපත"
                            data-ta="DELFT EILAND">DELFT ISLAND</p>
                        <h2 class="dest-title"
                            data-en="Delft Island <em>Remote Beauty</em>"
                            data-si="ඩෙල්ෆ්ට් දූපතේ <em>දුරස්ථ සුන්දරත්වය</em>"
                            data-ta="Delft Eiland <em>Afgelegen Schoonheid</em>">Delft Island <em>Remote Beauty</em></h2>
                        <p class="dest-para"
                            data-en="Delft Island, known locally as Neduntheevu, is the largest island in the Palk Strait off Sri Lanka's northern coast. Named by the Dutch after their city of Delft, it is known for wild horses and unique heritage."
                            data-si="ප්‍රාදේශීයව නෙදුන්ත්‍රීව් ලෙස හඳුන්වන ඩෙල්ෆ්ට් දූපත, ශ්‍රී ලංකාවේ උතුරු වෙරළ ඉදිරිපිට පිහිටි පාල්ක් සමුද්‍ර සන්ධිය හි විශාලතම දූපතයි. ඔවුන්ගේ ඩෙල්ෆ්ට් නගරය නමින් හොලන්දකරුවන් විසින් නම් කරන ලද මෙය, වල් අශ්වයින් සහ අනන්‍ය උරුමය සඳහා ප්‍රසිද්ධය."
                            data-ta="Delft Island, lokaal bekend als Neduntheevu, is het grootste eiland in de Straat van Palk voor de noordkust van Sri Lanka. Genoemd door de Nederlanders naar hun stad Delft, staat het bekend om wilde paarden en uniek erfgoed.">Delft Island, known locally as Neduntheevu, is the largest island in the Palk Strait off Sri Lanka's northern coast. Named by the Dutch after their city of Delft, it is known for wild horses and unique heritage.</p>
                        <p class="dest-para"
                            data-en="The island is home to wild horses, descendants of animals brought by the Portuguese and left by the Dutch. These horses roam freely across grassy plains, creating a surreal African savanna-like landscape."
                            data-si="දූපතේ, පෘතුගීසීන් ගෙනා සහ හොලන්දකරුවන් අත්හැර ගිය සතුන්ගේ දරු පරම්පරා වූ වල් අශ්වයින් වාසය කරයි. මෙම අශ්වයින් තණ තැනිතලා පුරාම නිදහසේ සැරිසරන අතර, අද්භූත ආෆ්‍රිකානු සවානා වැනි භූදර්ශනයක් නිර්මාණය කරයි."
                            data-ta="Het eiland herbergt wilde paarden, nakomelingen van dieren die door de Portugezen zijn meegebracht en door de Nederlanders zijn achtergelaten. Deze paarden zwerven vrij over de grasvlaktes en creëren een surrealistisch Afrikaans savanne-achtig landschap.">The island is home to wild horses, descendants of animals brought by the Portuguese and left by the Dutch. These horses roam freely across grassy plains, creating a surreal African savanna-like landscape.</p>
                        <p class="dest-para"
                            data-en="Delft is surrounded by coral walls built in the Dutch colonial era from chunks of surrounding reef. These walls, some several feet high, were used for boundaries and livestock containment and remain remarkably intact."
                            data-si="ඩෙල්ෆ්ට් ආසන්නයේ ඇති පරයෙන් ලද කොරල් කොටස් වලින් හොලන්ද යටත් විජිත යුගයේ ඉදිකරන ලද කොරල් පවුරුවලින් වට වී ඇත. මෙම පවුරු, සමහරක් අඩිවලින් කිහිපයක් උස, මායිම් සහ ගව රැඳවීම සඳහා භාවිතා කරන ලද අතර, ඒවා ආශ්චර්යජනක ලෙස නොකැළැඹී ඉතිරිව ඇත."
                            data-ta="Delft is omgeven door koraalstenen muren, gebouwd in de Nederlandse koloniale tijd van brokken nabijgelegen rif. Deze muren, sommige enkele voet hoog, werden gebruikt voor grenzen en het insluiten van vee en zijn opmerkelijk intact gebleven.">Delft is surrounded by coral walls built in the Dutch colonial era from chunks of surrounding reef. These walls, some several feet high, were used for boundaries and livestock containment and remain remarkably intact.</p>
                    </div>

