                    <!-- Right 40%: paragraph -->
                    <div class="dest-col col-text">
                        <p class="dest-para"
                            data-en="The island features a Portuguese fort, Dutch hospital, and the ancient Queen's Tower navigational beacon. Baobab trees planted by colonial settlers add to the otherworldly atmosphere of this remote outpost."
                            data-si="දූපතේ පෘතුගීසි බලකොටුවක්, හොලන්ද රෝහලක් සහ පුරාණ රාජිනී කුළුණු ගමන් ආලෝකය ඇත. යටත් විජිත පදිංචිකරුවන් විසින් රෝපණය කරන ලද බෝවබ් ගස් මෙම දුරස්ථ ව්‍යාප්තියේ අද්භූත ලෝකයෙන් ඔබ්බේ ඇති ආකාරයේ වාතාවරණයට එකතු වෙයි."
                            data-ta="Het eiland heeft een Portugees fort, een Nederlands ziekenhuis en het oude Queen's Tower navigatiebaken. Baobab-bomen geplant door koloniale kolonisten dragen bij aan de buitenaardse sfeer van dit afgelegen buitenpost.">The island features a Portuguese fort, Dutch hospital, and the ancient Queen's Tower navigational beacon. Baobab trees planted by colonial settlers add to the otherworldly atmosphere of this remote outpost.</p>
                        <p class="dest-para"
                            data-en="Life on Delft moves slowly with fishing and agriculture as main livelihoods. The island's isolation preserves natural beauty and traditional way of life, making it fascinating for those venturing off the beaten path."
                            data-si="ඩෙල්ෆ්ට් දූපතේ ජීවිතය මසුන් ඇල්ලීම සහ ගොවිතැන ප්‍රධාන ජීවනෝපාය ලෙස ස්ලෝ ලෙස ගමන් කරයි. දූපතේ හුදකලාව ස්වාභාවික සුන්දරත්වය සහ සාම්ප්‍රදායික ජීවන රීතිය සංරක්ෂණය කරන අතර, ගොළු මාර්ගයෙන් ඉදිරියට ගමන් කරන අය සඳහා මෙය ආකර්ශනීය කරයි."
                            data-ta="Het leven op Delft beweegt langzaam, met vissen en landbouw als belangrijkste middelen van bestaan. De isolatie van het eiland behoudt de natuurlijke schoonheid en traditionele manier van leven, waardoor het fascinerend is voor degenen die van de gebaande paden afwijken.">Life on Delft moves slowly with fishing and agriculture as main livelihoods. The island's isolation preserves natural beauty and traditional way of life, making it fascinating for those venturing off the beaten path.</p>
                    </div>

                </div>

            </div>
        </div>

        <!-- ════════════════════════════════
         CARD 33 — GREGORY LAKE
         Row 1: 40% img LEFT | 60% text RIGHT
         Row 2: 40% para LEFT | 60% 3-images RIGHT
    ════════════════════════════════ -->
        <div class="dest-card">
            <div class="dest-inner">

                <!-- ROW 1 -->
                <div class="dest-row row1-card1">

                    <!-- Left 40%: single image -->
                    <div class="dest-col col-img">
                        <div class="main-img-wrap">
                            <img src="https://images.unsplash.com/photo-1533050487297-09b450131914?w=700&q=80"
                                alt="GREGORY LAKE" />
                        </div>
                    </div>

                    <!-- Right 60%: label + title + paragraphs -->
                    <div class="dest-col col-text">
                        <p class="dest-label"
                            data-en="GREGORY LAKE"
                            data-si="ග්‍රෙගරි වැව"
                            data-ta="GREGORY MEER">GREGORY LAKE</p>
                        <h2 class="dest-title"
                            data-en="Gregory Lake <em>Nuwara Eliya</em>"
                            data-si="ග්‍රෙගරි වැව <em>නුවරඑළිය</em>"
                            data-ta="Gregory Meer <em>Nuwara Eliya</em>">Gregory Lake <em>Nuwara Eliya</em></h2>
                        <p class="dest-para"
                            data-en="Lake Gregory is a picturesque reservoir in the heart of Nuwara Eliya, surrounded by rolling hills and lush greenery. Built in 1873 by Governor William Gregory, it was created by damming the Nanu Oya stream for British recreation."
                            data-si="ග්‍රෙගරි වැව, රොළ ඇද යන කඳු සහ සශ්‍රීක කොළ පැහැයෙන් වට වූ නුවරඑළියේ හදවතේ ඇති සිත් ගන්නා ජලාශයකි. 1873 දී ආණ්ඩුකාරු විලියම් ග්‍රෙගරි විසින් ඉදිකරන ලද මෙය, බ්‍රිතාන්‍ය විනෝදක්‍රීඩා සඳහා නනු ඔය ගිලෙව්වෙන් නිර්මාණය කරන ලදී."
                            data-ta="Lake Gregory is een pittoresk reservoir in het hart van Nuwara Eliya, omringd door glooiende heuvels en weelderig groen. Gebouwd in 1873 door gouverneur William Gregory, werd het gecreëerd door de Nanu Oya-stroom op te dammen voor Britse recreatie.">Lake Gregory is a picturesque reservoir in the heart of Nuwara Eliya, surrounded by rolling hills and lush greenery. Built in 1873 by Governor William Gregory, it was created by damming the Nanu Oya stream for British recreation.</p>
                        <p class="dest-para"
                            data-en="Today it is one of Nuwara Eliya's most popular attractions, offering boat rides, pony rides along the shore, and walking paths encircling the water. The cool climate and scenic beauty make it a favorite spot."
                            data-si="අද වන විට එය නුවරඑළියේ වඩාත්ම ජනප්‍රිය ආකර්ශනීය ස්ථානවලින් එකක් වන අතර, බෝට්ටු ගමන්, වෙරළ ඔස්සේ කෙටි අශ්ව ගමන් සහ ජලය වට කරමින් ඇවිදීමේ මාර්ග ලබා දෙයි. සීතල දේශගුණය සහ සිත් ගන්නා සෞන්දර්යය, එය ප්‍රියතම ස්ථානයක් කරයි."
                            data-ta="Vandaag is het een van de populairste attracties van Nuwara Eliya, met boottochten, ponyritten langs de oever en wandelpaden rondom het water. Het koele klimaat en de pittoreske schoonheid maken het een geliefde plek.">Today it is one of Nuwara Eliya's most popular attractions, offering boat rides, pony rides along the shore, and walking paths encircling the water. The cool climate and scenic beauty make it a favorite spot.</p>
                        <p class="dest-para"
                            data-en="The lake is surrounded by well-maintained parks and gardens with Hakgala Botanical Garden visible in the distance. On clear days, mountain reflections in calm waters create postcard-perfect scenes."
                            data-si="දිස්තල දී හාකගල ශාකෝද්‍යානය දිස්වන, හොඳින් නඩත්තු කරන ලද උද්‍යාන හා කෙළිමළු වලින් ජලාශය වට වී ඇත. හිනිදිය දිනවල, සන්සුන් ජලයේ කඳු පිළිබිඹු පශ්චිමකාර්ඩ් දසුන් නිර්මාණය කරයි."
                            data-ta="Het meer is omringd door goed onderhouden parken en tuinen, met de botanische tuin van Hakgala zichtbaar in de verte. Op heldere dagen creëren bergreflecties in kalm water plaatjesachtige taferelen.">The lake is surrounded by well-maintained parks and gardens with Hakgala Botanical Garden visible in the distance. On clear days, mountain reflections in calm waters create postcard-perfect scenes.</p>
                    </div>

                </div>

                <!-- ROW 2 -->
                <div class="dest-row row2-card1">

                    <!-- Left 40%: paragraph -->
                    <div class="dest-col col-text">
                        <p class="dest-para"
                            data-en="The area has picnic spots, children's play areas, and food stalls serving local snacks. During April season, the lake becomes a hub of activity with families enjoying pleasant weather and festive atmosphere."
                            data-si="ප්‍රදේශයේ විවේකාගාර, ළමා ක්‍රීඩා ස්ථාන සහ ප්‍රාදේශීය ආහාර ලබා දෙන ආහාර කූඩාරම් ඇත. අප්‍රේල් සමය තුළ, ජලාශය සුළු දේශගුණය හා උත්සව වාතාවරණය භුක්ති විඳින පවුල් සමඟ ක්‍රියාකාරකම්වල කේන්ද්‍රස්ථානයක් බවට පත් වෙයි."
                            data-ta="Het gebied heeft picknickplaatsen, kinderspeelterreinen en eettentjes die lokale snacks serveren. Tijdens het aprilseizoen wordt het meer een centrum van activiteit, met families die genieten van het aangename weer en de feestelijke sfeer.">The area has picnic spots, children's play areas, and food stalls serving local snacks. During April season, the lake becomes a hub of activity with families enjoying pleasant weather and festive atmosphere.</p>
                        <p class="dest-para"
                            data-en="A leisurely walk around the lake offers stunning scenery and panoramic vistas with rugged mountains against clear blue skies. Whether jogging in the morning or boating in the afternoon, it provides serene highland escape."
                            data-si="ජලාශය වටා සැහැල්ලු ඇවිදීමක් නිල් අහස හරහා රළු කඳු සහිතව, අතිශය සිත් ගන්නා දර්ශන සහ විශ්ව දෘෂ්ටිකෝණ ලබා දෙයි. උදෑසන දිවීම හෝ දහවල් බෝට්ටු ගමන් සඳහා, සන්සුන් කඳුකර විවේකය ලබා දෙයි."
                            data-ta="Een ontspannen wandeling rond het meer biedt prachtig landschap en panoramische vergezichten met ruige bergen tegen een heldere blauwe lucht. Of je nu 's ochtends jogt of 's middags vaart, het biedt een serene ontsnapping naar het hoogland.">A leisurely walk around the lake offers stunning scenery and panoramic vistas with rugged mountains against clear blue skies. Whether jogging in the morning or boating in the afternoon, it provides serene highland escape.</p>
                    </div>

                    <!-- Right 60%: 3 images -->
                    <div class="dest-col col-imgs">
                        <div class="triple-imgs">
                            <div class="tri-img tri-img--sm">
                                <img src="https://images.unsplash.com/photo-1501854140801-50d01698950b?w=400&q=80"
                                    alt="GREGORY LAKE" />
