        <!-- ════════════════════════════════
         CARD 34 — MAHIYANGANAYA
         Row 1: 60% text LEFT | 40% img RIGHT
         Row 2: 60% 3-images LEFT | 40% para RIGHT
    ════════════════════════════════ -->
        <div class="dest-card">
            <div class="dest-inner">

                <!-- ROW 1 -->
                <div class="dest-row row1-card2">

                    <!-- Left 60%: label + title + paragraphs -->
                    <div class="dest-col col-text">
                        <p class="dest-label"
                            data-en="MAHIYANGANAYA"
                            data-si="මහියංගනය"
                            data-ta="MAHIYANGANAYA">MAHIYANGANAYA</p>
                        <h2 class="dest-title"
                            data-en="Mahiyanganaya <em>Ancient Site</em>"
                            data-si="මහියංගනය <em>පුරාණ ස්ථානය</em>"
                            data-ta="Mahiyanganaya <em>Oude Site</em>">Mahiyanganaya <em>Ancient Site</em></h2>
                        <p class="dest-para"
                            data-en="Mahiyanganaya in Uva Province holds immense historical and religious significance. It is believed to be the site of Buddha's first visit to Sri Lanka, where he preached to the indigenous Yaksha tribe."
                            data-si="ඌව පළාතේ මහියංගනය, විශාල ඓතිහාසික හා ආගමික වැදගත්කමක් දරයි. බුදුන් වහන්සේ ශ්‍රී ලංකාවට ප්‍රථම වරට පැමිණ, ආදිවාසී යක්ෂ ගෝත්‍රිකයන්ට ධර්ම දේශනා කළ ස්ථානය ලෙස මෙය විශ්වාස කරයි."
                            data-ta="Mahiyanganaya in de provincie Uva heeft een immense historische en religieuze betekenis. Men gelooft dat het de locatie is van Boeddha's eerste bezoek aan Sri Lanka, waar hij preekte voor de inheemse Yaksha-stam.">Mahiyanganaya in Uva Province holds immense historical and religious significance. It is believed to be the site of Buddha's first visit to Sri Lanka, where he preached to the indigenous Yaksha tribe.</p>
                        <p class="dest-para"
                            data-en="The Mahiyangana Stupa, originally built by King Devanampiya Tissa in the 3rd century BCE, marks this sacred spot. Successive kings enlarged and renovated it over centuries, making it a major pilgrimage site."
                            data-si="ක්‍රි.පූ. 3 වැනි සියවසේ දේවානම්පිය තිස්ස රජු විසින් මුලින් ඉදිකරන ලද මහියංගන ස්තූපය, මෙම පූජනීය ස්ථානය සලකුණු කරයි. අනුප්‍රාප්තික රජවරුන් සියවස් ගණනාවක් තිස්සේ එය පුළුල් කළ හා ප්‍රතිසංස්කරණය කළ අතර, ප්‍රධාන වන්දනා ස්ථානයක් බවට පත් කළේය."
                            data-ta="De Mahiyangana-stoepa, oorspronkelijk gebouwd door koning Devanampiya Tissa in de 3e eeuw v.Chr., markeert deze heilige plek. Opvolgende koningen breidden het uit en renoveerden het door de eeuwen heen, waardoor het een belangrijke pelgrimsplaats werd.">The Mahiyangana Stupa, originally built by King Devanampiya Tissa in the 3rd century BCE, marks this sacred spot. Successive kings enlarged and renovated it over centuries, making it a major pilgrimage site.</p>
                        <p class="dest-para"
                            data-en="The town is gateway to the indigenous Veddha community, Sri Lanka's aboriginal people. Village tours offer rare glimpses into their unique culture and traditions unchanged for thousands of years."
                            data-si="නගරය ශ්‍රී ලංකාවේ ආදිවාසී ජනතාව වූ ආදිවාසී වැද්ද ප්‍රජාව වෙත ප්‍රවේශ ද්වාරයකි. ගම් සංචාර, දහස් ගණනක් වසරකට වෙනස් නොවූ ඔවුන්ගේ අනන්‍ය සංස්කෘතිය හා සම්ප්‍රදායන් පිළිබඳ දුර්ලභ දසුන් ලබා දෙයි."
                            data-ta="Het stadje is de toegangspoort tot de inheemse Veddha-gemeenschap, de oorspronkelijke bewoners van Sri Lanka. Dorpstours bieden zeldzame blikken op hun unieke cultuur en tradities die duizenden jaren lang onveranderd zijn gebleven.">The town is gateway to the indigenous Veddha community, Sri Lanka's aboriginal people. Village tours offer rare glimpses into their unique culture and traditions unchanged for thousands of years.</p>
                    </div>

                    <!-- Right 40%: single image -->
                    <div class="dest-col col-img">
                        <div class="main-img-wrap">
                            <img src="https://images.unsplash.com/photo-1506905925346-21bda4d32df4?w=700&q=80"
                                alt="MAHIYANGANAYA" />
                        </div>
                    </div>

                </div>

                <!-- ROW 2 -->
                <div class="dest-row row2-card2">

                    <!-- Left 60%: 3 images -->
                    <div class="dest-col col-imgs">
                        <div class="triple-imgs">
                            <div class="tri-img tri-img--sm">
                                <img src="https://images.unsplash.com/photo-1464822759023-fed622ff2c3b?w=400&q=80"
                                    alt="MAHIYANGANAYA" />
                            </div>
                            <div class="tri-img tri-img--wide">
                                <img src="https://images.unsplash.com/photo-1582510003544-4d00b7f74220?w=600&q=80"
                                    alt="MAHIYANGANAYA" />
                            </div>
                            <div class="tri-img tri-img--sm">
                                <img src="https://images.unsplash.com/photo-1567620905732-2d1ec7ab7445?w=400&q=80"
                                    alt="MAHIYANGANAYA" />
                            </div>
                        </div>
                    </div>

                    <!-- Right 40%: paragraph -->
                    <div class="dest-col col-text">
                        <p class="dest-para"
                            data-en="Nearby Sorabora Lake offers scenic views and boating opportunities. Built by legendary giant Bulatha according to folklore, it remains an important irrigation reservoir for the region."
                            data-si="ආසන්නයේ ඇති සොරාබොර ජලාශය සිත් ගන්නා දසුන් සහ බෝට්ටු ගමන් අවස්ථා ලබා දෙයි. ජනප්‍රවාද අනුව, ජනප්‍රිය දෙව්මෑණිය බුලතා විසින් ඉදිකරන ලද බව කියන, එය ප්‍රදේශය සඳහා වැදගත් ජල සේදීම් ජලාශයක් ලෙස ඉතිරිව ඇත."
                            data-ta="Het nabijgelegen Sorabora-meer biedt schilderachtige uitzichten en vaarbootmogelijkheden. Gebouwd door de legendarische reus Bulatha, volgens de folklore, blijft het een belangrijk irrigatiereservoir voor de regio.">Nearby Sorabora Lake offers scenic views and boating opportunities. Built by legendary giant Bulatha according to folklore, it remains an important irrigation reservoir for the region.</p>
                        <p class="dest-para"
                            data-en="Mahiyanganaya serves as base for exploring Wasgamuwa National Park and Rathna Ella waterfall. Its combination of religious significance, indigenous culture, and natural attractions makes it a unique destination."
                            data-si="මහියංගනය, වාස්ගමුව ජාතික වනෝද්‍යානය සහ රත්නේල්ල දිය ඇල්ල ගවේෂණය කිරීම සඳහා පාදකයක් ලෙස සේවය කරයි. ආගමික වැදගත්කම, ආදිවාසී සංස්කෘතිය සහ ස්වාභාවික ආකර්ශනීය ස්ථාන ඒකාබද්ධ කිරීම, එය අනන්‍ය ගමනාන්තයක් කරයි."
                            data-ta="Mahiyanganaya dient als uitvalsbasis voor het verkennen van Wasgamuwa National Park en de Rathna Ella-waterval. De combinatie van religieuze betekenis, inheemse cultuur en natuurlijke attracties maakt het een unieke bestemming.">Mahiyanganaya serves as base for exploring Wasgamuwa National Park and Rathna Ella waterfall. Its combination of religious significance, indigenous culture, and natural attractions makes it a unique destination.</p>
                    </div>

                </div>

            </div>
        </div>

        <!-- ════════════════════════════════
         CARD 35 — BADULLA
         Row 1: 40% img LEFT | 60% text RIGHT
         Row 2: 40% para LEFT | 60% 3-images RIGHT
    ════════════════════════════════ -->
        <div class="dest-card">
            <div class="dest-inner">

                <!-- ROW 1 -->
                <div class="dest-row row1-card1">

                    <!-- Left 40%: single image -->
                    <div class="dest-col col-img">
                        <div class="main-img-wrap">
                            <img src="https://images.unsplash.com/photo-1533050487297-09b450131914?w=700&q=80"
                                alt="BADULLA" />
                        </div>
                    </div>

                    <!-- Right 60%: label + title + paragraphs -->
                    <div class="dest-col col-text">
                        <p class="dest-label"
                            data-en="BADULLA"
                            data-si="බදුල්ල"
                            data-ta="BADULLA">BADULLA</p>
                        <h2 class="dest-title"
                            data-en="Badulla <em>Hill Town</em>"
                            data-si="බදුල්ල <em>කඳු නගරය</em>"
                            data-ta="Badulla <em>Heuveldorp</em>">Badulla <em>Hill Town</em></h2>
                        <p class="dest-para"
                            data-en="Badulla is the capital of Uva Province, nestled in the lower central highlands. One of Sri Lanka's oldest towns with history dating to the pre-Christian era, it serves as an important commercial and transportation hub."
                            data-si="බදුල්ල, පහළ මධ්‍යම කඳුකරයේ කූඩු ගෙවෙන ඌව පළාතේ අගනුවරයි. ශ්‍රී ලංකාවේ වයස් ගත නගරවලින් එකක් ලෙස, ක්‍රිස්තු-පූර්ව යුගයට දිවෙන ඉතිහාසයක් සමඟ, එය වැදගත් වාණිජ හා ප්‍රවාහන කේන්ද්‍රස්ථානයක් ලෙස සේවය කරයි."
                            data-ta="Badulla is de hoofdstad van de provincie Uva, genesteld in het lagere centrale hoogland. Een van de oudste steden van Sri Lanka, met een geschiedenis die teruggaat tot het pre-christelijke tijdperk, het dient als een belangrijk commercieel en transportknooppunt.">Badulla is the capital of Uva Province, nestled in the lower central highlands. One of Sri Lanka's oldest towns with history dating to the pre-Christian era, it serves as an important commercial and transportation hub.</p>
                        <p class="dest-para"
                            data-en="Surrounded by tea plantations, vegetable farms, and scenic mountain views, the cool climate and lush greenery make it pleasant for travelers. Badulla is also the terminus of the scenic upcountry railway line."
                            data-si="තේ වතු, එළවළු ගොවිපොළ සහ සිත් ගන්නා කඳු දර්ශනවලින් වට වූ, සීතල දේශගුණය සහ සශ්‍රීක කොළ පැහැය සංචාරකයින්ට සතුටදායක කරයි. බදුල්ල, සිත් ගන්නා ඌව ගැමිදෙස දුම්රිය මාර්ගයේ ටර්මිනසය ද වෙයි."
                            data-ta="Omringd door theeplantages, groentetuinen en schilderachtige bergzichten, maakt het koele klimaat en het weelderige groen het aangenaam voor reizigers. Badulla is ook het eindpunt van de schilderachtige spoorlijn naar het binnenland.">Surrounded by tea plantations, vegetable farms, and scenic mountain views, the cool climate and lush greenery make it pleasant for travelers. Badulla is also the terminus of the scenic upcountry railway line.</p>
                        <p class="dest-para"
                            data-en="The Muthiyangana Raja Maha Viharaya is one of Badulla's most important temples, believed visited by Buddha during his third visit to Sri Lanka. The complex features a historic dagoba and ancient stone inscriptions."
                            data-si="මුතියංගන රජ මහා විහාරය, ශ්‍රී ලංකාවට ඔහුගේ තෙවැනි සංචාරයේ දී බුදුන් වහන්සේ පැමිණි බව විශ්වාස කරන, බදුල්ලේ වඩාත්ම වැදගත් විහාරස්ථානවලින් එකක් ය. සංකීර්ණයේ ඓතිහාසික දාගැබක් සහ පුරාණ ශිලා ලිපි ඇත."
                            data-ta="De Muthiyangana Raja Maha Viharaya is een van de belangrijkste tempels van Badulla, waarvan men gelooft dat Boeddha er tijdens zijn derde bezoek aan Sri Lanka naartoe ging. Het complex bevat een historische dagoba en oude steenopschriften.">The Muthiyangana Raja Maha Viharaya is one of Badulla's most important temples, believed visited by Buddha during his third visit to Sri Lanka. The complex features a historic dagoba and ancient stone inscriptions.</p>
                    </div>

                </div>

                <!-- ROW 2 -->
                <div class="dest-row row2-card1">

                    <!-- Left 40%: paragraph -->
                    <div class="dest-col col-text">
                        <p class="dest-para"
                            data-en="Dunhinda Falls, about 5 kilometers from town, is one of Sri Lanka's most beautiful waterfalls. The 64-meter cascade creates misty spray resembling a veil of smoke, giving the falls their evocative name."
                            data-si="නගරයෙන් කිලෝමීටර් 5ක් පමණ දුරින් ඇති දුන්හිඳ ඇල්ල, ශ්‍රී ලංකාවේ වඩාත්ම සුන්දර දිය ඇලිවලින් එකකි. මීටර් 64ක කාස්කේඩ්, දුකගෙනෙ නාමය ලබා ගෙන, දුමෙකේ තිරයකට සමාන මීදුම් ස්ප්‍රේ නිර්මාණය කරයි."
                            data-ta="Dunhinda Falls, ongeveer 5 kilometer van het stadje, is een van de mooiste watervallen van Sri Lanka. De 64 meter hoge cascade creëert mistspray die lijkt op een rookgordijn, waardoor de waterval zijn evocatieve naam krijgt.">Dunhinda Falls, about 5 kilometers from town, is one of Sri Lanka's most beautiful waterfalls. The 64-meter cascade creates misty spray resembling a veil of smoke, giving the falls their evocative name.</p>
                        <p class="dest-para"
                            data-en="Badulla offers authentic hill country life away from touristy destinations. The bustling market, friendly locals, and surrounding natural beauty make it worthwhile for travelers discovering the island's interior gems."
                            data-si="බදුල්ල, සංචාරකයින්ගෙන් ඈත ස්ථානවලින් සත්‍ය කඳුකර ජීවිතය ලබා දෙයි. ක්‍රියාශීලී වෙළඳ පොළ, මිත්‍රශීලී ප්‍රාදේශිකයන් සහ අවට ස්වාභාවික සෞන්දර්යය, දූපතේ අභ්‍යන්තර මැණිකු සොයන සංචාරකයින්ට එය වටිනා කරයි."
                            data-ta="Badulla biedt authentiek heuvellandleven, weg van toeristische bestemmingen. De drukke markt, vriendelijke lokale bewoners en omliggende natuurlijke schoonheid maken het de moeite waard voor reizigers die de binnenlandse juwelen van het eiland ontdekken.">Badulla offers authentic hill country life away from touristy destinations. The bustling market, friendly locals, and surrounding natural beauty make it worthwhile for travelers discovering the island's interior gems.</p>
                    </div>

                    <!-- Right 60%: 3 images -->
                    <div class="dest-col col-imgs">
                        <div class="triple-imgs">
                            <div class="tri-img tri-img--sm">
                                <img src="https://images.unsplash.com/photo-1501854140801-50d01698950b?w=400&q=80"
                                    alt="BADULLA" />
                            </div>
                            <div class="tri-img tri-img--wide">
                                <img src="https://images.unsplash.com/photo-1552832230-c0197dd311b5?w=600&q=80"
                                    alt="BADULLA" />
                            </div>
                            <div class="tri-img tri-img--sm">
                                <img src="https://images.unsplash.com/photo-1519681393784-d120267933ba?w=400&q=80"
                                    alt="BADULLA" />
