        <!-- ════════════════════════════════
         CARD 36 — AVUKANA BUDDHA STATUE
         Row 1: 60% text LEFT | 40% img RIGHT
         Row 2: 60% 3-images LEFT | 40% para RIGHT
    ════════════════════════════════ -->
        <div class="dest-card">
            <div class="dest-inner">

                <!-- ROW 1 -->
                <div class="dest-row row1-card2">

                    <!-- Left 60%: label + title + paragraphs -->
                    <div class="dest-col col-text">
                        <p class="dest-label"
                            data-en="AVUKANA BUDDHA STATUE"
                            data-si="අවුකන බුද්ධ ප්‍රතිමාව"
                            data-ta="AVUKANA BOEDDHASTANDBEELD">AVUKANA BUDDHA STATUE</p>
                        <h2 class="dest-title"
                            data-en="Avukana Buddha <em>Statue</em>"
                            data-si="අවුකන බුද්ධ <em>ප්‍රතිමාව</em>"
                            data-ta="Avukana Boeddha <em>Standbeeld</em>">Avukana Buddha <em>Statue</em></h2>
                        <p class="dest-para"
                            data-en="The Avukana Buddha Statue is a magnificent standing Buddha carved from a single granite rock face near Kala Wewa reservoir. Standing approximately 12 meters tall, it is one of the finest examples of ancient Sinhalese sculpture."
                            data-si="අවුකන බුද්ධ ප්‍රතිමාව, කලා වැව ජලාශයට ආසන්නයේ ඇති තනි ග්‍රැනයිට් ශිලා මතු‍ ුපරිතලයකින් කැටයම් කරන ලද රාජකීය ස්ථාවර බුද්ධ ප්‍රතිමාවකි. මීටර් 12ක් පමණ උස, එය පුරාණ සිංහල ශිල්ප නිදර්ශනවලින් ශ්‍රේෂ්ඨතමයන්ගෙන් එකක් වෙයි."
                            data-ta="Het Avukana Boeddhastandbeeld is een prachtig staand Boeddha-beeld, uitgehouwen uit een enkel granieten rotsoppervlak nabij het Kala Wewa-reservoir. Ongeveer 12 meter hoog, is het een van de mooiste voorbeelden van oude Singalese beeldhouwkunst.">The Avukana Buddha Statue is a magnificent standing Buddha carved from a single granite rock face near Kala Wewa reservoir. Standing approximately 12 meters tall, it is one of the finest examples of ancient Sinhalese sculpture.</p>
                        <p class="dest-para"
                            data-en="Believed created in the 5th century during King Dhatusena's reign, it depicts Buddha in Ashivaaka Mudra with right hand raised in blessing and left hand holding the robe. Intricate details and serene expression are remarkable."
                            data-si="ධාතුසේන රජුගේ රාජ්‍ය සමයේ 5 වැනි සියවසේ නිර්මාණය කළ බව විශ්වාස කෙරෙන, එය දකුණු අත ආශීර්වාදයෙන් ඉහළ ලූ හා වම් අතින් සිවුර රඳවා ගෙන ඇශිවාකා මුද්‍රාවෙහි බුදු රජාණන් නිරූපනය කරයි. සියුම් විස්තර සහ සන්සුන් ශ්‍රී ලාංෙද්‍රෂ්ටිය ආශ්චර්යයජනකයි."
                            data-ta="Naar men aanneemt gecreëerd in de 5e eeuw tijdens het bewind van koning Dhatusena, toont het Boeddha in Ashivaaka Mudra met rechterhand opgeheven in zegen en linkerhand die de mantel vasthoudt. Ingewikkelde details en serene uitdrukking zijn opmerkelijk.">Believed created in the 5th century during King Dhatusena's reign, it depicts Buddha in Ashivaaka Mudra with right hand raised in blessing and left hand holding the robe. Intricate details and serene expression are remarkable.</p>
                        <p class="dest-para"
                            data-en="What makes Avukana unique is that it is carved in the round but remains attached to the rock face at the back. Sculptors achieved perfect proportions with height exactly nine times the head length, following classical Buddhist iconography."
                            data-si="අවුකන ප්‍රතිමාව අනන්‍ය කරන්නේ, එය රවුමෙහි කැටයම් කළ නමුත් පිටුපස ශිලා මතු‍ ුපරිතලයට සම්බන්ධව ඉතිරිව ඇති බවය. ශිල්පීහු, සම්භාව්‍ය බෞද්ධ ශිල්ප නිරූපකශාස්ත්‍රය අනුගමනය කරමින්, හිස් දිගෙන් ගුණ 9ක් හරියටම ශරීරයේ උසින් යුත් පරිපූර්ණ සාමනේ ළඟා කළහ."
                            data-ta="Wat Avukana uniek maakt, is dat het in de ronde is uitgehouwen maar aan de achterkant verbonden blijft met het rotsoppervlak. Beeldhouwers bereikten perfecte proporties waarbij de hoogte precies negen keer de hoofdlengte is, overeenkomstig de klassieke boeddhistische iconografie.">What makes Avukana unique is that it is carved in the round but remains attached to the rock face at the back. Sculptors achieved perfect proportions with height exactly nine times the head length, following classical Buddhist iconography.</p>
                    </div>

                    <!-- Right 40%: single image -->
                    <div class="dest-col col-img">
                        <div class="main-img-wrap">
                            <img src="https://images.unsplash.com/photo-1506905925346-21bda4d32df4?w=700&q=80"
                                alt="AVUKANA BUDDHA STATUE" />
                        </div>
                    </div>

                </div>

                <!-- ROW 2 -->
                <div class="dest-row row2-card2">

                    <!-- Left 60%: 3 images -->
                    <div class="dest-col col-imgs">
                        <div class="triple-imgs">
                            <div class="tri-img tri-img--sm">
                                <img src="https://images.unsplash.com/photo-1464822759023-fed622ff2c3b?w=400&q=80"
                                    alt="AVUKANA BUDDHA STATUE" />
                            </div>
                            <div class="tri-img tri-img--wide">
                                <img src="https://images.unsplash.com/photo-1582510003544-4d00b7f74220?w=600&q=80"
                                    alt="AVUKANA BUDDHA STATUE" />
                            </div>
                            <div class="tri-img tri-img--sm">
                                <img src="https://images.unsplash.com/photo-1567620905732-2d1ec7ab7445?w=400&q=80"
                                    alt="AVUKANA BUDDHA STATUE" />
                            </div>
                        </div>
                    </div>

                    <!-- Right 40%: paragraph -->
                    <div class="dest-col col-text">
                        <p class="dest-para"
                            data-en="The statue faces Kala Wewa tank, and legend says it was carved in competition between a master sculptor and his pupil. The master completed this statue while the pupil created the Sasseruwa Buddha nearby."
                            data-si="ප්‍රතිමාව කලා වැව දෙස බලා සිටින අතර, ජනප්‍රවාද අනුව ගුරු ශිල්පියෙකු සහ ඔහුගේ ශිෂ්‍යයා අතර තරඟකාරීව කැටයම් කරන ලද බව කියැවේ. ශිෂ්‍යයා ආසන්නයේ සාස්සේරුව බුදු ප්‍රතිමාව නිර්මාණය කරද්දී, ගුරුවරයා මෙම ප්‍රතිමාව සම්පූර්ණ කළේය."
                            data-ta="Het standbeeld kijkt uit op het Kala Wewa-reservoir, en de legende vertelt dat het werd uitgehouwen in een wedstrijd tussen een meesterbeeldhouwer en zijn leerling. De meester voltooide dit beeld terwijl de leerling de nabijgelegen Sasseruwa-Boeddha maakte.">The statue faces Kala Wewa tank, and legend says it was carved in competition between a master sculptor and his pupil. The master completed this statue while the pupil created the Sasseruwa Buddha nearby.</p>
                        <p class="dest-para"
                            data-en="The Avukana Buddha Statue testifies to extraordinary artistic and engineering skills of ancient Sri Lanka. Its serene presence and beautiful rural setting make it deeply moving for Buddhists and art admirers alike."
                            data-si="අවුකන බුද්ධ ප්‍රතිමාව, පුරාණ ශ්‍රී ලංකාවේ අසාමාන්‍ය කලාත්මක හා ඉංජිනේරු කෞශල්‍යකට සාක්ෂි දරයි. එහි සන්සුන් ප්‍රකාශනය සහ සුන්දර ග්‍රාමීය සැකැස්ම, බෞද්ධයින්ට හා කලා ප්‍රේමීන්ට සමානව ගැඹුරු සිත් සසල කිරීමක් ලබා දෙයි."
                            data-ta="Het Avukana Boeddhastandbeeld getuigt van de buitengewone artistieke en ingenieursvaardigheid van het oude Sri Lanka. Zijn serene aanwezigheid en prachtige landelijke omgeving maken het diep ontroerend voor zowel boeddhisten als kunstliefhebbers.">The Avukana Buddha Statue testifies to extraordinary artistic and engineering skills of ancient Sri Lanka. Its serene presence and beautiful rural setting make it deeply moving for Buddhists and art admirers alike.</p>
                    </div>

                </div>

            </div>
        </div>

        <!-- ════════════════════════════════
         CARD 37 — MUNNESWARAM TEMPLE
         Row 1: 40% img LEFT | 60% text RIGHT
         Row 2: 40% para LEFT | 60% 3-images RIGHT
    ════════════════════════════════ -->
        <div class="dest-card">
            <div class="dest-inner">

                <!-- ROW 1 -->
                <div class="dest-row row1-card1">

                    <!-- Left 40%: single image -->
                    <div class="dest-col col-img">
                        <div class="main-img-wrap">
                            <img src="https://images.unsplash.com/photo-1533050487297-09b450131914?w=700&q=80"
                                alt="MUNNESWARAM TEMPLE" />
                        </div>
                    </div>

                    <!-- Right 60%: label + title + paragraphs -->
                    <div class="dest-col col-text">
                        <p class="dest-label"
                            data-en="MUNNESWARAM TEMPLE"
                            data-si="මුන්නේශ්වරම් දේවාලය"
                            data-ta="MUNNESWARAM TEMPEL">MUNNESWARAM TEMPLE</p>
                        <h2 class="dest-title"
                            data-en="Munneswaram <em>Hindu Temple</em>"
                            data-si="මුන්නේශ්වරම් <em>හින්දු දේවාලය</em>"
                            data-ta="Munneswaram <em>Hindoetempel</em>">Munneswaram <em>Hindu Temple</em></h2>
                        <p class="dest-para"
                            data-en="The Munneswaram Temple is an important Hindu temple complex in Chilaw on Sri Lanka's west coast. It is one of five ancient Ishwarams dedicated to Shiva, attracting devotees from across the island for over a thousand years."
                            data-si="මුන්නේශ්වරම් දේවාලය ශ්‍රී ලංකාවේ බටහිර වෙරළ තීරයේ ඇති චිලාවේ වැදගත් හින්දු ශාසන සංකීර්ණයකි. ශිව දෙවියන්ට කැප කරන ලද පුරාතන ඊශ්වරම් පහෙන් එකක් වන අතර, වසර දහසකට වැඩි කාලයක් දූපත පුරා භක්තිකයන් ආකර්ෂණය කරයි."
                            data-ta="De Munneswaram-tempel is een belangrijk hindoetempelcomplex in Chilaw aan de westkust van Sri Lanka. Het is een van de vijf oude Ishwarams gewijd aan Shiva en trekt al meer dan duizend jaar gelovigen van over het hele eiland aan.">The Munneswaram Temple is an important Hindu temple complex in Chilaw on Sri Lanka's west coast. It is one of five ancient Ishwarams dedicated to Shiva, attracting devotees from across the island for over a thousand years.</p>
                        <p class="dest-para"
                            data-en="Legend associates the temple with the Ramayana epic. Lord Rama, after defeating Ravana, stopped here and installed a lingam to absolve himself of killing a Brahmin, adding to its religious significance."
                            data-si="ජනශ්‍රුති රාමායණ කාව්‍ය ග්‍රන්ථය සමඟ ශාසනය සම්බන්ධ කරයි. රාම ලාංකිකයා රාවණා පරාජය කළ පසු, ජ‍ාති හිතෙකු ඝාතනය කළ සිය පාපය ප‍‍ිරිදිය කර ගනු වස් මෙහිදී ලිංගම් (ශිව ලිංග) ස්ථාපිත කළ, එමඟින් ආගමික වැදගත්කම වැඩිවිය."
                            data-ta="De legende associeert de tempel met het Ramayana-epos. Heer Rama stopte hier na het verslaan van Ravana en installeerde een lingam om zichzelf vrij te pleiten van het doden van een Brahmin, wat bijdraagt aan de religieuze betekenis ervan.">Legend associates the temple with the Ramayana epic. Lord Rama, after defeating Ravana, stopped here and installed a lingam to absolve himself of killing a Brahmin, adding to its religious significance.</p>
                        <p class="dest-para"
                            data-en="The complex consists of several shrines with the main one dedicated to Lord Shiva. Architecture features intricate carvings, colorful gopurams, and beautifully decorated halls famous for the annual chariot festival."
                            data-si="සංකීර්ණය ශිව දෙවියන්ට කැප කරන ලද ප්‍රධාන ශාලාව සහිතව පූජා ස්ථාන කිහිපයකින් සමන්විත වෙයි. ගෘහ නිර්මාණ ශිල්පයේ සියුම් කැටයම්, වර්ණවත් ගෝපුරම් සහ වාර්ෂික රථ මහෝත්සවය සඳහා ප්‍රසිද්ධ ලස්සනට සැරසූ ශාලා ඇත."
                            data-ta="Het complex bestaat uit verscheidene heiligdommen, waarbij het hoofdheiligdom gewijd is aan Heer Shiva. De architectuur heeft ingewikkelde houtsnijwerken, kleurrijke gopurams en prachtig versierde zalen, beroemd om het jaarlijkse wagenfeest.">The complex consists of several shrines with the main one dedicated to Lord Shiva. Architecture features intricate carvings, colorful gopurams, and beautifully decorated halls famous for the annual chariot festival.</p>
                    </div>

                </div>

                <!-- ROW 2 -->
                <div class="dest-row row2-card1">

                    <!-- Left 40%: paragraph -->
                    <div class="dest-col col-text">
                        <p class="dest-para"
                            data-en="The temple is also known for Munneswaram Pattini Devale dedicated to goddess Pattini, revered by both Hindus and Buddhists. This shared veneration reflects the religious harmony characterizing Sri Lankan society."
                            data-si="මෙම විහාරස්ථානය හින්දු සහ බෞද්ධ යන දෙපිරිසගේම ගෞරවයට පාත්‍ර වූ පත්තිනි දේවතාවිය වෙනුවෙන් කැප කරන ලද මුන්නේෂ්වරම් පත්තිනි දේවාලය සඳහා ද ප්‍රසිද්ධය. මෙම පොදු භක්තිය ශ්‍රී ලාංකික සමාජයේ ලක්ෂණයක් වන ආගමික සමගිය පිළිබිඹු කරයි."
                            data-ta="De tempel is ook bekend om Munneswaram Pattini Devale, gewijd aan de godin Pattini, die zowel door Hindus als Boedhists vereerd wordt. Deze gedeelde vereering weerspiegelt de religieuze harmonie die het Sri Lankaanse maatschappij kenmerkt.">The temple is also known for Munneswaram Pattini Devale dedicated to goddess Pattini, revered by both Hindus and Buddhists. This shared veneration reflects the religious harmony characterizing Sri Lankan society.</p>
                        <p class="dest-para"
                            data-en="Located near Chilaw lagoon, the temple offers a peaceful setting with temple bells and incense filling the air. The combination of religious significance, architectural beauty, and coastal location makes it unique."
                            data-si="හලාවත කලපුව අසල පිහිටා ඇති මෙම විහාරස්ථානය, විහාරස්ථාන සීනු සහ සුවඳ දුම් නාදයෙන් වාතය පුරවා ගනිමින් සාමකාමී පරිසරයක් ලබා දෙයි. ආගමික වැදගත්කම, ගෘහ නිර්මාණ ශිල්පීය අලංකාරය සහ වෙරළබඩ පිහිටීම යන සංකලනය එය අද්විතීය කරයි."
                            data-ta="Gelegenheidens near Chilaw lagoon, biedt de tempel een rustige omgeving met tempelbellen en geurige stenen die de lucht vullen. De combinatie van religieuze betekenis, architectonische schoonheid en de kustlocatie maakt het uniek.">Located near Chilaw lagoon, the temple offers a peaceful setting with temple bells and incense filling the air. The combination of religious significance, architectural beauty, and coastal location makes it unique.</p>
                    </div>

                    <!-- Right 60%: 3 images -->
                    <div class="dest-col col-imgs">
                        <div class="triple-imgs">
                            <div class="tri-img tri-img--sm">
                                <img src="https://images.unsplash.com/photo-1501854140801-50d01698950b?w=400&q=80"
                                    alt="MUNNESWARAM TEMPLE" />
                            </div>
                            <div class="tri-img tri-img--wide">
                                <img src="https://images.unsplash.com/photo-1552832230-c0197dd311b5?w=600&q=80"
