        <!-- ════════════════════════════════
         CARD 38 — GALLE FACE GREEN
         Row 1: 60% text LEFT | 40% img RIGHT
         Row 2: 60% 3-images LEFT | 40% para RIGHT
    ════════════════════════════════ -->
        <div class="dest-card">
            <div class="dest-inner">

                <!-- ROW 1 -->
                <div class="dest-row row1-card2">

                    <!-- Left 60%: label + title + paragraphs -->
                    <div class="dest-col col-text">
                        <p class="dest-label"
                        data-en="GALLE FACE GREEN"
                        data-si="ගාලු මුවදොර පිටිය"
                        data-ta="GALLE GEZICHT GROEN">GALLE FACE GREEN</p>
                        <h2 class="dest-title"
                        data-en="Galle Face <em>Green</em>"
                        data-si="ගාලු මුවදොර <em>පිටිය</em>"
                        data-ta="Galle Gezicht <em>Groen</em>">Galle Face <em>Green</em></h2>
                        <p class="dest-para"
                        data-en="Galle Face Green is a 5-hectare ocean-side urban park in the heart of Colombo, stretching along the coast between Galle Road and the Indian Ocean. It is the city's largest open space and beloved gathering place."
                        data-si="ගාලු මුවදොර පිටිය යනු කොළඹ නගර මධ්‍යයේ පිහිටි හෙක්ටයාර 5 ක සාගර පැත්තේ නාගරික උද්‍යානයක් වන අතර එය ගාලු පාර සහ ඉන්දියන් සාගරය අතර වෙරළ තීරය දිගේ විහිදේ. එය නගරයේ විශාලතම විවෘත අවකාශය සහ ආදරණීය රැස්වීම් ස්ථානයයි."
                        data-ta="Galle Gezicht Groen is een 5 hectare groot stadspark aan de oceaan in het hart van Colombo, dat zich uitstrekt langs de kust tussen Galle Road en de Indische Oceaan. Het is de grootste openbare ruimte van de stad en een geliefde ontmoetingsplek.">Galle Face Green is a 5-hectare ocean-side urban park in the heart of Colombo, stretching along the coast between Galle Road and the Indian Ocean. It is the city's largest open space and beloved gathering place.</p>
                        <p class="dest-para"
                        data-en="Originally created by the British in 1859 as a horse racing course and golf ground, it has evolved into Colombo's most popular public space. Families and friends flock here evenings to fly kites and enjoy street food."
                        data-si="මුලින් බ්‍රිතාන්‍යයන් විසින් 1859 දී තුරඟ තරඟ පිටියක් සහ ගොල්ෆ් පිටියක් ලෙස නිර්මාණය කරන ලද එය කොළඹ ජනප්‍රියම පොදු අවකාශය බවට පරිණාමය වී ඇත. සරුංගල් යැවීමට සහ වීදි ආහාර භුක්ති විඳීමට පවුලේ අය සහ මිතුරන් සවස් වරුවේ මෙහි පැමිණේ."
                        data-ta="Oorspronkelijk aangelegd door de Britten in 1859 als paardenrenbaan en golfbaan, is het uitgegroeid tot de populairste openbare ruimte van Colombo. Families en vrienden komen er 's avonds massaal naartoe om te vliegeren en te genieten van het straatvoedsel.">Originally created by the British in 1859 as a horse racing course and golf ground, it has evolved into Colombo's most popular public space. Families and friends flock here evenings to fly kites and enjoy street food.</p>
                        <p class="dest-para"
                        data-en="The promenade is lined with vendors selling isso wade, a popular lentil patty topped with whole prawns. The salty breeze, sound of waves, and vibrant atmosphere create an experience quintessentially Colombo."
                        data-si="පිටිය, ඉස්සන් වලින් සරසා ඇති ජනප්‍රිය ආහාර වර්ගයක් වන ඉස්සෝ වඩේ විකුණන වෙළෙන්දන්ගෙන් පිරී ඇත. ලුණු සහිත සුළඟ, රළ පහරවල්වල ශබ්දය සහ සජීවී වාතාවරණය කොළඹට අනන්‍ය අත්දැකීමක් නිර්මාණය කරයි."
                        data-ta="De boulevard is bezaaid met kraampjes waar isso wade wordt verkocht, een populaire linzenpastei met hele garnalen. De zilte zeebries, het geluid van de golven en de levendige sfeer zorgen voor een typische Colombo-ervaring.">The promenade is lined with vendors selling isso wade, a popular lentil patty topped with whole prawns. The salty breeze, sound of waves, and vibrant atmosphere create an experience quintessentially Colombo.</p>
                    </div>

                    <!-- Right 40%: single image -->
                    <div class="dest-col col-img">
                        <div class="main-img-wrap">
                            <img src="https://images.unsplash.com/photo-1506905925346-21bda4d32df4?w=700&q=80"
                                alt="GALLE FACE GREEN" />
                        </div>
                    </div>

                </div>

                <!-- ROW 2 -->
                <div class="dest-row row2-card2">

                    <!-- Left 60%: 3 images -->
                    <div class="dest-col col-imgs">
                        <div class="triple-imgs">
                            <div class="tri-img tri-img--sm">
                                <img src="https://images.unsplash.com/photo-1464822759023-fed622ff2c3b?w=400&q=80"
                                    alt="GALLE FACE GREEN" />
                            </div>
                            <div class="tri-img tri-img--wide">
                                <img src="https://images.unsplash.com/photo-1582510003544-4d00b7f74220?w=600&q=80"
                                    alt="GALLE FACE GREEN" />
                            </div>
                            <div class="tri-img tri-img--sm">
                                <img src="https://images.unsplash.com/photo-1567620905732-2d1ec7ab7445?w=400&q=80"
                                    alt="GALLE FACE GREEN" />
                            </div>
                        </div>
                    </div>

                    <!-- Right 40%: paragraph -->
                    <div class="dest-col col-text">
                        <p class="dest-para"
                        data-en="The green is flanked by iconic buildings including the Galle Face Hotel, one of Asia's oldest hotels, and modern Shangri-La Colombo. The contrast between colonial architecture and skyscrapers captures Sri Lanka's evolving identity."
                        data-si="ආසියාවේ පැරණිතම හෝටල්වලින් එකක් වන ගාලු මුවදොර හෝටලය සහ නවීන ෂැන්ග්‍රි-ලා කොළඹ ඇතුළු සංකේතාත්මක ගොඩනැගිලි වලින් හරිත පැහැය දෙපස පිහිටා ඇත. යටත් විජිත ගෘහ නිර්මාණ ශිල්පය සහ අහස උසට වැඩෙන ගොඩනැගිලි අතර වෙනස ශ්‍රී ලංකාවේ පරිණාමය වන අනන්‍යතාවය ග්‍රහණය කරයි."
                        data-ta="Het groene plein wordt geflankeerd door iconische gebouwen, waaronder het Galle Face Hotel, een van de oudste hotels van Azië, en het moderne Shangri-La Colombo. Het contrast tussen koloniale architectuur en wolkenkrabbers weerspiegelt de evoluerende identiteit van Sri Lanka.">The green is flanked by iconic buildings including the Galle Face Hotel, one of Asia's oldest hotels, and modern Shangri-La Colombo. The contrast between colonial architecture and skyscrapers captures Sri Lanka's evolving identity.</p>
                        <p class="dest-para"
                        data-en="In recent years Galle Face Green has become a symbol of civic engagement, hosting protests, celebrations, and public gatherings. It remains Colombo's beating heart where diverse communities come together to relax and rejoice."
                        data-si="මෑත වසරවලදී ගාලු මුවදොර පිටිය සිවිල් සහභාගීත්වයේ සංකේතයක් බවට පත්ව ඇති අතර, විරෝධතා, සැමරුම් සහ මහජන රැස්වීම් සඳහා සත්කාරකත්වය සපයයි. විවිධ ප්‍රජාවන් විවේක ගැනීමට සහ ප්‍රීති වීමට එක්වන කොළඹ ස්පන්දනීය හදවත එය ලෙස පවතී."
                        data-ta="Galle Gezicht Groen is de afgelopen jaren uitgegroeid tot een symbool van burgerparticipatie, een plek waar protesten, vieringen en openbare bijeenkomsten plaatsvinden. Het blijft het kloppende hart van Colombo, waar diverse gemeenschappen samenkomen om te ontspannen en te genieten.">In recent years Galle Face Green has become a symbol of civic engagement, hosting protests, celebrations, and public gatherings. It remains Colombo's beating heart where diverse communities come together to relax and rejoice.</p>
                    </div>

                </div>

            </div>
        </div>

        <!-- ════════════════════════════════
         CARD 39 — PIDURANGALA ROCK
         Row 1: 40% img LEFT | 60% text RIGHT
         Row 2: 40% para LEFT | 60% 3-images RIGHT
    ════════════════════════════════ -->
        <div class="dest-card">
            <div class="dest-inner">

                <!-- ROW 1 -->
                <div class="dest-row row1-card1">

                    <!-- Left 40%: single image -->
                    <div class="dest-col col-img">
                        <div class="main-img-wrap">
                            <img src="https://images.unsplash.com/photo-1533050487297-09b450131914?w=700&q=80"
                                alt="PIDURANGALA ROCK" />
                        </div>
                    </div>

                    <!-- Right 60%: label + title + paragraphs -->
                    <div class="dest-col col-text">
                        <p class="dest-label"
                        data-en="PIDURANGALA ROCK"
                        data-si="පිදුරංගල පර්වතය"
                        data-ta="PIDURANGALA ROCK">PIDURANGALA ROCK</p>
                        <h2 class="dest-title"
                        data-en="Pidurangala <em>Rock View</em>"
                        data-si="පිදුරංගල පර්වත දස්සල"
                        data-ta="Pidurangala <em>Rock View</em>">Pidurangala <em>Rock View</em></h2>
                        <p class="dest-para"
                        data-en="Pidurangala Rock is a massive formation just north of Sigiriya offering spectacular views of the Lion Rock from its summit. While Sigiriya draws crowds, Pidurangala provides a more adventurous and less crowded alternative."
                        data-si="පිදුරංගල පර්වතය යනු සීගිරියට උතුරින් පිහිටි දැවැන්ත නිර්මාණයක් වන අතර එහි මුදුනේ සිට සිංහ පර්වතයේ දර්ශනීය දසුන් ලබා දෙයි. සීගිරිය ජනකායක් ආකර්ෂණය කර ගන්නා අතර, පිදුරංගල වඩාත් වික්‍රමාන්විත හා අඩු ජනාකීර්ණ විකල්පයක් සපයයි."
                        data-ta="De Pidurangala-rots is een enorme rotsformatie net ten noorden van Sigiriya en biedt vanaf de top een spectaculair uitzicht op de Leeuwenrots. Terwijl Sigiriya veel bezoekers trekt, is Pidurangala een avontuurlijker en minder druk alternatief.">Pidurangala Rock is a massive formation just north of Sigiriya offering spectacular views of the Lion Rock from its summit. While Sigiriya draws crowds, Pidurangala provides a more adventurous and less crowded alternative.</p>
                        <p class="dest-para"
                        data-en="The hike to the top takes 30 to 45 minutes over boulders and through forest. Halfway up, hikers pass an ancient temple with a reclining Buddha statue from a monastery dating to King Kashyapa's time."
                        data-si="මුදුනට නැගීමට ගල් පර්වත හරහා සහ වනාන්තරය හරහා මිනිත්තු 30 සිට 45 දක්වා කාලයක් ගතවේ. අඩක් ඉහළට යන විට, කඳු නගින්නන් කාශ්‍යප රජුගේ කාලයට අයත් ආරාමයකින් සැතපෙන බුද්ධ ප්‍රතිමාවක් සහිත පුරාණ විහාරස්ථානයක් පසුකර යයි."
                        data-ta="De wandeling naar de top duurt 30 tot 45 minuten en voert over rotsblokken en door het bos. Halverwege passeren wandelaars een oude tempel met een liggend Boeddhabeeld, afkomstig uit een klooster dat dateert uit de tijd van koning Kashyapa.">The hike to the top takes 30 to 45 minutes over boulders and through forest. Halfway up, hikers pass an ancient temple with a reclining Buddha statue from a monastery dating to King Kashyapa's time.</p>
                        <p class="dest-para"
                        data-en="The summit offers unobstructed 360-degree views of surrounding countryside with Sigiriya rising majestically in the distance. The view is particularly stunning at sunrise when morning light paints the landscape gold and pink."
                        data-si="සීගිරිය ඈතින් තේජාන්විතව නැඟී සිටින අතර, අවට ග්‍රාමීය ප්‍රදේශයේ අංශක 360 ක බාධාවකින් තොරව දර්ශන කඳු මුදුනෙන් ලබා ගත හැකිය. උදෑසන ආලෝකය භූ දර්ශනය රන්වන් සහ රෝස පැහැයෙන් වර්ණ ගන්වන විට හිරු උදාවේදී දර්ශනය විශේෂයෙන් විශ්මයජනකයි."
                        data-ta="De top biedt een onbelemmerd 360-graden uitzicht over het omliggende landschap, met Sigiriya dat majestueus in de verte oprijst. Het uitzicht is vooral adembenemend bij zonsopgang, wanneer het ochtendlicht het landschap goud en roze kleurt.">The summit offers unobstructed 360-degree views of surrounding countryside with Sigiriya rising majestically in the distance. The view is particularly stunning at sunrise when morning light paints the landscape gold and pink.</p>
                    </div>

                </div>

                <!-- ROW 2 -->
                <div class="dest-row row2-card1">

                    <!-- Left 40%: paragraph -->
                    <div class="dest-col col-text">
                        <p class="dest-para"
                        data-en="The rock is geologically similar to Sigiriya, formed from the same ancient volcanic activity. Its name translates to Offered Rock, referring to its historical use as a monastery for monks when Kasyapa moved his capital."
                        data-si="මෙම පර්වතය භූ විද්‍යාත්මකව සීගිරියට සමාන වන අතර එය එම පුරාණ ගිනිකඳු ක්‍රියාකාරකම් වලින් සෑදී ඇත. එහි නම 'පූජා කරන ලද පර්වතය' ලෙස පරිවර්තනය වේ, කාශ්‍යප සිය අගනුවර ගෙන යන විට භික්ෂූන් වහන්සේලා සඳහා ආරාමයක් ලෙස එහි ඓතිහාසික භාවිතය ගැන සඳහන් කරයි."
                        data-ta="De rots is geologisch vergelijkbaar met Sigiriya en is gevormd door dezelfde oude vulkanische activiteit. De naam betekent 'Geofferde Rots', verwijzend naar het historische gebruik als klooster voor monniken toen Kasjapa zijn hoofdstad verplaatste.">The rock is geologically similar to Sigiriya, formed from the same ancient volcanic activity. Its name translates to Offered Rock, referring to its historical use as a monastery for monks when Kasyapa moved his capital.</p>
                        <p class="dest-para"
                        data-en="For photographers and nature lovers, Pidurangala is essential. The combination of historical significance, natural beauty, and unbeatable views of one of Sri Lanka's most iconic landmarks makes it a Cultural Triangle must-visit."
                        data-si="ඡායාරූප ශිල්පීන්ට සහ සොබාදහමට ආදරය කරන්නන්ට පිදුරංගල අත්‍යවශ්‍යයි. ඓතිහාසික වැදගත්කම, ස්වාභාවික සුන්දරත්වය සහ ශ්‍රී ලංකාවේ වඩාත් කැපී පෙනෙන සන්ධිස්ථානයක අසමසම දසුන්වල එකතුව එය නැරඹිය යුතුම සංස්කෘතික ත්‍රිකෝණයක් බවට පත් කරයි."
                        data-ta="Voor fotografen en natuurliefhebbers is Pidurangala een absolute aanrader. De combinatie van historische betekenis, natuurlijke schoonheid en een ongeëvenaard uitzicht op een van Sri Lanka's meest iconische bezienswaardigheden maakt het een must-visit in de Culturele Driehoek.">For photographers and nature lovers, Pidurangala is essential. The combination of historical significance, natural beauty, and unbeatable views of one of Sri Lanka's most iconic landmarks makes it a Cultural Triangle must-visit.</p>
                    </div>

