        <div class="dest-card">
            <div class="dest-inner">

                <!-- ROW 1 -->
                <div class="dest-row row1-card2">

                    <!-- Left 60%: label + title + paragraphs -->
                    <div class="dest-col col-text">
                        <p class="dest-label"
                        data-en="SEETHA AMMAN TEMPLE"
                        data-si="සීතා අම්මාන් කෝවිල"
                        data-ta="SEETHA AMMAN TEMPEL">SEETHA AMMAN TEMPLE</p>
                        <h2 class="dest-title"
                        data-en="Seetha Amman <em>Temple</em>"
                        data-si="සීතා අම්මාන් <em>කෝවිල</em>"
                        data-ta="Sita Amman <em>Tempel</em>">Seetha Amman <em>Temple</em></h2>
                        <p class="dest-para"
                        data-en="The Seetha Amman Temple is a unique Hindu temple in Seetha Eliya near Nuwara Eliya. It is believed to mark where Sita, wife of Lord Rama, was held captive by demon king Ravana according to the Ramayana epic."
                        data-si="නුවරඑළිය අසල සීතාඑළියේ පිහිටි සීතා අම්මාන් කෝවිල අද්විතීය හින්දු කෝවිලකි. රාමායණ වීර කාව්‍යයට අනුව, රාම දෙවියන්ගේ බිරිඳ වන සීතා, රාවණා යක්ෂ රජු විසින් සිරකරගෙන සිටි ස්ථානය සනිටුහන් කිරීමට මෙය යැයි විශ්වාස කෙරේ."
                        data-ta="De Seetha Amman-tempel is een unieke hindoetempel in Seetha Eliya, vlakbij Nuwara Eliya. Men gelooft dat deze tempel de plek markeert waar Sita, de vrouw van Heer Rama, volgens het epos Ramayana gevangen werd gehouden door de demonenkoning Ravana.">The Seetha Amman Temple is a unique Hindu temple in Seetha Eliya near Nuwara Eliya. It is believed to mark where Sita, wife of Lord Rama, was held captive by demon king Ravana according to the Ramayana epic.</p>
                        <p class="dest-para"
                        data-en="Built at the foot of a hill beside a stream, legend says Sita bathed in these waters during captivity. Hanuman's footprints are said to be imprinted on a nearby rock, adding to the site's mythological significance."
                        data-si="දොළක් අසල කන්දක් පාමුල ඉදිකර ඇති මෙම ජනප්‍රවාදයේ සඳහන් වන්නේ සීතා දේවිය වහල්භාවයේ සිටියදී මෙම ජලයේ ස්නානය කළ බවයි. හනුමාන්ගේ පා ​​සලකුණු අසල ඇති පර්වතයක සටහන් වී ඇති බව කියනු ලබන අතර, එය මෙම ස්ථානයේ මිථ්‍යා වැදගත්කම වැඩි කරයි."
                        data-ta="De plek is gebouwd aan de voet van een heuvel naast een beekje. Volgens de legende baadde Sita in dit water tijdens haar gevangenschap. De voetafdrukken van Hanuman zouden in een nabijgelegen rots te zien zijn, wat bijdraagt ​​aan de mythologische betekenis van de locatie.">Built at the foot of a hill beside a stream, legend says Sita bathed in these waters during captivity. Hanuman's footprints are said to be imprinted on a nearby rock, adding to the site's mythological significance.</p>
                        <p class="dest-para"
                        data-en="The temple complex features colorful statues and shrines dedicated to Rama, Sita, Lakshmana, and Hanuman. Vibrant architecture and lush green surroundings create a serene atmosphere attracting devotees and curious travelers."
                        data-si="මෙම විහාර සංකීර්ණය රාම, සීතා, ලක්ෂ්මණ සහ හනුමාන් වෙනුවෙන් කැප කරන ලද වර්ණවත් ප්‍රතිමා සහ සිද්ධස්ථාන වලින් සමන්විත වේ. විචිත්‍රවත් ගෘහ නිර්මාණ ශිල්පය සහ සශ්‍රීක හරිත වටපිටාව බැතිමතුන් සහ කුතුහලයෙන් පිරි සංචාරකයින් ආකර්ෂණය කර ගන්නා සන්සුන් වාතාවරණයක් නිර්මාණය කරයි."
                        data-ta="Het tempelcomplex is rijk aan kleurrijke beelden en heiligdommen gewijd aan Rama, Sita, Lakshmana en Hanuman. De levendige architectuur en weelderige groene omgeving creëren een serene sfeer die zowel gelovigen als nieuwsgierige reizigers aantrekt.">The temple complex features colorful statues and shrines dedicated to Rama, Sita, Lakshmana, and Hanuman. Vibrant architecture and lush green surroundings create a serene atmosphere attracting devotees and curious travelers.</p>
