                    <div class="dest-col col-text">
                        <p class="dest-para"
                        data-en="The area has unusual soil formations with some rocks bearing what appear to be fossilized footprints. Local guides explain Ramayana connections, weaving together mythology, geology, and folklore into fascinating narratives."
                        data-si="මෙම ප්‍රදේශය අසාමාන්‍ය පස් සැකැස්මක් ඇති අතර සමහර පාෂාණවලින් ෆොසිලීකරණය වූ පා සටහන් ලෙස පෙනේ. දේශීය මාර්ගෝපදේශකයින් රාමායණ සම්බන්ධතා පැහැදිලි කරන අතර, මිථ්‍යා කථා, භූ විද්‍යාව සහ ජනප්‍රවාද එකට එකතු කර සිත් ඇදගන්නාසුළු ආඛ්‍යාන බවට පත් කරයි."
                        data-ta="Het gebied kent bijzondere bodemformaties, met op sommige rotsen wat lijkt op gefossiliseerde voetafdrukken. Lokale gidsen leggen de verbanden met de Ramayana uit en verweven mythologie, geologie en folklore tot fascinerende verhalen.">The area has unusual soil formations with some rocks bearing what appear to be fossilized footprints. Local guides explain Ramayana connections, weaving together mythology, geology, and folklore into fascinating narratives.</p>
                        <p class="dest-para"
                        data-en="Whether a Ramayana believer or simply interested in Sri Lanka's cultural tapestry, the temple offers a unique experience. Religious significance, natural beauty, and mythological intrigue make it a memorable hill country stop."
                        data-si="රාමායණ ඇදහිලිවන්තයෙකු හෝ ශ්‍රී ලංකාවේ සංස්කෘතික පටි ගැන උනන්දුවක් දක්වන අයෙකු වුවද, මෙම විහාරස්ථානය අද්විතීය අත්දැකීමක් ලබා දෙයි. ආගමික වැදගත්කම, ස්වාභාවික සුන්දරත්වය සහ මිථ්‍යා කථා කුතුහලය නිසා එය අමතක නොවන කඳුකර නැවතුමකි."
                        data-ta="Of je nu in de Ramayana gelooft of gewoon geïnteresseerd bent in de rijke cultuur van Sri Lanka, de tempel biedt een unieke ervaring. Religieuze betekenis, natuurlijke schoonheid en mythologische intriges maken het een onvergetelijke stop in het heuvelland.">Whether a Ramayana believer or simply interested in Sri Lanka's cultural tapestry, the temple offers a unique experience. Religious significance, natural beauty, and mythological intrigue make it a memorable hill country stop.</p>
